-- SRS review-card backfill — BATCH 9 of 10 (947 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('413d57da-1v','{"options": ["a Before the tests", "c After the management plan’", "b After conducting the necessary tests ‘", "d During the preliminary examination’"], "correct": 2, "explanation": "Diagnosis occurs AFTER the necessary tests are completed (you gather data, then conclude). It precedes the management plan and follows the testing — not before tests or during preliminaries. Logic: data first, then diagnosis, then plan."}'),
  ('f2bec7a9-28','{"options": ["a To detect eye color ,", "c To investigate visual functions and needs ,", "b To record the patient''s family history ,", "d To offer a management plan,"], "correct": 1, "explanation": "The VISUAL FUNCTION assessment exists to INVESTIGATE visual functions and the patient''s visual NEEDS (accommodation, binocularity, etc.) — beyond just acuity. It isn''t for eye color, history-taking, or the management plan. Function assessment = probe how the visual system performs."}'),
  ('d8755530-2a','{"options": ["a Hyperopia;.", "c Ocular motility deficiencies ;.", "b Astigmatism;.", "d Diplopia;."], "correct": 1, "explanation": "Excessive HEAD MOVEMENT while reading (moving the head instead of the eyes) signals OCULAR MOTILITY deficiencies (poor saccades/pursuit) — the patient compensates for weak eye movements. Refractive errors blur; motility problems disrupt tracking. Head-moves-not-eyes = oculomotor dysfunction."}'),
  ('1b304e9d-2t','{"options": [";a) Myopia", ";c) Accommodative deficiency", ";b) Presbyopia", ";d) Ocular motility deficiency"], "correct": 1, "explanation": "Eye pain/headache AFTER PROLONGED near reading points to an ACCOMMODATIVE deficiency (the focusing system fatigues with sustained near demand). Myopia blurs distance; presbyopia is age-related near loss; motility causes tracking issues. Near-task asthenopia in a non-presbyope = accommodative."}'),
  ('1b1df39a-2i','{"options": ["a Penlight,.,", "c Phoropter,.,", "b Trial frame ,.,", "d Ophthalmoscope,.,"], "correct": 0, "explanation": "The CATOPTRIC (corneal-reflex) PD method uses a PENLIGHT with the mm rule — you measure between the corneal light reflexes (more accurate, uses the visual axis) rather than pupil/limbus edges. Phoropter/trial frame/ophthalmoscope aren''t the catoptric tools. Catoptric = reflex-based, penlight + rule."}'),
  ('b24cd4b5-2c','{"options": ["a Use the center of the cornea for measurement’;", "b Use the center of the pupils for measurement ‘;", "c Measure the outer edges of the pupils’;", "d Avoid measuring the PD in such cases’;"], "correct": 1, "explanation": "With ANISOCORIA (unequal pupils), measure PD using the CENTER of each PUPIL (the functional optical center), accepting the asymmetry, rather than corneal center or pupil edges. Centering on the pupils preserves accurate monocular PDs. Anisocoria → still use pupil centers."}'),
  ('2bfbf7eb-1a','{"options": ["1-2 mm -", "4-6 mm -", "2-4 mm -", "6-8 mm-"], "correct": 2, "explanation": "Average pupil size in BRIGHT light ≈ 2-4 mm (constricted). In dim light it dilates to ~4-8 mm. So 2-4 mm photopic is normal; 5 mm in bright light would be abnormally large (Q37). Photopic pupil ≈ 2-4 mm."}'),
  ('25905f3a-1i','{"options": ["Ophthalmoscope ‘", "Retinoscope ‘", "Hemisphere scale ‘", "Slit lamp’"], "correct": 2, "explanation": "Pupil DIAMETER is gauged with a pupil gauge/HEMISPHERE (PD/pupil) scale held beside the eye (or a mm ruler/Rosenbaum card gauge). Ophthalmoscope/retinoscope/slit lamp assess other things. Pupil size = pupil gauge (hemisphere scale)."}'),
  ('8146e81d-1t','{"options": ["Normal pupil size.", "Mydriasis .", "Myosis.", "Anisocoria."], "correct": 1, "explanation": "A 5 mm pupil in BRIGHT light is abnormally large = MYDRIASIS (should be 2-4 mm photopic, Q35). Miosis is small; anisocoria is unequal sizes. Large-in-bright-light = mydriasis (e.g., drug, CN III, Adie)."}'),
  ('4090f5ad-i','{"options": ["Abnormally small pupils.,", "Dilated pupils due to myopia ,", "Unequal pupil sizes .,", "Constricted pupils in hyperopia.,"], "correct": 2, "explanation": "ANISOCORIA = UNEQUAL pupil sizes between the two eyes. (Not ''small pupils'' = miosis, not dilated = mydriasis.) Aniso = unequal; -coria = pupil. Work up by checking which pupil is abnormal in light vs dark."}'),
  ('e3729e9d-17','{"options": ["The health of the retina /", "The size of the pupil /", "The alignment of the eyes /", "The patient''s refractive error/"], "correct": 2, "explanation": "The FIXATION (corneal-reflex/cover) test assesses ocular ALIGNMENT — whether the eyes are straight or deviated (strabismus). It isn''t a retinal-health, pupil-size, or refraction test. Fixation/Hirschberg = alignment screen."}'),
  ('d10fa01c-20','{"options": ["0.5 mm temporal to the center of the pupil ‘", "0.5 mm nasal to the center of the pupil ‘", "1.0 mm temporal to the center of the pupil’", "At the center of the pupil’"], "correct": 1, "explanation": "Normally the corneal light reflex sits ~0.5 mm NASAL to the pupil center, reflecting the small positive angle kappa (the fovea is slightly temporal, so the visual axis crosses nasally). A markedly nasal or temporal reflex flags deviation (Q41). Normal = ~0.5 mm nasal reflex."}'),
  ('d281d620-2s','{"options": ["No deviation -.", "Exodeviation -.", "Esodeviation-.", "Normal alignment-."], "correct": 1, "explanation": "A reflex displaced extremely NASAL-ward = the eye is turned OUT (the cornea/reflex shifts nasally when the globe rotates temporally) = EXODEVIATION. (Conversely, a temporal reflex = esodeviation.) Consistent reflex rule: nasal reflex = exo, temporal reflex = eso."}'),
  ('f4160c86-32','{"options": ["Hirschberg method ‘;", "Maddox rod test ‘;", "Cover test’;", "Snellen chart test’;"], "correct": 0, "explanation": "The HIRSCHBERG method gives a crude estimate of the deviation angle in young/uncooperative patients from the corneal reflex position (~15° per mm / per pupil-zone). Maddox/cover need cooperation; Snellen is acuity. Hirschberg = quick corneal-reflex angle estimate."}'),
  ('9a14f0ef-3a','{"options": ["5°", "10°", "15°", "20°"], "correct": 2, "explanation": "Hirschberg: a reflex at the PUPILLARY MARGIN ≈ 15° of deviation (each ~mm from center ≈ 15°; margin ≈ 2 mm ≈ 15°). At the limbus ≈ 45°; mid-iris ≈ 30°. Reference scale: margin 15°, mid-iris 30°, limbus 45°."}'),
  ('5cca01ae-2j','{"options": ["Allen Pre-school Chart ,", "F fooks ,", "Lea symbol,"], "correct": 0, "explanation": "The ALLEN preschool chart (Allen pictures) uses 7 recognizable picture optotypes for young children who can''t read letters. Fooks and Lea symbols are other pediatric tests, but the ''7-plate picture'' description fits Allen. Pediatric picture acuity = Allen."}'),
  ('d06ff92b-3k','{"options": ["Cataract .", "Glaucoma .", "Migraine."], "correct": 1, "explanation": "Halos/RAINBOWS around lights classically signal corneal EDEMA from raised IOP = GLAUCOMA (especially acute angle closure). Cataract causes glare/scatter but the ''rainbow halo'' is the corneal-edema/glaucoma sign; migraine gives scintillating scotoma. Rainbow halos = corneal edema → think glaucoma."}'),
  ('b79eb8a1-1x','{"options": ["A central nervous system disorder -.", "Retinal involvement -.", "A psychogenic cause such as hysteria-.", "A corneal abnormality-."], "correct": 1, "explanation": "A SLUGGISH pupil to direct light suggests an afferent/RETINAL (or optic nerve) problem reducing the light signal — retinal involvement dampens the reflex. (A CNS/efferent lesion gives other patterns; hysteria/corneal issues don''t slow the reflex this way.) Sluggish direct response = afferent/retinal compromise."}'),
  ('5766f78a-2q','{"options": ["Green ,", "Red ,", "Blue,"], "correct": 0, "explanation": "[3 options.] DEUTERANOPE = absence/defect of the M (medium-wavelength) cones → difficulty perceiving GREEN. Protan = red defect; tritan = blue. Mnemonic: Deutera = ''two''/green (the second/green channel). Red-green is the common axis."}'),
  ('aca0aad9-1p','{"options": ["6/60..", ".1..", "20/20 ..", "6/6.."], "correct": 2, "explanation": "20/20 is a SNELLEN IMPERIAL (foot) fraction (test distance 20 ft). 6/6 and 6/60 are metric (meters); .1 is decimal. Imperial = feet (20/20); metric = meters (6/6)."}'),
  ('b0f90cbd-1n','{"options": ["6/200,", "20/20,", "6/60 ,", "6/120,"], "correct": 2, "explanation": "20/200 (imperial) = 6/60 (metric): both express ''60-m letter seen at 6 m'' = ''200-ft letter at 20 ft.'' Convert 20→6 m and 200→60. 20/200 = 6/60."}'),
  ('f75c6a0a-22','{"options": ["As a fraction in feet’’", "As a fraction in meters", "In decimal form ‘", "In diopters’"], "correct": 2, "explanation": "Snellen DECIMAL/International notation records acuity as a DECIMAL (e.g., 20/20 = 1.0, 20/40 = 0.5) rather than a foot/meter fraction or diopters. Decimal acuity = the fraction reduced to a single number."}'),
  ('bdf2597d-1v','{"options": ["To reduce glare during the test.", "To diagnose color blindness,", "To improve acuity if decreased vision is due to refractive error ,", "To measure intraocular pressure,"], "correct": 2, "explanation": "A PINHOLE improves acuity ONLY if reduced vision is from REFRACTIVE error (it restricts to paraxial rays, cutting blur). If VA improves with pinhole → uncorrected refractive error; if not → non-optical cause (Q52). Pinhole = isolates refractive blur."}'),
  ('2a4cf480-1y','{"options": ["The patient is faking visual loss’", "The cause is likely not optical ‘", "The patient needs a stronger glasses prescription’", "The Snellen chart is incorrect’"], "correct": 1, "explanation": "If pinhole does NOT improve VA, the cause is likely NOT OPTICAL (refractive) — suspect media opacity, macular, optic-nerve, or amblyopic pathology. (Not malingering or a wrong chart by default.) No pinhole improvement = look for organic/pathologic cause."}'),
  ('3373ea40-1i','{"options": ["Intraocular pressure’", "Total (refractive) astigmatism ‘", "Visual acuity in decimal notation’", "Pupil diameter under dim lighting’"], "correct": 1, "explanation": "JAVAL''S RULE estimates TOTAL (refractive) astigmatism from CORNEAL (keratometric) astigmatism: At = 1.25×(corneal cyl) + (−0.50 × 90) — adding the average physiologic lenticular ATR component. It predicts refractive cyl from K''s. Javal = corneal → total astigmatism."}'),
  ('a7470700-2e','{"options": ["A correction factor for corneal curvature-", "With-the-rule astigmatism-", "Average lens-induced astigmatism-", "Against-the-rule astigmatism -"], "correct": 3, "explanation": "In Javal''s rule At = 1.25(Ac) + (−0.50 cyl × 90), the constant −0.50 × 90 represents the average PHYSIOLOGIC lenticular ASTIGMATISM, which is AGAINST-THE-RULE (the lens contributes ~0.50 D ATR). So the −0.50 × 90 term = against-the-rule astigmatism. (Pairs with Q53.)"}'),
  ('8533bdd1-22','{"options": ["Medium aperture.", "Half light.", "Large aperture.", "Micro-spot/small aperture ."], "correct": 3, "explanation": "For a SMALL, undilated pupil use the MICRO-SPOT (small) aperture of the ophthalmoscope — it reduces reflections off the iris/lens and gets light through the tiny pupil. Large/medium apertures are for dilated pupils. Small pupil → small aperture."}'),
  ('ccfd1ad7-1s','{"options": ["Decreases light intensity for patient comfort.,", "Helps evaluate corneal contour,.", "Enhances contrast of blood vessels and red structures ,.", "Used to fit contact lenses,."], "correct": 2, "explanation": "The RED-FREE (green) filter absorbs red light, ENHANCING CONTRAST of blood vessels, hemorrhages, and the nerve fiber layer (which appear dark against the green). Not for comfort, cornea, or CL fitting. Red-free = vessels/NFL contrast."}'),
  ('17ade08a-41','{"options": ["-’A. Cornea", "-’-B. Anterior chamber", "‘C. Nucleus of the lens", "-’D. Posterior lens or vitreous"], "correct": 3, "explanation": "Direct-ophthalmoscope PARALLAX: an opacity moving WITH (same direction as) the scope lies POSTERIOR (behind the eye''s rotation center) — posterior lens/vitreous. Against motion = anterior (cornea/anterior chamber). Rule: ''with'' = posterior, ''against'' = anterior; still = at the nodal/pupil plane."}'),
  ('d55c3c8a-2c','{"options": ["Decreases both magnification and field of view;’", "Increases magnification but decreases field of view ;’", "Decreases magnification and increases field of view;’", "Increases both magnification and field of view;’"], "correct": 1, "explanation": "A LOW-POWERED condensing lens in indirect ophthalmoscopy INCREASES MAGNIFICATION but DECREASES the field of view (less convergence, larger image, smaller area). Higher-powered lenses give wide field, low mag. Trade-off: lens power ↑ → field ↑, mag ↓ (so low power → mag ↑, field ↓)."}'),
  ('f01089af-2o','{"options": ["Accommodation and refraction-’;", "Convergence and divergence-’;", "Accommodative and convergence patterns -’;", "Fusional reserves and binocular balance-’;"], "correct": 2, "explanation": "Phorometry centers on the ACCOMMODATIVE and CONVERGENCE patterns (and their interaction, AC/A) — the OEP analysis groups findings into these two systems plus their interplay. Not refraction or color. The two key visual patterns = accommodation + convergence."}'),
  ('718d0290-1d','{"options": ["To assess color vision..", "To affect the convergence pattern ..", "To correct refractive error..", "To evaluate amplitude of accommodation.."], "correct": 1, "explanation": "PRISMS in phorometry alter/measure the CONVERGENCE pattern (dissociate the eyes and measure phorias and fusional vergence ranges). They don''t correct refraction, test color, or measure accommodative amplitude. Prism = manipulate/measure vergence."}'),
  ('035086a4-1p','{"options": ["Step #14A,", "Step #3 and #8 ,", "Step #16A and #16B,", "Step #17A and #17B,"], "correct": 1, "explanation": "Lateral phoria at FAR is tested at OEP steps #3 (and #8) (von Graefe dissociation at distance). Steps #14/#16/#17 are near accommodative/vergence findings. Distance lateral phoria = #3 (and #8)."}'),
  ('220477fd-1l','{"options": ["Oblique prism-", "Horizontal dissociating prism-", "Vertical dissociating prism -", "Rotating prism-"], "correct": 2, "explanation": "Lateral (horizontal) phoria is dissociated with a VERTICAL dissociating prism (e.g., 6Δ BU before one eye) so the images separate vertically and the horizontal misalignment is read on the measuring prism. (Vertical phorias use a horizontal dissociating prism.) Dissociate perpendicular to the phoria you measure."}'),
  ('7428f04c-1o','{"options": ["Enhances color perception’", "Measures fusion reserve’", "Provides tolerance for maintaining visual clarity and single vision ‘", "Assists in diagnosing hyperopia’"], "correct": 2, "explanation": "The BUFFER (zone of comfort, Percival/Sheard region) provides TOLERANCE so the eyes maintain clear single binocular vision without symptoms — the reserve cushion around the demand. It isn''t color, a fusion-reserve measurement per se, or a hyperopia test. Buffer = comfort tolerance for clear single vision."}'),
  ('cd5b55f0-2i','{"options": ["Binocular Crossed Cylinder ;", "Dissociated Crossed Cylinder ;", "Amplitude of Accommodation ;", "Phoria at Near ;"], "correct": 2, "explanation": "The AMPLITUDE OF ACCOMMODATION test deliberately ALTERS the accommodative stimulus (push-up/minus-lens) and records a definite response (first sustained blur) — measuring the focusing range. BCC/DCC measure posture (lag); near phoria measures alignment. AoA = graded accommodative stimulus → response."}'),
  ('cb97bc78-1c','{"options": ["Maddox Rod method’", "Worth 4 Dot Test’", "Von Graefe method ‘", "Hirschberg test’"], "correct": 2, "explanation": "Phoria is commonly measured by the VON GRAEFE method (dissociating prism in the phoropter, align the split images). Maddox rod is an alternative; W4D tests fusion; Hirschberg estimates tropia. Von Graefe = standard phoropter phoria."}'),
  ('7d0d1f4f-26','{"options": ["Step #17A-=", "Step #16A =", "Step #14B=", "Step #21="], "correct": 1, "explanation": "Positive Relative Convergence (PRC) at NEAR is OEP step #16A (base-out to blur/break/recovery at near). #17A is divergence (NRC); #14 accommodative; #21 NRA/PRA-related. PRC near = #16A (base-out near)."}'),
  ('a5dd2e73-2q','{"options": ["10 prism diopters./", "2.50 prism diopters./", "15 prism diopters ./", "6 prism diopters./"], "correct": 2, "explanation": "Convergence demand = PD(cm)/working distance(m). 16 in = 0.406 m; 64 mm = 6.4 cm → 6.4/0.406 ≈ 15.7 ≈ 15Δ. (Equivalently meter-angle × PD.) Stimulus to convergence ≈ 15Δ. Method: Δ = PD(cm) ÷ distance(m)."}'),
  ('7281ac84-1q','{"options": ["To assess accommodative lag’", "To measure intraocular pressure’", "To indicate the position of rest of the eyes when fusional convergence is relaxed’", "To evaluate visual acuity under stress’"], "correct": 2, "explanation": "The PHORIA test reveals the eyes'' POSITION OF REST when fusional convergence is RELAXED (dissociated) — the latent deviation the fusion system normally controls. Not accommodative lag, IOP, or acuity. Phoria = dissociated resting alignment."}'),
  ('f5805738-2f','{"options": ["Minus lenses until blur;", "Plus lenses until first readable ;", "Cylindrical lenses to refine axis;", "Cross-cylinder lenses with prism;"], "correct": 1, "explanation": "For a PRESBYOPE, the Amplitude of Accommodation ''push-up'' is impractical, so PLUS lenses are added until print is FIRST READABLE (minus-lens-to-blur measures it in non-presbyopes). Presbyope AoA → plus-to-clear method. (Non-presbyope endpoint in Q70.)"}'),
  ('0fdfbef7-2j','{"options": ["Highest plus before blur,", "Vertical alignment,", "Print becomes difficult to read ,", "Equal image clarity in both eyes,"], "correct": 2, "explanation": "For a NON-presbyope, the AoA endpoint (minus-lens or push-up) is when PRINT BECOMES JUST SUSTAINEDLY BLURRED / difficult to read (the first sustained blur = max accommodation). Not highest-plus or alignment. Endpoint = first sustained blur."}'),
  ('2278ead6-1w','{"options": ["Measures fusion reserves at near;", "Indicates accommodative lag under dissociated condition ;", "Tests for binocular visual acuity;", "Determines convergence insufficiency;"], "correct": 1, "explanation": "The DISSOCIATED Cross-Cylinder (DCC, OEP #14A) indicates the accommodative LAG under DISSOCIATED (monocular-like, fused-target-removed) conditions — a baseline accommodative posture. The BINOCULAR CC (#14B) measures it under binocular conditions. DCC = dissociated accommodative lag."}'),
  ('0ed9bcc9-20','{"options": ["The eye’s vertical alignment ability,,", "The eye’s accommodative facility,,", "The convergence in reserve at fixation ,,", "The amplitude of accommodation,,"], "correct": 2, "explanation": "In the Positive Fusional (convergence) Reserve test, the BREAK point = the maximum CONVERGENCE the patient holds before fusion breaks (diplopia) at that fixation distance — the convergence ''in reserve.'' Not vertical/accommodative. Break = limit of fusional convergence."}'),
  ('b5b2da1a-1l','{"options": ["Break and recovery’’", "Blur-out’’", "First readable print’’", "Equality ‘’"], "correct": 3, "explanation": "The Binocular Cross-Cylinder (#14B) endpoint is EQUALITY — the horizontal and vertical lines of the grid appear equally clear/black (balanced accommodative posture under binocular conditions). Break/recovery and blur-out belong to other tests. BCC endpoint = equality."}'),
  ('23abaf72-2u','{"options": ["Emmetropia-=", "Hyperopia-=", "Myopia -=", "Astigmatism-="], "correct": 2, "explanation": "A keratometry reading of 46.00 D is a relatively STEEP cornea (high corneal power), which biases toward MYOPIA (more converging power). Flatter K (~41-42) trends hyperopic. Steep K → myopic tendency (corneal/refractive myopia)."}'),
  ('8f438211-4e','{"options": ["Suppression of the left eye ,", "Convergence problem,", "Suppression of the right eye ,", "Accommodative problem,"], "correct": 0, "explanation": "During a base-out (convergence) test, if the target appears to slide to the LEFT (one image vanishes/drifts), it indicates SUPPRESSION of the LEFT eye (that eye''s image is dropped under stress). The disappearing image localizes the suppressing eye. Target shifts toward the suppressed side."}'),
  ('10204b00-3x','{"options": ["The circle of least confusion is on the retina ..", "All points are on the retina .", "The sphere is focused on the retina.", "The vertical lines are on the retina."], "correct": 3, "explanation": "At the cross-cylinder endpoint ''equally clear,'' the two line sets focus symmetrically about the retina; the classic statement is that the VERTICAL lines fall on the retina at balance (the circle of least confusion straddles, but the equality reflects the principal line positions). [The intended answer ties equality to the line positions on the retina.] Endpoint = balanced focal lines."}'),
  ('8ef5f64c-27','{"options": ["Inhibition ‘", "Stimulation’", "Accommodation’", "Convergence’"], "correct": 0, "explanation": "Lateral phoria measurement uses an INHIBITION (relaxation/dissociation) probing method — fusion is broken (inhibited) so the latent deviation surfaces, rather than stimulating accommodation/convergence. Phoria = measured under dissociation (inhibited fusion)."}'),
  ('85036159-4p','{"options": ["-a. +1.50D", "-b. +1.75D", "-c. +2.00D", "-d. +2.25D"], "correct": 0, "explanation": "Half-amplitude rule: keep half the accommodation in reserve. Demand at 13 in (0.33 m) = 3.00 D; usable = ½ of 3.00 D amplitude = 1.50 D; add = demand − usable = 3.00 − 1.50 = +1.50 D. Method: Add = near demand − ½(amplitude)."}'),
  ('10fa2285-3z','{"options": ["The cylinder correction is insufficient", "The cylinder correction is excessive", "The patient has not been properly fogged Astigmatism is irregular"], "correct": 2, "explanation": "[3 options.] If the blurred (axis) line won''t DARKEN with added minus during astigmatic refinement, the patient likely wasn''t properly FOGGED (accommodation isn''t controlled) or the astigmatism is irregular — the cylinder can''t be cleanly refined. Re-fog and recheck. Proper fogging is prerequisite to cylinder refinement."}'),
  ('76fdd14d-1c','{"options": ["Myopia caused by an increase in the refractive power of the cornea=", "Myopia resulting from a short axial length of the eye=", "Myopia due to elongation of the axial length of the eyeball=", "Myopia secondary to lens opacities="], "correct": 2, "explanation": "AXIAL myopia = myopia from ELONGATION of the eyeball''s axial length (the most common type) — the retina sits behind the focal point. Not corneal steepening (that''s refractive/curvature myopia) or lens opacity. Axial = long eye."}'),
  ('a4b13107-5u','{"options": ["True axial myopia/", "Refractive myopia due to corneal steepening/", "Accommodative spasm mimicking myopia/", "Early lenticular sclerosis/"], "correct": 2, "explanation": "A 9-year-old with −3.00 D retinoscopy but +0.25 D on CYCLOPLEGIC refraction (the minus vanishes under cycloplegia) and normal axial length (23.5 mm) = ACCOMMODATIVE SPASM (pseudomyopia) mimicking myopia — active accommodation created the false minus. True axial myopia would persist under cycloplegia. Cycloplegic clears the ''myopia'' → spasm."}'),
  ('dda6c460-2k','{"options": ["Congenital myopia’;’;", "Axial myopia’;;", "Induced myopia’;’", "Pseudomyopia;’;’"], "correct": 2, "explanation": "INDUCED (acquired) myopia is most associated with NUCLEAR SCLEROSIS — the sclerotic lens nucleus gains refractive index/power, causing an index (lenticular) myopic shift (''second sight''). Axial/congenital/pseudomyopia have other mechanisms. Nuclear cataract → index (induced) myopia."}'),
  ('27406bd1-3t','{"options": ["High hyperopia/", "Low myopia/", "High myopia/", "Mixed astigmatism/"], "correct": 0, "explanation": "A DULL, SLOW ''WITH'' reflex in a dim room in both meridians suggests HIGH MYOPIA — wait: ''with'' motion means hyperopia/under-minus, and a dim, slow reflex suggests HIGH refractive error (far point near the peephole). A dull slow reflex = high power; with-motion classically = hyperopia, but a high myope viewed inside the far point shows ''against.'' [Keyed high myopia — interpret the dull/slow reflex as high ametropia; verify the motion direction.] Dull/slow = high error."}'),
  ('a3b874a7-8k','{"options": ["Stable emmetropization; follow-up in 2 years", "Myopia onset confirmed; monitor axial length every 6 months", "Findings are typical; no further testing needed", "Astigmatism is the main concern; initiate keratometry monitoring"], "correct": 1, "explanation": "A 7-year-old going from +0.25 D to −0.50 D with axial length 23.4→24.3 mm over 12 months, low outdoor + high near work = early MYOPIA ONSET with rapid axial growth → these are the classic risk findings warranting AXIAL-LENGTH MONITORING every ~6 months and myopia-control measures. [Keyed ''C'' reads as typical/no-action — but the risk profile argues for active monitoring; verify.] Myopia onset + fast AL growth = monitor closely."}'),
  ('f54cecaf-34','{"options": ["Increased accommodation improves emmetropization/", "Hyperopic defocus decreases axial elongation/", "Myopic defocus at the retina slows growth/", "Increased outdoor exposure reduces progression/"], "correct": 2, "explanation": "Historically, UNDER-correction was believed to slow myopia via MYOPIC DEFOCUS at the retina (image focused in front ''signals'' less growth). Modern evidence REVERSED this — under-correction (hyperopic defocus) actually speeds progression; myopic defocus (e.g., from multifocals/ortho-K reverse zone) slows it. Concept: myopic defocus = anti-growth signal."}'),
  ('ae7d290d-2r','{"options": ["Myope’’’", "Pre-myope;’;", "Progressive Myopia’;’;", "High Hyperopia’;’"], "correct": 1, "explanation": "A 6-year-old with +0.75 D is a PRE-MYOPE — low hyperopia below the age-expected reserve (~+1.00 to +1.50 D at 6 yr) flags myopia risk (less hyperopic ''buffer'' = likely to become myopic). Not yet myopic, not high hyperopia. Low hyperopic reserve for age = pre-myopia."}'),
  ('edea24a6-27','{"options": ["European", "Caucasian", "African", "Asian"], "correct": 3, "explanation": "ASIANS (especially East Asian) have the HIGHEST myopia prevalence/risk (genetic + intense near-work/education + low outdoor time). A major epidemiologic fact driving the global myopia ''epidemic.'' Highest myopia risk ethnicity = East Asian."}'),
  ('13405aa8-45','{"options": ["Emmetropization/", "Accommodation/", "Dynamic Refraction/", "Phototransduction/"], "correct": 0, "explanation": "EMMETROPIZATION = the developmental process by which corneal/lens power and axial length come into BALANCE to yield clear distance vision (the newborn''s hyperopia reduces toward emmetropia over the early years). Accommodation/dynamic refraction/phototransduction are different. Emmetropization = growth-driven refractive balancing."}'),
  ('54ac99ae-1g','{"options": ["The use of one eye alone to perceive depth and space", "The coordinated, integrated, and simultaneous function of both eyes to produce a single mental image", "The ability to see with each eye independently without suppression", "The simple summation of visual fields from both eyes"], "correct": 1, "explanation": "Binocular vision is defined as the coordinate use of BOTH eyes to produce a single mental image, implying FUSION — the blending of both images into one percept."}'),
  ('9a9b210f-14','{"options": ["120°", "150°", "180°", "210°"], "correct": 2, "explanation": "Total binocular visual field = 180°. Common binocular field = 120° (overlap zone). Monocular = 150°. Temporal crescent = 30°."}'),
  ('a8fa26a1-21','{"options": ["30°", "120°", "150°", "180°"], "correct": 1, "explanation": "The common binocular visual field = 120°. This is the zone where both eyes overlap. The total binocular field is 180°, monocular is 150°."}'),
  ('6b7c18ea-1w','{"options": ["Seen by both eyes simultaneously", "Seen by one eye only with no binocular overlap", "Processed by the contralateral cortex only", "Stimulated exclusively by the fovea"], "correct": 1, "explanation": "The temporal crescent (30°) is the outermost zone of the visual field seen by ONLY one eye — no binocular overlap exists here."}'),
  ('8314b4ba-2a','{"options": ["Foveal region stimulated in both eyes", "Corresponding retinal points", "Partial decussation of optic nerve fibers", "Equal refractive error in both eyes"], "correct": 3, "explanation": "Equal refractive error is NOT a prerequisite. The 6 prerequisites are: frontally placed eyes, partial decussation, foveal stimulation, corresponding retinal points, equal/near-equal retinal image SIZE (iseikonia), and efficient EOMs."}'),
  ('c7299043-1m','{"options": ["Anisometropia", "Antimetropia", "Aniseikonia", "Aniso-oxyopia"], "correct": 2, "explanation": "Aniseikonia = unequal retinal image SIZE. Iseikonia = equal. Anisometropia = difference in refractive error amount. Aniso-oxyopia = unequal best-corrected VA."}'),
  ('80f2c4fb-2l','{"options": ["Anisometropia", "Aniseikonia", "Iso-oxyopia", "Antimetropia"], "correct": 3, "explanation": "Antimetropia = DIFFERENT refractive status (one eye myopic, one hyperopic). Anisometropia = significant difference in the AMOUNT of refractive error, but same type."}'),
  ('a67cdab3-2h','{"options": ["Stereopsis", "Enlarged field of vision", "Single vision", "Compensation of blind spot"], "correct": 2, "explanation": "Single vision is explicitly stated as the FIRST and FOREMOST advantage of binocular vision. Stereopsis is also an advantage but ranked below single vision."}'),
  ('59bdffcd-13','{"options": ["At birth", "2 months", "3 months", "6 months"], "correct": 2, "explanation": "The foveas are fully formed at 3 months. At 3 months, the infant also begins to HOLD fixation on objects. At 3–4 months, eyes are expected to be STRAIGHT."}'),
  ('1c94d81d-1q','{"options": ["Following large objects", "Fixing on a face", "Eyes following LIGHT", "Equal VA in both eyes"], "correct": 2, "explanation": "In the newborn, the first sign of fixation development appears when the eyes follow LIGHT. At 2 months, they follow large objects. At 3 months, foveas are fully formed."}'),
  ('476f190c-1q','{"options": ["3 months", "6 months", "1 year", "1 year 6 months"], "correct": 3, "explanation": "Fusional mechanism becomes fully developed at 1 year 6 months (18 months). VA of 20/20 is reached at 3 years. Accommodation develops with sharpening of VA at ~3 years."}'),
  ('c4f89792-1k','{"options": ["Birth", "6 months", "1 year", "3 years"], "correct": 2, "explanation": "VA of 20/70 is normal at 1 year. VA of 20/20 is expected at 3 years. At birth, VA is ≤ 5/200."}'),
  ('78781dff-1f','{"options": ["0–3 years", "3–6 years", "7–12 years", "12–18 years"], "correct": 2, "explanation": "7–12 years is the age of emmetropization — when the eye gradually shifts toward emmetropia as axial length increases."}'),
  ('0fb5c9fb-19','{"options": ["Emmetropic", "Myopic", "Hyperopic", "Astigmatic"], "correct": 2, "explanation": "Newborns are normally hyperopic because the eyeball is smaller and the ciliary muscles are not yet fully developed. VA at birth is ≤ 5/200."}'),
  ('495ef0ad-2g','{"options": ["20 cm", "30 cm", "40 cm", "50 cm"], "correct": 2, "explanation": "Reading material is positioned at 40 cm (16 inches) from the patient in the bar reading test. A pen is placed 2–3 inches over the page."}'),
  ('98fea080-29','{"options": ["2 prism diopters", "4 prism diopters", "6 prism diopters", "10 prism diopters"], "correct": 2, "explanation": "6 prism diopters (BU or BD) is placed before one eye to induce doubling. If the patient detects diplopia, BV is confirmed."}'),
  ('1d728fbc-1c','{"options": ["Apex", "Center", "Base", "Edge"], "correct": 2, "explanation": "LIGHT bends toward the BASE. The EYE looking through a prism is displaced toward the APEX. The OBJECT viewed appears displaced toward the APEX. Remember: Light=Base, Eye/Object=Apex."}'),
  ('4c9591e6-1i','{"options": ["Base", "Optical center", "Edge", "Apex"], "correct": 3, "explanation": "Both the EYE and the OBJECT are displaced toward the APEX of the prism. Only LIGHT goes toward the BASE."}'),
  ('6d3713fe-2l','{"options": ["A vertical phoria", "A lateral (horizontal) phoria", "A torsional phoria", "A cyclodeviation"], "correct": 1, "explanation": "Horizontal Maddox rod → vertical streak → detects LATERAL (horizontal) phoria. Vertical Maddox rod → horizontal streak → detects VERTICAL phoria."}'),
  ('b84f4d2e-31','{"options": ["Orthophoria", "Esophoria", "Exophoria", "Hyperphoria"], "correct": 2, "explanation": "Crossed projection (OD sees right image on LEFT visual field) = EXOPHORIA. Uncrossed projection = esophoria. Superimposed images = orthophoria."}'),
  ('c9a35f13-3c','{"options": ["Exophoria", "Orthophoria", "Esophoria", "Hyperphoria"], "correct": 2, "explanation": "Uncrossed position (streak on SAME side as light) = ESOPHORIA. Crossed position (opposite side) = exophoria. Superimposed = orthophoria."}'),
  ('1e2268db-2c','{"options": ["Exactly 1 diameter", "2 or fewer diameters", "3 diameters", "More than 4 diameters"], "correct": 1, "explanation": "The rolled paper should have 2 or fewer diameters. The tube is directed toward a distant fixation object while the palm is held up — a hole appears in the hand if BV is present."}'),
  ('391542a7-2h','{"options": ["Primary position", "Secondary position", "Tertiary position", "Quaternary position"], "correct": 2, "explanation": "Tertiary position = combination of lateral + vertical movements (e.g., dextrosupra, levoinfra). Secondary = only lateral OR only vertical."}'),
  ('3e56f71f-1g','{"options": ["Eyes deviated right, head erect", "Eyes deviated upward", "Eyes directed straight ahead on the horizon, head erect", "Eyes in the position of anatomical rest without visual stimulus"], "correct": 2, "explanation": "Primary position = head erect, eyes directed straight ahead on the horizon. This is the ''ortho'' position."}'),
  ('1c6ee2a6-1m','{"options": ["Primary", "Secondary", "Tertiary", "Conjugate"], "correct": 2, "explanation": "Dextrosupraversion = right + up = combination of lateral and vertical = TERTIARY position."}'),
  ('2b3742ca-1q','{"options": ["Dextrosupraversion", "Levoinfraversion", "Supraversion", "Dextroinfraversion"], "correct": 2, "explanation": "Secondary positions involve ONLY lateral OR only vertical movement. Supraversion = only upward = SECONDARY. The others (dextrosupra, levoinfra, dextroinfra) are tertiary."}'),
  ('78cc0969-y','{"options": ["Version", "Vergence", "Duction", "Fusion"], "correct": 2, "explanation": "Duction = movement of ONE eye only. Version = both eyes in the SAME direction. Vergence = both eyes in OPPOSITE directions."}'),
  ('8e1bf5a7-27','{"options": ["Duction", "Version", "Vergence", "Fusion"], "correct": 1, "explanation": "Version = both eyes move synchronously and symmetrically in the SAME direction (conjugate). Example: Dextroversion — both eyes look right."}'),
  ('dc357616-1k','{"options": ["Divergence", "Incyclovergence", "Adduction", "Convergence"], "correct": 3, "explanation": "Convergence = both eyes moving INWARD (nasally). Divergence = both outward. Adduction = ONE eye inward (a duction, not vergence)."}'),
  ('6451b715-u','{"options": ["Infraversion", "Dextroversion", "Levoversion", "Supraversion"], "correct": 3, "explanation": "Sursumversion = Supraversion = Anaversion — all mean both eyes looking UPWARD. Deorsumversion = Cataversion = Infraversion (both eyes down)."}'),
  ('ca70ddbb-1x','{"options": ["Excycloduction", "Abduction", "Infraduction", "Incycloduction"], "correct": 3, "explanation": "Incycloduction = rotation of the vertical corneal meridian INWARD (intorsion). Excycloduction = outward rotation (extorsion). These are torsional ductions."}'),
  ('0f2698ad-1o','{"options": ["Dextrosupraversion", "Levoinfraversion", "Levosupraversion", "Dextroinfraversion"], "correct": 3, "explanation": "Dextroinfraversion = both eyes to the RIGHT + DOWNWARD. Dextrosupraversion = right + up. Levoinfraversion = left + down."}'),
  ('cd2d8569-16','{"options": ["Right eye up, left eye down", "Both eyes upward", "Right eye down, left eye up", "Both eyes downward"], "correct": 2, "explanation": "Negative Vertical Divergence = right eye DOWN, left eye UP. Positive Vertical Divergence = right eye UP, left eye DOWN."}'),
  ('9ed78926-1p','{"options": ["Superior Rectus", "Inferior Oblique", "Superior Oblique", "Medial Rectus"], "correct": 3, "explanation": "MR (and LR) work only in the horizontal plane with NO secondary or tertiary actions. SR and IR angle 23° nasally, giving them secondary/tertiary actions. SO and IO are oblique muscles with complex actions."}'),
  ('692a9c13-1v','{"options": ["Medial Rectus", "Lateral Rectus", "Superior Rectus", "Inferior Rectus"], "correct": 2, "explanation": "SR has the FARTHEST insertion from the limbus. MR has the CLOSEST insertion to the limbus. SR is also the longest muscle when the tendon is excluded."}'),
  ('35255c59-v','{"options": ["The pathway of the SO tendon through the trochlea", "The circle connecting insertion points of all four recti muscles", "The shape of the visual field in glaucoma", "The arc of EOM origins at the Annulus of Zinn"], "correct": 1, "explanation": "Spiral of Tillaux = the circular arc connecting the INSERTION points of all four recti muscles on the sclera."}'),
  ('dbe54081-2m','{"options": ["40 mm", "50 mm", "60 mm", "70 mm"], "correct": 2, "explanation": "SO is the longest EOM at 60mm total. The trochlea acts as a pulley, adding to its length. Without the tendon, SR is the longest rectus muscle."}'),
  ('df4973cf-1g','{"options": ["Elevation", "Depression", "Incycloduction", "Excycloduction"], "correct": 2, "explanation": "SO primary action = INCYCLODUCTION (intorsion). Secondary = depression. Tertiary = abduction. The opposite muscle, IO, primarily excyclotorts."}'),
  ('1ce86f76-1g','{"options": ["Incycloduction", "Depression", "Elevation", "Excycloduction"], "correct": 3, "explanation": "IO primary action = EXCYCLODUCTION (extorsion). Secondary = elevation. Tertiary = abduction. IO is innervated by CN III."}'),
  ('645e6090-24','{"options": ["Lateral Rectus", "Superior Rectus", "Medial Rectus", "Inferior Oblique"], "correct": 2, "explanation": "MR is the strongest, heaviest, and broadest EOM. It has the closest insertion to the limbus and works ONLY in the horizontal plane."}'),
  ('50fadd66-21','{"options": ["Right SR and Left SR", "Right SR and Left IO", "Right IO and Left SR", "Right LR and Left MR"], "correct": 1, "explanation": "Dextrosupraversion = both eyes up and right. Right eye uses SR (elevation + adduction). Left eye uses IO (elevation + abduction from adducted). Yoke pair: Right SR + Left IO."}'),
  ('2a75f532-19','{"options": ["When a muscle contracts, its direct antagonist relaxes equally", "An equal impulse is sent to the contralateral yoke muscle when a muscle is innervated", "Convergence and accommodation are linked", "Fusion requires equal retinal image size"], "correct": 1, "explanation": "Hering''s Law = when a nervous impulse causes one muscle to contract, an EQUAL impulse goes to the CONTRALATERAL SYNERGIST (yoke muscle) to maintain parallelism of visual axes."}'),
  ('f0b3cf76-1i','{"options": ["Binocular movements", "Vergence movements only", "Monocular movements (one eye)", "Torsional movements only"], "correct": 2, "explanation": "Sherrington''s Law applies to MONOCULAR movements — within one eye, when the agonist contracts, the direct antagonist RELAXES equally. Example: supraduction — SR contracts, IR relaxes."}'),
  ('ff929d44-25','{"options": ["Right MR and Left MR", "Right LR and Left MR", "Right MR and Left LR", "Right SR and Left IO"], "correct": 1, "explanation": "Dextroversion = both eyes look right. Right eye agonist = LR. Left eye yoke = MR. Hering''s Law sends EQUAL impulse to R LR and L MR simultaneously."}'),
  ('63259059-27','{"options": ["Right Superior Oblique", "Right Inferior Rectus", "Left Superior Rectus", "Right Lateral Rectus"], "correct": 1, "explanation": "Sherrington''s = monocular. For right supraduction: R SR contracts (agonist) → R IR must RELAX (antagonist). This is within the same eye."}'),
  ('42e4569b-1e','{"options": ["Accommodation", "Parallelism of the visual axes", "Equal pupil size", "Constant accommodative vergence"], "correct": 1, "explanation": "Hering''s Law ensures equal innervation to yoke muscles so both eyes remain PARALLEL — maintaining alignment of visual axes during conjugate movements."}'),
  ('951ed913-1l','{"options": ["X-axis (transverse)", "Z-axis (vertical)", "Y-axis (optic/sagittal)", "None — torsion has no axis"], "correct": 2, "explanation": "Y-axis (optic/sagittal, 24mm) = TORSIONAL movements. X-axis (transverse, 22mm) = vertical movements. Z-axis (vertical, 22mm) = horizontal movements."}'),
  ('05921ba0-2c','{"options": ["7 mm", "10 mm", "13.5 mm", "17 mm"], "correct": 2, "explanation": "The center of rotation is 13.5 mm behind the cornea. ALL oblique axes pass through this point. All eye movements occur at the center of rotation."}'),
  ('1c6b070b-17','{"options": ["Object of regard to center of rotation", "Center of cornea to center of rotation", "Object of regard to the fovea, passing through the nodal point", "Entrance pupil perpendicular to the cornea"], "correct": 2, "explanation": "Visual axis = object of regard → nodal point → fovea. Line of sight = object of regard → center of rotation. Pupillary axis = perpendicular to cornea through entrance pupil center."}'),
  ('fe528c30-u','{"options": ["Visual axis and optic axis at the nodal point", "Optic axis and line of sight at the center of rotation", "Pupillary axis and line of sight", "Baseline and visual axis"], "correct": 2, "explanation": "Angle Lambda = between PUPILLARY AXIS and LINE OF SIGHT. Angle Alpha = visual axis vs optic axis at nodal point. Angle Gamma = optic axis vs line of sight at COR."}'),
  ('b74d0a7f-v','{"options": ["Voluntary fixation", "Pursuit fixation", "Steady fixation", "Saccadic (jump) fixation"], "correct": 3, "explanation": "Saccadic/jump fixation is the FASTEST type — rapid change of fixation from one point to another. Pursuit = tracking a moving object. Scanning = series of rapid fixations."}'),
  ('ddb9e770-24','{"options": ["Y + X axes; upper and lower", "Y + Z axes; right and left hemispheres", "X + Z axes; anterior and posterior halves", "Y + Z axes; anterior and posterior halves"], "correct": 2, "explanation": "Equatorial plane = X-axis (transverse) + Z-axis (vertical) → divides eye into ANTERIOR and POSTERIOR halves. Horizontal plane (Y+X) = upper/lower. Median plane (Y+Z) = right/left."}'),
  ('426fdfd8-15','{"options": ["The dominant eye in binocular viewing", "An imaginary eye between the two physical eyes representing both retinas", "The eye with superior visual acuity", "The fovea of the fixating eye"], "correct": 1, "explanation": "Cyclopean Eye/Binoculus = imaginary eye located BETWEEN the two physical eyes, representing both retinas as one unified system."}'),
  ('9546567c-26','{"options": ["Right temporal retina", "Left nasal retina", "Left temporal retina", "Left fovea"], "correct": 2, "explanation": "NRC: R nasal = L temporal; R temporal = L nasal; R fovea = L fovea. The nasal of one eye always matches the temporal of the other."}'),
  ('a006a546-1e','{"options": ["Both foveas share a common visual direction with each other", "The fovea of one eye shares a common visual direction with an extrafoveal area of the other eye", "Complete suppression of the deviating eye", "Retinal rivalry between the two eyes"], "correct": 1, "explanation": "ARC = fovea of one eye + EXTRAFOVEAL area of the other eye share a common visual direction. This is the brain''s attempt to regain binocular advantage despite a strabismus."}'),
  ('f1002980-15','{"options": ["Always superior to NRC", "Not related to the angle of deviation", "Directly proportional to the angle of deviation", "Inversely proportional to the angle of deviation"], "correct": 3, "explanation": "Quality of BV in ARC is INVERSELY proportional to the angle of deviation — the larger the squint, the POORER the quality of ARC binocular vision."}'),
  ('2b5bbb1d-1x','{"options": ["Panum, 1850", "Worth, 1903", "Aguilonius, 1613", "Hering, 1868"], "correct": 2, "explanation": "The term ''Horopter'' (horizon of vision) was introduced in 1613 by Aguilonius. It describes the locus of all object points imaged on corresponding retinal elements at a given fixation distance."}'),
  ('ab9da898-12','{"options": ["The periphery of the retina", "The temporal crescent", "The point of fixation (fovea)", "12° of eccentricity"], "correct": 2, "explanation": "Panum''s is narrowest at the fixation point (6–10 arc min near fovea). It widens toward the periphery — reaching 30–40 arc min at 12° eccentricity."}'),
  ('9ae11821-2c','{"options": ["6–10 arc minutes", "10–15 arc minutes", "15–25 arc minutes", "30–40 arc minutes"], "correct": 3, "explanation": "At 12° eccentricity: 30–40 arc min. Near fovea: 6–10 arc min. Width increases ~1–2 arc min per degree of eccentricity."}'),
  ('70dd6140-3b','{"options": ["Single vision through fusion", "Suppression of one image", "Diplopia", "ARC"], "correct": 2, "explanation": "Disparate points → two different visual directions → the object appears in TWO places = DIPLOPIA. Corresponding points → same visual direction → single vision."}'),
  ('5b9bf3fa-14','{"options": ["Large, alternating strabismus", "Non-changing deviation of sufficient duration for retinocortical reorientation", "Complete suppression of the deviating eye", "Bilateral patching for weeks"], "correct": 1, "explanation": "ARC requires a NON-CHANGING deviation of SUFFICIENT DURATION for retinocortical elements to become reoriented. Alternating strabismus prevents ARC since the deviation keeps shifting."}'),
  ('e855a728-2b','{"options": ["Crossed diplopia", "Proximal diplopia", "Pathological diplopia", "Uncrossed (distal) diplopia"], "correct": 3, "explanation": "Uncrossed/Distal diplopia = objects BEYOND fixation. Crossed/Proximal = objects NEARER than fixation. Both are PHYSIOLOGICAL — normal phenomena."}'),
  ('f147ecea-29','{"options": ["Uncrossed diplopia", "Distal diplopia", "Homonymous diplopia", "Crossed (proximal) diplopia"], "correct": 3, "explanation": "Crossed/Proximal diplopia is commonly seen in EXOPHORIC conditions. Uncrossed/Distal is more common in ESOPHORIC conditions."}'),
  ('0b68793e-2l','{"options": ["Facultative suppression", "Retinal rivalry", "Binocular suppression", "Obligatory suppression"], "correct": 3, "explanation": "Obligatory suppression persists monocularly → results in reduced VA. AMBLYOPIA is the direct consequence. Facultative suppression = binocular only, no monocular ''hangover''."}'),
  ('7914cd65-12','{"options": ["Facultative suppression", "Retinal rivalry", "Physiological diplopia", "Obligatory suppression"], "correct": 3, "explanation": "Amblyopia = fallout of OBLIGATORY suppression. The suppression persists under monocular conditions and causes reduction of visual acuity."}'),
  ('c8182e24-1d','{"options": ["Diplopia", "Amblyopia", "ARC", "Confusion"], "correct": 3, "explanation": "Foveal suppression prevents CONFUSION (dissimilar images on corresponding foveal areas). Extrafoveal suppression prevents DIPLOPIA (similar images on non-corresponding areas)."}'),
  ('ca778a6c-r','{"options": ["Similar images fall on non-corresponding areas", "Corresponding areas are stimulated by dissimilar contours", "Both eyes are occluded simultaneously", "The fovea is stimulated from peripheral retina"], "correct": 1, "explanation": "Retinal rivalry = dissimilar contours on CORRESPONDING retinal areas → fusion impossible → brain alternately suppresses one eye''s image."}'),
  ('f1a51c9c-1p','{"options": ["Seeing a near object double while fixating far away", "Far object appearing double when fixating near", "Double vision due to myasthenia gravis", "Physiological diplopia for objects outside Panum''s area"], "correct": 2, "explanation": "Pathological diplopia is caused by disease — myasthenia gravis, multiple sclerosis, strabismus, proptosis, cataract, lens subluxation, etc. Options A and D describe physiological diplopia."}'),
  ('c5f28621-3l','{"options": ["Worth''s Theory", "Wall''s Theory", "Panum''s Theory", "Verhoeff''s Theory"], "correct": 3, "explanation": "Verhoeff''s Theory (''Theory of Replacement''/''Retinal Rivalry'') = alternating mosaic patterns from each eye combine to form a unified percept. Worth''s = psychological/cerebral. Wall''s = projection to same perceptual position."}'),
  ('6f14d519-1m','{"options": ["Retinal areas with maximal disparity", "Retinal areas with common visual directions", "Non-corresponding retinal areas", "Peripheral retina exclusively"], "correct": 1, "explanation": "Grade 1 (SMP) = stimulation of retinal areas with COMMON VISUAL DIRECTIONS — allowing two different objects (e.g., bird + cage) to be perceived simultaneously in the same direction."}'),
  ('a970c975-1a','{"options": ["Three-dimensional depth perception", "Simultaneous macular perception only", "Absence of sensory fusion", "True fusion without stereopsis — a 2D percept"], "correct": 3, "explanation": "Grade 2 = flat fusion = TRUE FUSION WITHOUT STEREOPSIS. The resultant percept is two-dimensional (flat), occupying a single plane. It is more than SMP but less than full stereopsis."}'),
  ('328db9ff-t','{"options": ["Superimposition", "Simultaneous macular perception", "Flat fusion", "Stereopsis"], "correct": 3, "explanation": "Stereopsis (Grade 3) is the highest form of fusion — full 3D depth perception from binocular retinal disparity. Tested with stereo fly/butterfly with full correction."}'),
  ('bb0a0271-1i','{"options": ["Equal or nearly equal VA", "Normal retinal correspondence", "Normal ocular motility", "Equal pupil size in both eyes"], "correct": 3, "explanation": "Equal pupil size is NOT a requirement for fusion. The 6 requirements are: equal VA, monocular fixation of each eye, NRC, normal motility, similar (not identical) images, and representation of crossed + uncrossed optic fibers in occipital cortex."}'),
  ('9c84f098-15','{"options": ["The fovea and central retina", "The extrafoveal retinal periphery", "The lateral geniculate nucleus", "The optic chiasm"], "correct": 1, "explanation": "Motor fusion = exclusive function of the EXTRAFOVEAL RETINAL PERIPHERY. Sensory fusion involves foveal areas. Both are ultimately CENTRAL PROCESSES (visual cortex)."}'),
  ('1f7338cd-1k','{"options": ["Accommodative demand", "Tonic vergence insufficiency", "Retinal disparity outside Panum''s area", "Pupillary light reflex"], "correct": 2, "explanation": "Retinal disparity OUTSIDE Panum''s fusional area is the stimulus for motor fusion. The eyes move in opposite directions (vergence) to bring the images back within Panum''s space and restore fusion."}'),
  ('d819a0fd-23','{"options": ["Motion parallax", "Aerial perspective", "Mathematical perspective", "Velocity"], "correct": 3, "explanation": "Velocity = speed cue. Fast moving image = NEARER. Slow moving = FARTHER. This is distinct from motion parallax which is based on direction of apparent movement relative to head motion."}'),
  ('10995ced-1p','{"options": ["Farther than the obscured object", "At the same distance", "Closer than the obscured object", "At infinity"], "correct": 2, "explanation": "Intervening objects cue: the object that OBSCURES another is judged NEARER. The partly obscured object appears farther away."}'),
  ('835644cf-38','{"options": ["Farther than the fixation point", "At the fixation point", "Closer than the fixation point", "Not detectable"], "correct": 2, "explanation": "Against parallax = object NEARER than fixation point. With parallax = object FARTHER. This is a reliable monocular depth cue."}'),
  ('33776e43-20','{"options": ["Farther and larger than they really are", "Closer and smaller than they really are", "At their actual distance", "At infinity"], "correct": 1, "explanation": "Clear mountain air: objects appear CLOSER and SMALLER than they really are (too distinct). Foggy weather: objects appear FARTHER and larger (less distinct = more distance assumed)."}'),
  ('103ec362-21','{"options": ["Monocular cues", "Binocular cues", "Psychological cues", "Proprioceptive cues only"], "correct": 1, "explanation": "Convergence + accommodation = BINOCULAR CUE — requires both eyes. The muscular effort for near fixation gives the brain distance information. There are 2 binocular cues total (+ binocular parallax)."}'),
  ('9c45f5fd-28','{"options": ["Farther", "At the same distance regardless", "Closer", "Placed at optical infinity"], "correct": 2, "explanation": "Greater parallactic angle = NEARER object. The parallactic angle is the sum of angles between the visual axes and the line connecting the object to the extrafoveal retina."}'),
  ('8d38cee8-33','{"options": ["Accommodative insufficiency", "Accommodative paralysis", "Ill-sustained accommodation (accommodative fatigue)", "Accommodative infacility"], "correct": 2, "explanation": "Ill-sustained accommodation = AA is NORMAL but tires with repeated stimulation. Insufficiency = AA is LOWER than expected for age. Infacility = difficulty CHANGING focus."}'),
  ('897d3e64-36','{"options": ["Accommodative insufficiency", "Accommodative fatigue", "Accommodative infacility / inertia", "Spasm of accommodation"], "correct": 2, "explanation": "Infacility/Inertia = difficulty CHANGING accommodative state (sluggish response). AA is normal. Insufficiency = AA is LOW. Fatigue = AA normal but tires with repeated stimulation."}'),
  ('7809441a-1p','{"options": ["Esophoria, miosis, and accommodative fatigue", "Over-accommodation, over-convergence, and pupillary miosis", "Exophoria, mydriasis, and accommodative paralysis", "Convergence insufficiency, miosis, and reduced AA"], "correct": 1, "explanation": "Spasm of Near Reflex (SNR) triad = OVER-ACCOMMODATION + OVER-CONVERGENCE + PUPILLARY MIOSIS. The ciliary muscle is contracted and cannot relax."}'),
  ('df917aac-1b','{"options": ["Normal AA that tires easily", "Total inability to accommodate", "AA lower than expected for age, NOT due to lens sclerosis", "Ciliary muscle continuously contracted and unable to relax"], "correct": 2, "explanation": "Accommodative insufficiency = AA LOWER THAN EXPECTED for age, not from crystalline lens sclerosis (which is presbyopia). Usually demonstrates poor SUSTAINING ability."}'),
  ('62dfb684-2m','{"options": ["Ill-sustained accommodation", "Accommodative infacility", "Accommodative insufficiency", "Accommodative paralysis"], "correct": 3, "explanation": "Accommodative paralysis = rare condition; ciliary muscle completely fails to respond to any stimulus. TOTAL inability. All other types have partial or fatiguing accommodation."}'),
  ('1371bd80-1b','{"options": ["Completely paralyzed with no response", "Slow to respond to accommodative stimuli", "Contracted and CANNOT relax", "Normal but fatigues on repeated stimulation"], "correct": 2, "explanation": "Spasm of accommodation = ciliary muscle is CONTRACTED and CANNOT BE RELAXED. Accommodation is continuously exerted. May be part of the SNR triad."}'),
  ('42e43eef-1m','{"options": ["Exophoria greater at distance than near", "Exophoria equal at distance and near", "Exophoria greater at NEAR than at distance", "Esophoria at near"], "correct": 2, "explanation": "Convergence weakness = EXO at NEAR > Exo at distance. Decompensated exophoria for NEAR vision only. Divergence excess = Exo at distance > near."}'),
  ('43efaa8f-10','{"options": ["Exophoria at near greater than distance", "Esophoria at distance greater than near", "Exophoria at distance greater than near (≥15Δ)", "Equal exophoria at distance and near"], "correct": 2, "explanation": "Divergence excess = Exo at DISTANCE > Exo at near (often by ≥15Δ). Presents as intermittent divergent squint for DISTANCE, with compensated exophoria for near."}'),
  ('513f0fda-2i','{"options": ["Right (ipsilateral) side", "Left (contralateral) side", "No head tilt expected", "Chin elevation only"], "correct": 1, "explanation": "SO damaged → head tilts to the OPPOSITE (contralateral) side. RSO palsy → LEFT head tilt. IO damaged → head tilts to SAME (ipsilateral) side."}'),
  ('d213cc8d-2i','{"options": ["Left (contralateral) side", "Right (ipsilateral) side", "Chin depression", "Left with chin elevation"], "correct": 1, "explanation": "IO damaged → head tilts to the SAME (ipsilateral) side. RIO palsy → RIGHT head tilt. Remember: IO = Ipsilateral; SO = opposite Side."}'),
  ('f34d95fd-2b','{"options": ["Also to the left (same as face turn)", "Downward", "To the right (opposite to face turn)", "Remains stationary"], "correct": 2, "explanation": "Face turn rule: the GOOD eye moves OPPOSITE to the direction of face turn. L esotropia → face turns LEFT → good eye (OD) moves RIGHT."}'),
  ('08c5e777-17','{"options": ["Fusional vergence reserve", "Proximal convergence near targets", "The magnitude of heterophoria at DISTANCE", "Accommodative convergence at near"], "correct": 2, "explanation": "Tonic vergence (from EOM tonus) is the basic cause of DISTANCE heterophoria. Deficient tonic = exophoria. Excessive tonic = esophoria at distance."}'),
  ('5d1adddb-1d','{"options": ["High AC/A ratio with normal vergence", "Normal phorias and AC/A but REDUCED fusional vergence amplitudes", "Large esodeviations at distance", "Convergence excess at near"], "correct": 1, "explanation": "Fusional vergence dysfunction = normal phorias + normal AC/A + REDUCED fusional vergence amplitudes → small zone of Clear Single Binocular Vision (CSBV)."}'),
  ('11629d5d-1n','{"options": ["90° OS and 180° OD", "45° OD and 135° OS", "45° OS and 135° OD", "60° OD and 120° OS"], "correct": 2, "explanation": "Bagolini: OS at 45°, OD at 135°. Streaks appear perpendicular. MOST PHYSIOLOGICAL test — does not affect vision or accommodation. Does not use dissociating lenses."}'),
  ('0a1a9b77-1m','{"options": ["Suppression of the LEFT eye", "Normal binocular vision", "Harmonious ARC", "Suppression of the RIGHT eye"], "correct": 3, "explanation": "Convention: red filter OD, green filter OS. 3 green dots only = OD (right eye) SUPPRESSED — patient only sees what OS sees. 2 red dots only = OS suppressed."}'),
  ('5fa3d050-1q','{"options": ["Angle of Anomaly = Subjective + Objective Angle", "Angle of Anomaly = Objective − Subjective Angle", "Angle of Anomaly = Subjective − Objective Angle", "Angle of Anomaly = Subjective × Objective Angle"], "correct": 1, "explanation": "Angle of Anomaly = OBJECTIVE − SUBJECTIVE Angle. If Subjective = Objective → NRC. If Angle of Anomaly = Objective Angle → Harmonious ARC (full sensory adaptation)."}'),
  ('12067fcd-2g','{"options": ["Symmetrical cross response (superimposed gaps)", "Single line with a gap (suppression)", "Vertical afterimage displaced to the LEFT", "Vertical afterimage displaced to the RIGHT"], "correct": 2, "explanation": "In ARC with right esotropia, the vertical afterimage (from deviating R eye''s fovea) is displaced to the LEFT. This is because the fovea of OD has acquired a different (anomalous) visual direction."}'),
  ('4acd1ed4-2v','{"options": ["It uses highly dissociating filters", "It projects afterimages onto the retina", "It does NOT affect vision or accommodation of the patient", "It measures objective and subjective angles simultaneously"], "correct": 2, "explanation": "Bagolini''s = most physiological because the plano lenses with fine striations do NOT alter vision or accommodation. The patient''s visual environment remains most natural."}'),
  ('73249ed7-2k','{"options": ["Normal bifoveal fusion", "A central suppression scotoma over the fovea", "ARC with harmonious deviation", "Convergence insufficiency"], "correct": 1, "explanation": "The 4Δ base-out test: normal = biphasic response (version + fusional duction). Absent second phase (no fusional duction) = the foveal area shifted into is SCOTOMATOUS (suppression scotoma) — no refixation drive."}'),
  ('39df9f73-1w','{"options": ["Normal binocular vision", "Harmonious ARC", "Diplopia (uncrossed for esotropia, crossed for exotropia)", "Suppression of one eye"], "correct": 2, "explanation": "5 dots = DIPLOPIA. For esotropia: uncrossed diplopia — red dots appear to the RIGHT. For exotropia: crossed diplopia — red dots appear to the LEFT of green dots."}'),
  ('cd34027d-2l','{"options": ["Bagolini''s striated glasses", "Red filter test", "Worth 4-Dot test", "Hering-Bielschowsky after-image test"], "correct": 3, "explanation": "The after-image test is the MOST DISSOCIATING — it produces afterimages that persist regardless of whether eyes are open, closed, straight, or deviated, completely separating the two foveal inputs."}'),
  ('e60c3c1a-3y','{"options": ["Harmonious ARC", "Unharmonious ARC", "Suppression of the left eye", "NRC — heteronymous (crossed) diplopia"], "correct": 3, "explanation": "NRC in exotropia produces HETERONYMOUS (crossed) diplopia — red light (right eye filtered) appears to the LEFT of white light. This is the expected response in NRC with exotropia."}'),
  ('6f78bf5b-w','{"options": ["Unequal best-corrected visual acuity between the two eyes", "A difference in refractive error between the two eyes", "Unequal perceived image size between the two eyes", "One eye myopic and the other hyperopic"], "correct": 1, "explanation": "Anisometropia = a difference in refractive ERROR between the eyes (aniso = unequal, metr = measure, opia = eye). Unequal acuity is aniso-oxyopia, unequal image size is aniseikonia, and one-myopic-one-hyperopic is antimetropia."}'),
  ('99e13480-31','{"options": ["0.25 D or greater", "1.00 D or greater", "2.00 D or greater", "6.00 D or greater"], "correct": 2, "explanation": "Thresholds by author (mnemonic HGB = 0.25 / 1.00 / 2.00): Hartstein counts any difference from 0.25 D, Grosvenor uses 1.00 D, and Borish sets 2.00 D or greater as clinically significant."}'),
  ('06139de7-27','{"options": ["Isoanisometropia", "Isometropia", "Antimetropia", "Aniso-oxyopia"], "correct": 2, "explanation": "Antimetropia (mixed anisometropia) is one eye myopic and the other hyperopic. It is the least common form. Isoanisometropia would be the same type of error in both eyes with different magnitude."}'),
  ('1ea25997-28','{"options": ["Refractive error, not acuity", "Visual acuity, not refractive error", "Image size, not acuity", "Ocular alignment, not refraction"], "correct": 1, "explanation": "The suffix oxyopia refers to ACUITY. Iso-oxyopia is equal best-corrected acuity between eyes; aniso-oxyopia is unequal acuity despite full correction. The suffix opia (as in anisometropia) refers to refraction."}'),
  ('611b788f-1x','{"options": ["Unequal magnification between the two lenses", "Changing prism effect as the eyes move away from the optical centers (Prentice effect)", "Suppression of the non-dominant eye", "Eccentric fixation in the amblyopic eye"], "correct": 1, "explanation": "Anisophoria is a difference in heterophoria across gaze positions. With strong lenses the induced prism changes as the eye moves off the optical center (Prentice effect), so the phoria differs in up-gaze versus down-gaze, producing asthenopia."}'),
  ('8a0f53d6-3r','{"options": ["Class I", "Class II", "Class III", "Class IV"], "correct": 2, "explanation": "Class III (generally greater than 3.00 D) shows pronounced amblyopia in the poorer eye that may reach only about 20/100, with peripheral fusion keeping the eyes aligned. Mnemonic Fine-Fusion-Fails-Flip-Fights: Class III = Fails."}'),
  ('59e85062-5s','{"options": ["Class II", "Class III", "Class IV", "Class V"], "correct": 2, "explanation": "Class IV: good acuity in each eye but one eye used at a time (natural monovision), classically emmetropia in one eye with moderate myopia in the other. Class V would involve a muscle imbalance or strabismus."}'),
  ('c2be4ace-3s','{"options": ["2.00 D", "3.00 D", "4.00 D", "6.00 D"], "correct": 3, "explanation": "A difference beyond about 6.00 D is usually left alone. The aniseikonia and prism problems become too great for comfortable fusion, so it is often managed with contact lenses rather than spectacles instead of pushing full spectacle correction."}'),
  ('dfd892d5-3b','{"options": ["Overall (global) symmetrical", "Meridional symmetrical", "Compound symmetrical", "Retinal aniseikonia"], "correct": 1, "explanation": "Meridional aniseikonia differs in a single meridian (usually horizontal or vertical) and is tied to astigmatic errors and their correction. Overall type differs equally in all meridians; compound combines both. Mnemonic: One All, One Line, One Both."}'),
  ('0639ff1c-20','{"options": ["High-index spectacle lenses", "Contact lenses", "Occlusion therapy", "Base-in prism"], "correct": 1, "explanation": "Contact lenses sit on the cornea and minimize the spectacle magnification difference, giving more equal retinal image sizes and better binocular vision. This is why they are preferred over spectacles for anisometropic aniseikonia."}'),
  ('75c1dcc4-26','{"options": ["Dioptric power of the lens", "Shape factor (base curve and thickness) while keeping power constant", "Retinal receptor spacing", "Accommodative demand"], "correct": 1, "explanation": "Spectacle magnification has a shape factor (front base curve plus thickness) and a power factor (power plus vertex distance). Iseikonic lenses adjust the shape factor to change image size while keeping the corrective power the same. They change size, not power."}'),
  ('e769743f-3m','{"options": ["Optical aniseikonia", "Retinal aniseikonia", "Meridional aniseikonia", "Compound aniseikonia"], "correct": 1, "explanation": "Retinal aniseikonia comes from altered spacing of retinal elements (stretched or crowded receptors), as in retinal detachment repair or macular edema. Optical aniseikonia instead comes from unequal lens magnification, such as after unequal spectacle correction or aphakia."}'),
  ('9a88f522-2n','{"options": ["Kevin Tuohy", "Leonardo da Vinci", "Otto Wichterle", "A. E. Fick"], "correct": 1, "explanation": "Leonardo da Vinci first described the concept of a contact lens in 1508. Fick made the first vision-correcting lens (1888); Tuohy the first PMMA corneal lens (1947); Wichterle the first soft (HEMA) lens."}'),
  ('93336fe1-1y','{"options": ["PMMA", "Silicone acrylate", "HEMA (the first soft lens material)", "Cellulose acetate butyrate"], "correct": 2, "explanation": "Otto Wichterle developed HEMA, the first soft (hydrogel) contact lens material. PMMA was the original rigid material (Tuohy, 1947)."}'),
  ('c7e0cfd3-1j','{"options": ["Change the eye color", "Increase myopia", "Protect the cornea and promote epithelial healing", "Replace spectacles for astigmatism"], "correct": 2, "explanation": "Bandage lenses protect the corneal surface and facilitate healing of erosions; they can also act as a drug reservoir, giving longer medication contact time than drops."}'),
  ('39c1757f-15','{"options": ["Adding plus power at near", "Permanently thinning the cornea", "Blocking blue light", "Temporarily reshaping the corneal epithelium during overnight wear"], "correct": 3, "explanation": "Ortho-K gas-permeable lenses worn overnight temporarily reshape the corneal epithelium to reduce myopia and slow its progression, an alternative to daytime correction or surgery."}'),
  ('2e7e4435-1k','{"options": ["It is smaller than 12 mm", "The cornea bears all the lens weight", "It is always soft", "The sclera bears the weight and no part touches the cornea"], "correct": 3, "explanation": "A scleral lens vaults the cornea and rests on the sclera, which carries the lens weight; no part touches the cornea. True sclerals are about 18 mm; mini-sclerals are under 18 mm."}'),
  ('74e61188-1q','{"options": ["18 mm and above", "Less than 12 mm (cornea bears the weight)", "Exactly 20 mm", "12-16 mm"], "correct": 1, "explanation": "Corneal lenses are under 12 mm and the cornea alone bears the weight. Semi-corneal/sclero-corneal lenses are 12-16 mm; sclerals are about 18 mm and up."}'),
  ('93be900e-2s','{"options": ["-2.00 D", "-6.00 D", "-4.00 D", "-0.75 D"], "correct": 3, "explanation": "A spherical lens masks only about -0.75 D of astigmatism; beyond that (with a favorable sphere-to-cylinder ratio you may still use the spherical equivalent) a toric lens is needed."}'),
  ('0e02a92a-15','{"options": ["A glass core", "Two soft lenses fused together", "A rigid gas-permeable center surrounded by a soft/silicone-hydrogel skirt", "A prism-ballasted toric back"], "correct": 2, "explanation": "A hybrid lens combines an RGP optical center with a soft skirt, giving RGP optics with soft comfort, useful in keratoconus that cannot tolerate a full RGP."}'),
  ('d3c965b0-1k','{"options": ["Pupil diameter (even when dilated)", "Corneal diameter", "Palpebral aperture", "Lens total diameter"], "correct": 0, "explanation": "The optic zone must exceed the pupil diameter, including in dim light when the pupil dilates; otherwise the patient gets glare and blur, especially with small-optic-zone RGPs."}'),
  ('9eb1cd98-29','{"options": ["Flatter, to give edge lift, stability, and tear exchange", "Steeper", "The same curvature", "Toric"], "correct": 0, "explanation": "The peripheral curve is flatter than the central curve, providing edge lift, stability on the cornea, and tear exchange behind the lens."}'),
  ('42048f8a-1h','{"options": ["Water content and tint", "Refractive index and thickness", "Wetting angle", "Base curve (BOZR) and diameter"], "correct": 3, "explanation": "Sag is set by the base curve and the diameter. A steeper base curve or a larger diameter increases the sag and tightens the fit."}'),
  ('713935a9-2d','{"options": ["Anterior epithelium and endothelium", "Stroma and Descemet", "Bowman and stroma", "Epithelium and Bowman only"], "correct": 0, "explanation": "The anterior epithelium (continuous regeneration) and the endothelium (pumps water out of the stroma) are metabolically active; hypoxia here causes edema and clouding."}'),
  ('c6ce3e62-17','{"options": ["High", "Medium", "Low", "Zero"], "correct": 0, "explanation": "Dk classification: low <30, medium 30-60, high >60. Higher Dk means better oxygen permeability of the material."}'),
  ('048ce1af-22','{"options": ["50", "10", "87", "25"], "correct": 3, "explanation": "Daily wear requires a Dk/t of about 25 or more; overnight (extended) wear requires about 87 or more to avoid hypoxic complications."}'),
  ('422cf945-22','{"options": ["Stays constant", "Increases", "Decreases", "Becomes zero"], "correct": 2, "explanation": "Higher water content lowers the refractive index, so higher-water materials need a thicker design to achieve a given power, affecting oxygen transmissibility."}'),
  ('72927113-1s','{"options": ["More flexible and better able to follow the cornea", "Higher in water content", "More oxygen permeable", "Stiffer and harder to drape"], "correct": 0, "explanation": "Low modulus means more flexibility, so the lens conforms to the cornea. Early silicone hydrogels had a high modulus (stiff), causing handling and GPC problems."}'),
  ('b8f77eed-25','{"options": ["Zero-charge", "More wettable", "Hydrophilic", "Less wettable"], "correct": 3, "explanation": "A higher wetting angle means the surface is less wettable (water beads up). Hydrophilic soft materials have a zero wetting angle; hydrophobic silicone RGPs are often plasma-treated."}'),
  ('19a9807f-2h','{"options": ["Silicone hydrogel", "Cellulose acetate butyrate", "PMMA", "PHEMA only"], "correct": 0, "explanation": "Silicone hydrogel predominates because its high oxygen transmissibility reduces hypoxic complications and its silicone content limits water evaporation, aiding mild-to-moderate dry eye."}'),
  ('bccf91af-24','{"options": ["Have no water content", "Cannot be tinted", "Take up MORE protein and are more sensitive to pH/osmolality", "Take up less protein"], "correct": 2, "explanation": "Ionic (charged) materials attract more protein deposits and are more sensitive to pH, osmolality, and care-system components than non-ionic materials."}'),
  ('9589dd35-13','{"options": ["Daily disposables", "Extended-wear soft lenses", "Bandage lenses", "Diagnostic trial lenses"], "correct": 3, "explanation": "PMMA has excellent optics but almost zero oxygen permeability, so today it survives mainly as rigid diagnostic (trial) lenses."}'),
  ('426b3936-29','{"options": ["Plasma treatment", "Cast molding", "Spin-casting", "Lathe cutting"], "correct": 2, "explanation": "Spin-casting injects liquid polymer into a spinning mold. Lathe cutting machines a polymer rod; cast molding presses polymer between two molds under heat and pressure."}'),
  ('8602b4e9-1j','{"options": ["D = r / (n - 1)", "D = (n - 1) / r", "D = 1 / (n x r)", "D = n x r"], "correct": 1, "explanation": "Surface power D = (n - 1) / r, with r the radius of curvature in meters and n the material index."}'),
  ('d014949c-1b','{"options": ["Deq = D1 x D2", "Deq = D1 + D2 - (t/n)(D1 x D2)", "Deq = D1 + D2", "Deq = D1 - D2"], "correct": 1, "explanation": "Equivalent power Deq = D1 + D2 - (t/n)(D1 x D2) accounts for the lens thickness t and index n; the nominal power Dn = D1 + D2 ignores thickness."}'),
  ('3efbe6cd-2y','{"options": ["-6.00 D", "-6.47 D", "-5.60 D", "-5.00 D"], "correct": 2, "explanation": "D(CL) = -6.00 / [1 - 0.012 x -6.00] = -6.00 / 1.072 = -5.60 D. A minus lens needs less minus at the cornea."}'),
  ('3afd4c6b-2a','{"options": ["+8.00 D", "+8.85 D", "+9.50 D", "+7.30 D"], "correct": 1, "explanation": "D(CL) = +8.00 / [1 - 0.012 x 8.00] = +8.00 / 0.904 = +8.85 D. A plus lens needs more plus at the cornea (shorter vertex)."}'),
  ('afc969c2-1a','{"options": ["+2.50 D", "+1.50 D", "+1.00 D", "+0.50 D"], "correct": 1, "explanation": "Spherical equivalent = sphere + 1/2 cylinder = +2.00 + (-0.50) = +1.50 D."}'),
  ('a7ffa1c4-17','{"options": ["CLM = D(spec) / d", "CLM = d / D(spec)", "CLM = 1 - d x D(spec)", "CLM = 1 + d x D(spec)"], "correct": 2, "explanation": "CLM = 1 - d x D(spec). For a -10 D lens at 14 mm this is 1.14 (magnified); for +10 D it is 0.86 (minified)."}'),
  ('af0d0fae-2c','{"options": ["Larger", "Smaller", "Doubled", "The same size"], "correct": 1, "explanation": "For a plus lens CLM is less than 1, so the hyperope sees a smaller (more natural) image with contact lenses; myopes see a larger image."}'),
  ('d6d4b28b-3f','{"options": ["Spectacles", "Prisms only", "Contact lenses", "Neither"], "correct": 0, "explanation": "By Knapp''s principle, axial ametropia gives more equal retinal-image sizes when corrected with spectacles, while refractive ametropia is better with contact lenses (near the eye''s plane)."}'),
  ('3447b43b-2j','{"options": ["Refractive", "Unknown", "Axial", "Neurological"], "correct": 0, "explanation": "When corneal power tracks the refractive error (e.g., steep cornea with myopia), the ametropia is refractive in nature and favors contact-lens correction."}'),
  ('356768c6-1r','{"options": ["No oblique astigmatism, no distortion, no field-of-view limit", "Larger prismatic effects", "More chromatic aberration", "Spectacle-frame diplopia"], "correct": 0, "explanation": "Contact lenses move with the eye and sit at the corneal plane, eliminating oblique astigmatism, distortion, chromatic aberration, field-of-view limits, and frame diplopia."}'),
  ('cb5b3bb1-1x','{"options": ["Fluorescein angiography", "Tear break-up time", "Tear meniscus (prism) height", "Rose bengal staining"], "correct": 2, "explanation": "Tear meniscus (prism) height is the contact-lens gold standard for tear volume, though it is small (a fraction of a millimeter) and hard to measure on the slit lamp."}'),
  ('615dc0ce-2b','{"options": ["Measure tear quality", "Test drainage", "Avoid touching the sensitive cornea and triggering reflex tearing", "Increase the reading"], "correct": 2, "explanation": "Placing the strip about 5 mm from the lateral (temporal) canthus keeps it off the sensitive cornea, preventing reflex tearing that would falsely raise the volume reading."}'),
  ('3ed5ec15-1o','{"options": ["Volume", "Quality/stability", "Osmolality", "Drainage patency"], "correct": 1, "explanation": "TBUT assesses tear quality/stability (time for the film to break up after a blink) using fluorescein. Schirmer and meniscus height measure volume; Jones test measures drainage."}'),
  ('1aa6d02c-15','{"options": ["7.4 (slightly alkaline)", "6.0", "9.0 (strongly alkaline)", "5.5 (acidic)"], "correct": 0, "explanation": "Tear film is slightly alkaline at about pH 7.4. Contact-lens solutions range 6.5-8.0; a large mismatch can burn the ocular surface."}'),
  ('96d24bb2-v','{"options": ["50 per minute", "2 per minute", "5 per minute", "24 per minute"], "correct": 3, "explanation": "The average blink rate is about 24/min (range 10-34). Blinking spreads the tear film and keeps the lens wet and comfortable."}'),
  ('0dd12537-21','{"options": ["No addition", "5 mm", "2.0 mm (low water) to 2.5 mm (high water)", "0.5 mm"], "correct": 2, "explanation": "Soft total diameter = HVID + 2.0 mm for low-water lenses or + 2.5 mm for high-water lenses (which shrink slightly on the eye)."}'),
  ('acc67508-1l','{"options": ["3-4 mm of movement", "It should slide off the cornea", "No movement at all", "About 0.3-0.5 mm with good centration and full coverage"], "correct": 3, "explanation": "A good soft fit shows full corneal coverage, good centration, and about 0.3-0.5 mm of movement on blink. No movement suggests a tight fit; excessive movement a loose fit."}'),
  ('378aa5be-2b','{"options": ["Toric", "Flat/loose", "Optimally", "Steep/tight"], "correct": 1, "explanation": "Excessive movement, poor centration, and discomfort indicate a flat/loose fit. A steep/tight fit shows little or no movement and feels bound."}'),
  ('a4e8fda2-2f','{"options": ["-10.00 and -15.00 D", "Plano and -0.50 D", "-3.00 and -6.00 D", "-1.00 and -2.00 D"], "correct": 2, "explanation": "About -3.00 D (low minus) and -6.00 D (high minus) trial powers are recommended so the trial fit resembles the ordered lens; +2.00 and +5.00 D are used for plus fits."}'),
  ('dc1f0dd8-1q','{"options": ["Plano tear lens", "Plus tear lens", "A negative meniscus", "Minus tear lens"], "correct": 0, "explanation": "An aligned lens sits parallel to the cornea and shows an even thin fluorescein film, giving a plano tear lens. Flat fits give a minus tear lens; steep fits a plus tear lens."}'),
  ('b877dfe4-u','{"options": ["CL prescription - (trial BVP + over-refraction)", "Trial BVP - over-refraction", "Over-refraction only", "CL prescription + trial BVP + over-refraction"], "correct": 0, "explanation": "Tear lens = CL prescription - (trial-lens BVP + over-refraction). Rearranged, CL prescription = trial BVP + over-refraction + tear lens."}'),
  ('3f4565c3-34','{"options": ["It is faster to skip fluorescein", "Fluorescein is toxic", "The over-refraction predicts whether the fit is flat, steep, or aligned, letting you jump to the right base curve", "Over-refraction requires dilation"], "correct": 2, "explanation": "The over-refraction reveals the tear-lens sign (flat/steep/aligned), so you can predict and select the next base curve instead of trialing many curves, saving time."}'),
  ('8a092093-2h','{"options": ["20-30 minutes", "1 full day", "Immediately", "2 hours"], "correct": 0, "explanation": "Allow about 20-30 minutes for adaptation and settling before assessing the fit; premature assessment causes reflex tearing and a misleading (unstable) appearance."}'),
  ('3867b0b7-2x','{"options": ["0.1 mm", "0.6 mm", "0.3 mm", "1.0 mm"], "correct": 2, "explanation": "Rule of thumb: a 0.5 mm change in total diameter is balanced by a 0.3 mm change in BOZR in the same direction to keep a comparable fit."}'),
  ('f26da9e7-29','{"options": ["Corneal astigmatism", "No astigmatism", "Residual (lenticular) astigmatism", "Both corneal and residual"], "correct": 2, "explanation": "A front-surface toric corrects residual (lenticular) astigmatism; a back-surface toric corrects corneal astigmatism; a bitoric corrects both."}'),
  ('d6a0adf6-15','{"options": ["90 degrees", "30 degrees temporal", "No rotation ever", "5-10 degrees nasal"], "correct": 3, "explanation": "Average toric lens rotation is about 5-10 degrees nasal, with the upper lid as the dominant stabilizing force; individual variation requires axis compensation."}'),
  ('fab5fdfd-25','{"options": ["Prism ballast", "Reverse prism", "Double slab-off", "Truncation"], "correct": 3, "explanation": "Truncation removes a segment (usually inferior) so the flat edge aligns with the lower lid margin; it can cause discomfort and is not always successful."}'),
  ('a75f9b69-2o','{"options": ["Monovision", "Alternating bifocal", "Bitoric", "Simultaneous multifocal"], "correct": 0, "explanation": "Monovision corrects the dominant eye for distance and the non-dominant eye for near; it is simple but reduces stereopsis."}'),
  ('7d3afd6e-1l','{"options": ["Uses only one eye", "Switches lenses for near", "Views through the distance and near portions at the same time", "Looks through the top for distance and bottom for near"], "correct": 2, "explanation": "Simultaneous-vision designs present distance and near powers together so the retina receives both; alternating (translating) designs use separate distance-top and near-bottom zones."}'),
  ('3addb9b5-1c','{"options": ["900 mOsm/kg", "302 mOsm/kg", "500 mOsm/kg", "150 mOsm/kg"], "correct": 1, "explanation": "Average tear osmolality is about 302 mOsm/kg; a higher value indicates dry eye (tears more concentrated in salt)."}'),
  ('efe85fb5-28','{"options": ["0.9%", "5.0%", "2.0%", "0.45%"], "correct": 0, "explanation": "Isotonic = 0.9% NaCl, matching cell tonicity. Hypotonic is under 0.9% (lens swells) and hypertonic is over 0.9% (lens shrinks)."}'),
  ('523276a6-1o','{"options": ["Ammonia / ammonium", "Sodium hydroxide / water", "Boric acid / sodium borate", "Sodium bicarbonate / carbonic acid"], "correct": 2, "explanation": "Borate (boric acid + sodium borate), citrate, and phosphate buffer pairs resist pH change in contact-lens solutions."}'),
  ('350b7d06-1r','{"options": ["Neither", "Alkaline burn", "Acid burn", "Both equally mild"], "correct": 1, "explanation": "Alkaline (basic) burns penetrate deeper and are the ocular emergency; this is why the pH compatibility of a contact-lens solution matters."}'),
  ('5584bb08-19','{"options": ["Chemical agents such as alcohol", "Surfactants", "Physical means such as heat, UV, or autoclave", "Preservatives only"], "correct": 2, "explanation": "Sterilization uses physical means (heat, UV, boiling, autoclave). Disinfection uses chemical agents (alcohol, hydrogen peroxide) to reduce microbial load."}'),
  ('473dd60d-2a','{"options": ["Staphylococcus", "All bacteria", "Fungi only", "Pseudomonas aeruginosa"], "correct": 3, "explanation": "BAK protects against most organisms but has reduced efficacy against Pseudomonas aeruginosa, an important cause of contact-lens microbial keratitis."}'),
  ('991803e4-y','{"options": ["Adding water content", "Breaking protein bonds enzymatically", "Dissolving loosely bound deposits so they rinse off", "Neutralizing peroxide"], "correct": 2, "explanation": "Surfactant (surface-active) cleaners loosen and lift loosely bound surface deposits so they can be rinsed away. Enzymatic cleaners break protein bonds, mainly for conventional lenses."}'),
  ('e5491ab3-1w','{"options": ["Excess oxygen", "Ultraviolet light only", "High tear volume", "Chronic hypoxia (oxygen deprivation)"], "correct": 3, "explanation": "New vessels grow to supply an oxygen-starved cornea; risk rises with overwear, thick/low-Dk lenses, or stacked lenses. Manage with a higher-Dk lens and reduced wear."}'),
  ('81fb2aa3-28','{"options": ["Costs more", "Looks unnatural", "Starves the central cornea of oxygen (double barrier)", "Cannot be cleaned"], "correct": 2, "explanation": "Two lenses on the cornea double the oxygen barrier, reducing oxygen to the central cornea and risking hypoxia and neovascularization."}'),
  ('5860ab20-1t','{"options": ["Corneal arcus", "A hyphema", "Papillae on the upper tarsal conjunctiva with lens intolerance", "A cherry-red macula"], "correct": 2, "explanation": "GPC produces large papillae on the upper tarsus from lens deposits and mechanical irritation, causing itching and contact-lens intolerance."}'),
  ('58003e18-2l','{"options": ["Microbial keratitis (e.g., Pseudomonas, Acanthamoeba)", "A visibility tint", "Mild dryness", "Spectacle blur"], "correct": 0, "explanation": "Microbial keratitis is the most sight-threatening complication; Pseudomonas and Acanthamoeba are linked to overnight wear, poor hygiene, and water exposure."}'),
  ('721c8899-u','{"options": ["The first soft lens", "The first RGP lens", "The concept of the contact lens", "The first contact lens intended to correct vision"], "correct": 3, "explanation": "A. E. Fick described the first contact lens intended to correct vision (a glass scleral) in 1888. Da Vinci conceived the idea (1508); Tuohy made the first PMMA corneal lens (1947)."}'),
  ('a1e2e221-26','{"options": ["John Herschel", "Otto Wichterle", "F. E. Muller", "Kevin Tuohy"], "correct": 3, "explanation": "Kevin Tuohy made the first PMMA plastic corneal lens in 1947, improving durability and centration over glass scleral lenses, though still non-oxygen-permeable."}'),
  ('54fbb94e-2g','{"options": ["Tricurve", "Monocurve", "Bicurve", "Aspheric"], "correct": 2, "explanation": "The bicurve design (central + peripheral curve) is the most widely available. Monocurve is obsolete; tricurve suits ortho-K/irregular corneas; aspheric follows the cornea''s shape."}'),
  ('f15f663b-1h','{"options": ["Uniform single curvature", "Steeper center that flattens toward the periphery, following the cornea", "Truncated edge", "Toric back surface"], "correct": 1, "explanation": "Aspheric designs are steeper centrally and flatter peripherally to mimic the cornea''s natural asphericity, which is steeper centrally and flattens toward the periphery."}'),
  ('8da653d8-1o','{"options": ["Make the lens easier to see and handle", "Change the eye color permanently", "Correct astigmatism", "Block ultraviolet light"], "correct": 0, "explanation": "A visibility (handling) tint (usually blue/green) makes the lens easier to find and handle in solution or on the eye; it does not change the apparent eye color like an opaque tint."}'),
  ('03015f1b-20','{"options": ["Are the cheapest option", "Have zero oxygen needs", "Can be worn without removal to promote epithelial healing", "Are always toric"], "correct": 2, "explanation": "Continuous-wear lenses can stay in place for up to two weeks without removal, making them well suited as bandage lenses that promote healing of the corneal epithelium."}'),
  ('44cd9daf-27','{"options": ["Corneal hypoxia from lens wear", "Excess oxygen", "Allergic conjunctivitis", "Dry eye only"], "correct": 0, "explanation": "These are short-term hypoxic signs of oxygen deprivation under a lens; long-term hypoxia causes corneal distortion, endothelial disruption, and refractive change."}'),
  ('d9055f80-31','{"options": ["More wettable while keeping high oxygen permeability", "Softer", "Cheaper", "Non-permeable"], "correct": 0, "explanation": "Adding fluorine to silicone acrylate lowers the surface charge and improves wettability while maintaining silicone-like oxygen permeability (Dk 40-100), making FSA the common modern RGP."}'),
  ('820821d4-22','{"options": ["38%", "10%", "55%", "75%"], "correct": 0, "explanation": "PHEMA (poly-HEMA) has about 38% water. It is a close relative of PMMA made hydrophilic by adding a hydroxyl group."}'),
  ('ea79ecee-2j','{"options": ["4%", "21%", "9-10%", "15%"], "correct": 2, "explanation": "About 9-10% oxygen is the minimum for safe daily (open-eye) wear and avoiding edema; roughly 12% is the minimum for extended wear and higher levels avoid microcysts and polymegethism."}'),
  ('86eeb144-1v','{"options": ["Dv = Dn - (t/n)(D2)²", "Dv = D1 x D2", "Dv = Dn / t", "Dv = Dn + (t/n)(D1)²"], "correct": 3, "explanation": "Back vertex (effective) power Dv = Dn + (t/n)(D1)² uses the front-surface power squared; the front vertex (neutralizing) power uses (D2)²."}'),
  ('9a0bec75-2g','{"options": ["Axial", "Refractive", "Neurological", "Purely astigmatic"], "correct": 1, "explanation": "Aphakia is a refractive ametropia; when IOLs are not implanted (e.g., young children with congenital cataract) contact lenses are preferred over very thick, aberration-prone aphakic spectacles."}'),
  ('738746eb-24','{"options": ["No optical problem", "Meridional aniseikonia (unequal image size in the two meridians)", "Improved fusion", "Reduced accommodation"], "correct": 1, "explanation": "Spectacle correction of high corneal astigmatism creates meridional aniseikonia (one meridian''s image larger than the other), which contact lenses avoid, favoring soft toric or RGP lenses."}'),
  ('ee92d6bf-1r','{"options": ["Precipitate the need for a near add", "Cause immediate presbyopia", "Postpone the need for a near add", "Have no effect on accommodation"], "correct": 2, "explanation": "A hyperope needs LESS accommodation with contact lenses, so the need for a reading addition may be postponed. A myope needs more accommodation and may need a near add sooner."}'),
  ('f2fe3aba-1y','{"options": ["Snellen and LogMAR", "Amsler and tangent screen", "Efron and Brien Holden grading scales", "Ishihara and D-15"], "correct": 2, "explanation": "The Efron, Brien Holden, and CIBA Vision grading scales standardize documentation of anterior-segment signs at baseline and follow-up."}'),
  ('171f4287-2t','{"options": ["2 mm", "5 mm", "Equal to HVID", "0.5 mm"], "correct": 0, "explanation": "An RGP diameter about 2 mm smaller than the HVID is a typical starting point, though lid position is a more important criterion than HVID alone."}'),
  ('3119e6f7-1t','{"options": ["Within +/- 0.10 mm of the flattest corneal radius", "1 mm flatter than the flattest K", "2 mm steeper than the flattest K", "Equal to the steepest K"], "correct": 0, "explanation": "The initial RGP BOZR is set at about +/- 0.10 mm of the flattest corneal radius, then refined by dynamic and static (fluorescein) fitting assessment."}'),
  ('be3fefdf-22','{"options": ["3 mm", "No addition", "0.7 mm or more for thicker/low-water lenses", "0.1 mm"], "correct": 2, "explanation": "Add about 0.7 mm or more to the flattest K for thicker, low-water lenses, and 0.3-0.6 mm for thin, high-water lenses. Typical soft BOZR range is 7.9-9.3 mm."}'),
  ('567f22aa-z','{"options": ["High motivation and a moderate-to-high prescription (or an irregular cornea)", "Low prescription and low motivation", "No refractive error", "Severe dry eye and low motivation"], "correct": 0, "explanation": "RGP candidates should be highly motivated (initial discomfort) with a moderate-to-high prescription so the visual benefit justifies the adaptation; irregular corneas also benefit from RGPs."}'),
  ('aaa643cf-1f','{"options": ["Purely residual", "Purely corneal", "Absent", "Both corneal and residual"], "correct": 3, "explanation": "A bitoric lens (toric on both surfaces) addresses astigmatism arising from both the corneal surface and residual/lenticular sources, though it is uncommon."}'),
  ('77378e57-32','{"options": ["Reverse prism", "Truncation", "Prism ballast", "Double slab-off"], "correct": 2, "explanation": "Prism ballast adds 1-1.5 prism diopters base-down; the extra inferior thickness stabilizes the axis but reduces oxygen and can cause lid discomfort."}'),
  ('0c725716-1z','{"options": ["Thinner and symmetrical with thin zones superiorly and inferiorly", "Truncated", "Thicker and asymmetrical", "Prism-ballasted"], "correct": 0, "explanation": "Double slab-off creates thin zones both superiorly and inferiorly, giving a thinner, symmetrical lens with better comfort and oxygen than prism ballast, held by lid forces."}'),
  ('11efe2fc-1c','{"options": ["Preservative strength", "Thickness", "Total salt concentration", "pH"], "correct": 2, "explanation": "Osmolality describes the total salt concentration (mOsm/kg). Tonicity describes the solution''s effect on cell shape (hypotonic, isotonic, hypertonic)."}'),
  ('4c0d278a-1x','{"options": ["Add oxygen", "Kill bacteria", "Increase the contact time of the solution on the lens/eye", "Lower the pH"], "correct": 2, "explanation": "Viscosity-enhancing agents thicken solutions so they stay on the lens/ocular surface longer, improving daily-cleaner rubbing action and rewetting-drop contact time."}'),
  ('70966090-1v','{"options": ["Buffers", "Viscosity agents", "Bacteriostatic preservatives", "Surfactants"], "correct": 2, "explanation": "Thimerosal, BAK, chlorhexidine, sorbic acid/EDTA, Dymed, and Polyquad are bacteriostatic preservatives/antimicrobials in lens-care products."}'),
  ('3f1f23c8-1o','{"options": ["Lipid", "Iron", "Calcium", "Protein (by breaking protein bonds)"], "correct": 3, "explanation": "Enzymatic cleaners break the bonds holding protein deposits together; they were mainly used for conventional lenses and are largely obsolete with disposables."}'),
  ('b704583f-22','{"options": ["Discolor", "Shrink", "Keep its shape", "Swell (gain water)"], "correct": 3, "explanation": "In a hypotonic solution water moves into the lens (higher internal salt), so the lens swells and gains water; a hypertonic solution shrinks it."}'),
  ('e7396ee0-1k','{"options": ["No prismatic effect", "Improved centration", "Ghosting of images", "Wider field of view"], "correct": 2, "explanation": "A decentered lens produces ghosting; a rotating toric lens produces a toric over-refraction and reduced vision, and moving lenses cause visual disturbances."}'),
  ('3c63569c-16','{"options": ["Patient comfort (a wider PCW is more comfortable)", "Refractive index", "Water content", "Optical power"], "correct": 0, "explanation": "The peripheral curve contacts the sclera/peripheral cornea; a larger peripheral curve width generally improves comfort."}'),
  ('4f04171f-1z','{"options": ["Steeper", "Toric", "Flatter", "Wider"], "correct": 0, "explanation": "As the RGP base curve steepens, its optic zone shrinks; if the optic zone becomes smaller than the pupil, the patient experiences glare and blur, especially at night."}'),
  ('d94e3e19-2o','{"options": ["iOptik lens", "Wink-activated telescope lens", "Google glucose lens", "Triggerfish sensor lens"], "correct": 3, "explanation": "The SENSIMED Triggerfish is a soft disposable lens with an embedded micro-sensor that monitors IOP-related changes in glaucoma patients. The Google lens monitored tear glucose."}'),
  ('81f1f101-1i','{"options": ["Ratio of diameter to base curve", "Ratio of water to polymer", "Ratio of Dk to thickness", "Sphere-to-cylinder ratio that permits a spherical-equivalent lens"], "correct": 3, "explanation": "The 4:1 rule means the sphere must be at least four times the cylinder (with cylinder under 1.00 D) to justify prescribing a spherical lens using the spherical equivalent."}'),
  ('efe5c55d-2j','{"options": ["Daily disposable soft", "PMMA / rigid lenses", "Bandage soft lens", "Silicone hydrogel"], "correct": 1, "explanation": "Rigid (PMMA) lenses mold the cornea, causing transient spectacle blur and corneal warpage, so they are stopped ~3 weeks before refractive surgery and before keratometry/topography."}'),
  ('1b9829af-2r','{"options": ["Excessive water loss", "Low oxygen", "Stiffness making them hard to remove, plus giant papillary conjunctivitis", "Dissolving in saline"], "correct": 2, "explanation": "First-generation silicone hydrogels had a high (stiff) modulus, so they were rubbery and hard to remove and caused mechanical GPC; later generations added wetting surface treatments."}'),
  ('eea8e852-2o','{"options": ["Prism ballast", "The lens material", "Truncation", "The tear (fluid) lens formed beneath the rigid lens"], "correct": 3, "explanation": "A rigid lens creates a tear (fluid) lens between its spherical back surface and the toric cornea, neutralizing corneal astigmatism without a toric lens."}'),
  ('e26c7955-2o','{"options": ["A larger diameter only", "A toric RGP lens", "Stopping lens wear", "A flatter base curve only"], "correct": 1, "explanation": "A significant residual cylinder on over-refraction indicates that a spherical RGP is not fully correcting the astigmatism, so a toric RGP (or bitoric) should be considered."}'),
  ('7b1bd694-1w','{"options": ["With prism ballast", "With low water content", "As thick as possible", "Thin, to provide sufficient oxygen to the cornea"], "correct": 3, "explanation": "For extended/flexible wear a hydrogel lens should be thin to raise Dk/t and supply enough oxygen overnight; silicone hydrogel is preferred for its high oxygen."}'),
  ('6d07a1c8-14','{"options": ["High-velocity impact damage", "Horizontal vertex iris distance; the base curve", "Horizontal visible iris diameter; the lens total diameter", "Hydrated volume index of diameter"], "correct": 2, "explanation": "HVID (horizontal visible iris diameter) is measured (PD rule, graticule, or comparator) to help select the lens total diameter."}'),
  ('b61fd4c5-1j','{"options": ["Always add 10 degrees", "Reverse the cylinder sign", "Ignore rotation", "Left Add, Right Subtract the observed rotation"], "correct": 3, "explanation": "LARS: if the lens rotates Left (anticlockwise), Add that amount to the axis; if it rotates Right (clockwise), Subtract, to compensate the ordered axis for lens rotation."}'),
  ('572f8d4e-1z','{"options": ["Secrete mucin", "Pump water out of the corneal stroma to keep it clear", "Produce tears", "Regenerate epithelial cells"], "correct": 1, "explanation": "The endothelium pumps water out of the stroma to maintain corneal clarity; when hypoxia impairs this pump, fluid accumulates and the cornea develops edema."}'),
  ('52fcc87a-1z','{"options": ["Higher tensile strength and lower protein uptake", "More discoloration", "Higher oxygen permeability", "Lower tensile strength"], "correct": 0, "explanation": "Low-water lenses have higher tensile strength, lower protein uptake (longer life), and good stability, and do not absorb preservatives; high-water lenses have higher oxygen but lower strength."}'),
  ('a5d430fb-1u','{"options": ["Jones test", "Schirmer test", "Osmolality", "TBUT"], "correct": 0, "explanation": "The Jones test assesses lacrimal drainage patency. Schirmer and meniscus height measure volume; TBUT measures quality; osmolality measures salt concentration."}'),
  ('e401f8f0-1z','{"options": ["Limbus", "Pupil", "Lower lid margin", "Upper lid margin"], "correct": 2, "explanation": "Truncation aligns the flat (truncated) inferior edge with the lower lid margin to resist rotation, at the cost of some discomfort."}'),
  ('d0db355a-1s','{"options": ["Prism-ballasted", "Much smaller than average", "Slightly larger than average (up to ~0.5 mm)", "Truncated"], "correct": 2, "explanation": "Plus lenses are heavier centrally and ride low, so making them up to about 0.5 mm larger than average improves centration; high-BVP lenses (> +/-8 D) are also made larger for lenticulation."}'),
  ('42ccd210-1v','{"options": ["Fluorescein first, then let it settle", "Only fluorescein, never over-refract", "Refract immediately, no settling", "Let it settle 20-30 min, do over-refraction, then fluorescein assessment"], "correct": 3, "explanation": "Insert and let the lens settle 20-30 minutes, perform the over-refraction (to predict flat/steep/aligned), then confirm with the fluorescein assessment; this is faster and more reliable."}'),
  ('65aac7b3-25','{"options": ["The study, knowledge, or science of law", "The power of the state to punish", "The moral duty of a professional", "The practice of medicine"], "correct": 0, "explanation": "Jurisprudence derives from the Latin juris prudentia, meaning the study, knowledge, or science of law."}'),
  ('b217c7db-2v','{"options": ["Jurisprudence", "Ethics", "Litigation", "Legislation"], "correct": 1, "explanation": "Ethics is the branch of knowledge that deals with moral principles; it governs conduct. Jurisprudence is the science of law."}'),
  ('3c528c64-5l','{"options": ["Positivism", "Formalism", "Legal realism", "Naturalism"], "correct": 0, "explanation": "Positivists hold that law and morality are separate, and the only law is that expressly enacted. Naturalists, by contrast, include morality, religion, and reason as sources of law."}'),
  ('b4a7ef2d-2y','{"options": ["Legal realism", "Positivism", "Naturalism", "Formalism (conceptualism)"], "correct": 3, "explanation": "Formalism, or conceptualism, treats law like math or science. Legal realism holds that judges must balance interests and draw an arbitrary line."}'),
  ('12b55fe0-5c','{"options": ["Police power", "Judicial power", "Eminent domain", "Executive privilege"], "correct": 0, "explanation": "Police power is the power of the legislature to enact reasonable laws for public welfare; it is the constitutional basis for regulating professions like optometry."}'),
  ('ebdfa55c-1t','{"options": ["The Optometry Law of 1917", "RA 8050", "Public Act No. 2245", "RA 1998"], "correct": 0, "explanation": "The Optometry Law of 1917 was the first regulatory law in Philippine optometry; it was later amended in 1919."}'),
  ('f70b8625-1e','{"options": ["1918", "1932", "1913", "1919"], "correct": 3, "explanation": "The Optometry Law of 1917 was amended in 1919."}'),
  ('90cc04f1-27','{"options": ["The Board of Optical Examiners", "The Board of Optometry", "The Junta Examinadora", "The Professional Regulation Commission"], "correct": 0, "explanation": "Public Act No. 2245 (Feb 11, 1913) created the Board of Optical Examiners, originally under the Department of Interior (later under the Department of Public Instruction after the 1932 reorganization)."}'),
  ('356d736a-1g','{"options": ["Regulated the practice of optometry, amending the Optometry Law of 1917", "Established the six-year optometry course", "Created the PRC", "Created the CPD Council"], "correct": 0, "explanation": "RA 1998 (June 22, 1957) regulated the practice of optometry, amending/repealing the earlier optometry law. It was later repealed and superseded by RA 8050."}'),
  ('75ad457b-2j','{"options": ["RA 10912", "RA 8050", "RA 1998", "RA 8981"], "correct": 1, "explanation": "RA 8050, the Revised Optometry Law of 1995, is the current law regulating optometry. It replaced RA 1998."}'),
  ('7e01b906-u','{"options": ["The Revised Optometry Law of 1995", "The Optometry Modernization Act", "The Optometry Law of 1917", "The PRC Modernization Act"], "correct": 0, "explanation": "RA 8050 shall be known and cited as the Revised Optometry Law of 1995."}'),
  ('f33a6acc-x','{"options": ["An Act Modernizing the Professional Regulation Commission", "An Act Providing for Continuing Professional Development", "An Act Regulating the Practice of Optometry, Upgrading Optometric Education, Integrating Optometrists, and for Other Purposes", "An Act to Regulate the Practice of Optometry in the Philippines"], "correct": 2, "explanation": "RA 8050 is titled ''An Act Regulating the Practice of Optometry, Upgrading Optometric Education, Integrating Optometrists, and for Other Purposes.''"}'),
  ('0663c269-1e','{"options": ["Making optometry a graduate-only degree", "A two-year associate course", "Upgrading the optometry course from four years to a six-year program", "Removing pharmacology from the curriculum"], "correct": 2, "explanation": "RA 8050 upgraded optometric education by providing for a six-year Doctor of Optometry course. The first year of implementation began in SY 1998-1999."}'),
  ('a2165bc3-2d','{"options": ["Board of Optometry Resolution No. 01, Series of 2008", "PRC Resolution No. 1032, Series of 2017", "Board Resolution No. 07, Series of 1995", "PRC Resolution No. 2019-1146"], "correct": 0, "explanation": "Board of Optometry Resolution No. 01, Series of 2008 is the Rules and Regulations governing the examination, registration, and practice of optometrists (the IRR of RA 8050)."}'),
  ('475b675c-2m','{"options": ["The Supreme Court", "The Department of Health", "The Professional Regulation Commission", "The duly integrated and accredited national organization of optometrists (adopted by the Board upon PRC approval)"], "correct": 3, "explanation": "The Code of Professional Ethics is prescribed by the duly integrated and accredited national organization of optometrists (IPAO), then adopted and promulgated by the Board of Optometry upon approval by the Commission."}'),
  ('600ccae7-s','{"options": ["The science and art of examining the human eye and analyzing ocular function, prescribing and dispensing lenses, and using authorized DPAs, among other measures", "The dispensing of medicines for the eye", "The manufacture and sale of eyeglasses only", "The surgical treatment of eye disease"], "correct": 0, "explanation": "Under RA 8050, optometry is the science and art of examining the human eye, analyzing ocular function, prescribing and dispensing ophthalmic devices, conducting vision training, installing prosthetics, and using authorized DPAs, among other measures."}'),
  ('db8bca68-v','{"options": ["Any graduate of a Doctor of Optometry course", "A natural person certified by the Board of Optometry and registered with the PRC as qualified to practice optometry in the Philippines", "Anyone who dispenses eyeglasses", "A physician with eye training"], "correct": 1, "explanation": "An optometrist is a natural person who has been certified by the Board of Optometry and registered with the PRC as qualified to practice optometry in the Philippines."}'),
  ('3f8095ca-1c','{"options": ["Only a valid professional identification card", "A diploma from an accredited school", "A valid certificate of registration AND a valid professional identification card (professional license)", "Only a valid certificate of registration"], "correct": 2, "explanation": "An optometrist in good standing is authorized to practice by virtue of BOTH a valid certificate of registration and a valid professional identification card (professional license)."}'),
  ('5d0b5949-2h','{"options": ["Renewed every three years", "Issued annually with the PTR", "Valid only in the region of practice", "Permanent, signed by the PRC Chairperson and the Board, serving as proof the registrant is qualified to practice"], "correct": 3, "explanation": "The Certificate of Registration is a permanent (non-expiring) document, signed by the PRC Chairperson and all Board members, that serves as proof the registrant is qualified to practice. The PIC, by contrast, is the renewable card."}'),
  ('f25586d9-26','{"options": ["The same as the certificate of registration", "A renewable card issued by the PRC, evidence that the bearer is an optometrist in good standing", "Issued by the Board of Optometry only", "A permanent, non-expiring document"], "correct": 1, "explanation": "The PIC is a renewable card issued by the Commission (PRC) indicating the holder is competent and authorized to practice; it is evidence of good standing until its expiration."}'),
  ('9a583edf-28','{"options": ["Every year", "Every five years", "Every two years", "Every three years, on the birth month of the optometrist"], "correct": 3, "explanation": "The PIC is renewed every three (3) years on the birth month of the registered optometrist, upon payment of the annual registration fees for three years."}'),
  ('654249fa-1g','{"options": ["Advertising in newspapers", "Offering free eye screenings in a hospital", "Conducting eye examinations while carrying optical merchandise for concurrent sale, going place to place selling to potential customers", "Displaying the certificate of registration"], "correct": 2, "explanation": "Canvassing is when a person or optometrist conducts eye examinations, carries optical merchandise for concurrent sale and delivery, and goes from place to place selling to potential customers (often using audiovisual devices, public address systems, or shouting). It is a prohibited/unethical act."}'),
  ('6f5d0882-2i','{"options": ["Prescription and dispensing of ophthalmic lenses and contact lenses", "Counseling patients on vision and eye hygiene", "Surgical excision of a pterygium", "Conduct of ocular exercises and vision training"], "correct": 2, "explanation": "Surgery is outside the optometric scope. RA 8050 covers examination, prescribing/dispensing, ocular exercises/vision training/orthoptics, prosthetics, counseling, and establishing offices and collecting professional fees."}'),
  ('172936db-2s','{"options": ["By the PRC Commissioner", "By the Board of Optometry, upon approval by the Secretary of the DOH and recommendation of the BFAD (now FDA)", "By the Department of Trade and Industry", "By the Board of Optometry alone"], "correct": 1, "explanation": "DPAs are specified by the Board of Optometry upon approval by the Secretary of the Department of Health (DOH) and upon recommendation of the Bureau of Food and Drugs (BFAD, now the FDA)."}'),
  ('a61e39b0-31','{"options": ["Phenylephrine 2.5%", "Timolol 0.5%", "Tropicamide 0.5%", "Proparacaine 0.5%"], "correct": 1, "explanation": "Timolol is a therapeutic anti-glaucoma beta-blocker, not a DPA. The authorized DPAs are Phenylephrine 2.5%, Tropicamide 0.5%, Proparacaine 0.5%, Benoxinate (Oxybuprocaine) HCl 0.4%, Cyclopentolate HCl 1.0%, and Fluorescein strips."}'),
  ('211b3b10-1k','{"options": ["Proparacaine 0.5%", "Fluorescein", "Phenylephrine 2.5%", "Cyclopentolate HCl 1.0%"], "correct": 3, "explanation": "Cyclopentolate HCl 1.0% is the cycloplegic. Tropicamide 0.5% is primarily a mydriatic (weak cycloplegic); Phenylephrine 2.5% is a mydriatic; Proparacaine and Benoxinate are anesthetics; Fluorescein is a dye."}'),
  ('1213aa8c-1t','{"options": ["Oxybuprocaine", "Proparacaine", "Lidocaine", "Tetracaine"], "correct": 0, "explanation": "Benoxinate is another name for Oxybuprocaine, a topical anesthetic. The RA 8050 statutory list uses ''Oxybuprocaine HCl 0.4%,'' while the IRR list uses ''Benoxinate HCl 0.4%'' — the same agent."}'),
  ('f07c45ac-2r','{"options": ["Proparacaine 0.5%", "Tropicamide", "Phenylephrine", "Cyclopentolate"], "correct": 0, "explanation": "Proparacaine 0.5% (and Benoxinate/Oxybuprocaine 0.4%) are the authorized topical anesthetics. Phenylephrine, Tropicamide, and Cyclopentolate are mydriatic/cycloplegic agents."}'),
  ('b17a89ca-35','{"options": ["Take a pharmacology course prescribed by CHED and pass a special certification examination administered by the Board", "Apply for a new certificate of registration", "Nothing; they are automatically authorized", "Re-take the entire licensure examination"], "correct": 0, "explanation": "Optometrists admitted before RA 8050 (typically four-year-course graduates) must take a pharmacology course prescribed by CHED and pass a special certification examination given by the Board before using DPAs."}'),
  ('f8229e5b-30','{"options": ["Exempt from the licensure exam", "The first authorized by law to use diagnostic pharmaceutical agents (DPAs) in practice", "The first to take the PRC licensure exam", "The first to be integrated into one organization"], "correct": 1, "explanation": "The first graduates of the six-year curriculum (2004) were authorized by law to use DPAs in their practice, since pharmacology was integrated into their curriculum."}'),
  ('755a45a4-1b','{"options": ["Seven (7)", "Three (3)", "Five (5)", "Nine (9)"], "correct": 2, "explanation": "The Board of Optometry is composed of five (5) members appointed by the President of the Philippines."}'),
  ('3bc0ea5d-43','{"options": ["Five (5) nominees", "Fifteen (15) nominees", "Three (3) nominees", "Ten (10) nominees"], "correct": 3, "explanation": "The President appoints Board members, upon PRC recommendation, from a list of ten (10) nominees submitted by the duly integrated and accredited national organization of optometrists."}'),
  ('9bdc7828-25','{"options": ["At least 35 years of age at the time of appointment", "A natural-born citizen of the Philippines", "In active practice for at least ten (10) years prior to appointment", "A resident of Metro Manila"], "correct": 3, "explanation": "There is no residency requirement. A Board member must be a natural-born Filipino, a registered optometrist in good standing, at least 35 years old, of good moral character, and in active practice for at least 10 years before appointment."}'),
  ('67f4073e-25','{"options": ["Owns an optical shop", "Is a faculty member of, or has pecuniary interest in, a school teaching optometry, OR is an officer of an optometric association (unless he relinquishes such before taking oath)", "Is over 60 years old", "Has been in practice for more than 20 years"], "correct": 1, "explanation": "A faculty member or one with pecuniary interest in an optometry school, or an officer of an optometric association, is disqualified unless he/she relinquishes the position/interest before or upon taking the oath as Board member."}'),
  ('e6a4845d-1l','{"options": ["Coterminous with the President", "Five (5) years, non-renewable", "Seven (7) years, non-renewable", "Three (3) years, renewable once"], "correct": 1, "explanation": "Board members serve a non-renewable term of five (5) years, starting on the date of appointment and until their successors are appointed."}'),
  ('432a3980-2c','{"options": ["Three (3)", "Four (4)", "All five (5)", "Two (2)"], "correct": 0, "explanation": "The attendance of at least three (3) members constitutes a quorum for the Board to officially transact business."}'),
  ('21c9a0d3-39','{"options": ["Four (4)", "Three (3)", "A unanimous vote", "Two (2)"], "correct": 1, "explanation": "The vote of three (3) members of the Board is necessary to render a decision in an administrative case."}'),
  ('4d4ed294-3s','{"options": ["Thirty (30) days", "Fifteen (15) days", "Sixty (60) days", "Ten (10) days"], "correct": 1, "explanation": "The Board''s decision in an administrative case becomes final and executory fifteen (15) days after receipt of the notice of judgment/decision, unless appealed to the Commission."}'),
  ('9844baba-3s','{"options": ["Sixty (60) days", "Ninety (90) days", "Thirty (30) days", "One hundred twenty (120) days"], "correct": 0, "explanation": "During investigation, the President may suspend the Board member for a period not more than sixty (60) days and appoint a temporary member in his place."}'),
  ('b837bc4e-1y','{"options": ["The Professional Regulation Commission (PRC)", "The Supreme Court", "The Commission on Higher Education", "The Department of Health"], "correct": 0, "explanation": "The Professional Regulation Commission (PRC) exercises general supervision over the Board of Optometry and all professional regulatory boards."}'),
  ('0f688d22-27','{"options": ["Republic Act No. 8981", "Presidential Decree No. 223 (as amended by P.D. 657)", "Republic Act No. 8050", "Public Act No. 2245"], "correct": 1, "explanation": "The PRC was created by Presidential Decree No. 223 (as amended by P.D. 657), which transferred supervision of the regulatory boards from the Bureau of Civil Service to the PRC. RA 8981 later modernized it."}'),
  ('7ec7853e-n','{"options": ["Continuing Professional Development Act of 2016", "PRC Modernization Act of 2000", "Revised Optometry Law of 1995", "FDA Act of 2009"], "correct": 1, "explanation": "RA 8981 (approved December 5, 2000) is the PRC Modernization Act of 2000, which repealed P.D. 223 and modernized the Commission."}'),
  ('25e0d000-1l','{"options": ["Five-man commission", "Single-commissioner office", "Board of seven commissioners", "Three-man commission (one Chairperson and two Commissioners)"], "correct": 3, "explanation": "RA 8981 created a three-man Commission: one full-time Chairperson and two full-time Commissioners, appointed by the President."}'),
  ('138c4e9b-24','{"options": ["Seven (7) years, without reappointment", "Three (3) years", "Five (5) years, renewable", "Coterminous with the appointing President"], "correct": 0, "explanation": "The Chairperson and Commissioners of the PRC serve a term of seven (7) years without reappointment."}'),
  ('2b38d603-2s','{"options": ["At least 40 years of age", "At least 35 years of age", "At least 50 years of age", "At least 45 years of age"], "correct": 0, "explanation": "A PRC Chairperson or Commissioner must be at least forty (40) years of age, with a valid certificate of registration and PIC (or valid certificate of competency/professional license)."}'),
  ('9cad5a6d-1n','{"options": ["At least once every two years", "Only when there are enough applicants", "At least once a year", "Twice a year without exception"], "correct": 2, "explanation": "The licensure examination is given at least once a year, in places and on dates designated by the Commission."}'),
  ('e990a4df-44','{"options": ["80% and 20%", "60% and 40%", "70% and 30%", "50% and 50%"], "correct": 2, "explanation": "The written/theoretical examinations are weighted 70% and the clinical skills assessment (performance) 30% of the General Weighted Average Rating."}'),
  ('02123e82-3k','{"options": ["10%", "15%", "20%", "5%"], "correct": 0, "explanation": "Jurisprudence, Ethics, Practice Management, and Public Health carries a 10% weight in the written (theoretical) licensure examination."}'),
  ('2c3a8f9a-2w','{"options": ["At least 75% with no subject below 60%", "At least 70% with no subject below 50%", "At least 75% with no subject rating below 50%", "At least 80% with no subject below 60%"], "correct": 2, "explanation": "To pass, the examinee must obtain a GWA of at least seventy-five percent (75%) with no subject rating below fifty percent (50%)."}'),
  ('5e9776fc-2w','{"options": ["Failed", "Passed", "Conditioned (must retake only the deficient subject/s)", "Disqualified"], "correct": 2, "explanation": "Such an examinee is CONDITIONED and must retake only the subject/s in which he/she scored below 50%."}'),
  ('be3b6782-2m','{"options": ["The practical examination only", "BOTH the theoretical and practical examinations", "The theoretical examination only", "Any single subject"], "correct": 1, "explanation": "An examinee is deemed FAILED when the GWA is below 75% on both the theoretical and practical examinations."}'),
  ('fa6d3d8b-2y','{"options": ["Of good moral character", "At least 21 years old", "In active practice for at least 10 years", "A Filipino citizen"], "correct": 2, "explanation": "Ten years of active practice is a qualification for BOARD MEMBERS, not exam applicants. An applicant must be a Filipino citizen, at least 21 years old, of good moral character, and a holder of a Doctor of Optometry degree from an accredited institution."}'),
  ('ea06077f-3l','{"options": ["Twenty (20) days", "Thirty (30) days", "Ten (10) days", "Sixty (60) days"], "correct": 0, "explanation": "The application for examination must be filed at least twenty (20) days before or prior to the first day of the examination."}'),
  ('3d4d84cd-3j','{"options": ["Obtains a waiver from the PRC Chairperson", "Submits proof of having taken a refresher course in a duly accredited institution", "Re-enrolls in the entire optometry course", "Waits five years"], "correct": 1, "explanation": "After a third failure, the applicant must submit proof of having taken a refresher course in a duly accredited institution before being allowed to take the succeeding examination."}'),
  ('d1e0af03-1p','{"options": ["Publication of results", "Joining IPAO", "Taking the oath as an optometrist and payment of the required fees, then registration in the Roster of Optometrists", "Receiving a passing letter by mail"], "correct": 2, "explanation": "A successful examinee must take the oath before the Board (or an authorized officer), pay the required fees, and be registered/enrolled in the Roster of Optometrists."}'),
  ('2cf77056-56','{"options": ["Three (3) or more years", "Two (2) or more years", "Ten (10) or more years", "Five (5) or more years"], "correct": 3, "explanation": "Failure to pay the annual registration fees continuously for five (5) or more years renders an optometrist delinquent, and he/she is dropped from the Roll of Registered Optometrists in Good Standing."}'),
  ('9e7aff85-2h','{"options": ["The patient''s PhilHealth number", "Only the optometrist''s name", "The certificate of registration number, the PTR (professional tax receipt) number, and the PIC expiry date", "Only the clinic address"], "correct": 2, "explanation": "The optometrist''s certificate of registration number, professional tax receipt (PTR) number, and the expiry date of the professional identification card must appear on prescriptions and documents he issues."}'),
  ('f2d5fdc2-2d','{"options": ["A minimum of five (5) years", "Three (3) years", "Ten (10) years", "One (1) year"], "correct": 0, "explanation": "An optometrist must keep a record of the patient''s data, findings, examination results, and services for a minimum of five (5) years after the last consultation."}'),
  ('f265e941-2k','{"options": ["Foreign optometrists on tourist visas", "Any optical shop employee", "Ophthalmic technicians and opticians", "Registered physicians with postgraduate eye training; physicians examining the eye during a physical exam; and trained public health workers doing only VA testing and visual screening"], "correct": 3, "explanation": "Allowed limited practice: physicians with postgraduate training in diagnosis/treatment of eye disease; physicians examining the eye as part of a physical exam; and public health workers (blindness-prevention program) who may conduct only visual acuity tests and visual screening."}'),
  ('db3787a4-30','{"options": ["Fit contact lenses", "Use diagnostic pharmaceutical agents", "Prescribe and dispense spectacles", "Conduct only visual acuity tests and visual screening"], "correct": 3, "explanation": "Trained public health workers may conduct only visual acuity tests and visual screening under the government''s blindness prevention program."}'),
  ('86fbe3e0-1r','{"options": ["Emphasizing free services and discounts", "True, honest, fair, dignified, and objective statements of fact", "Focused on the lowest fees", "Self-laudatory and competitive"], "correct": 1, "explanation": "An optometrist making known his services shall use only true, honest, fair, dignified, and objective information or statements of fact."}'),
  ('59ad60d9-2f','{"options": ["Stating lower fees than customary rates, or advertising free examinations, discounts, and prizes to attract patronage", "Listing office hours", "Indicating the optometrist''s degree", "Displaying the clinic name and services offered"], "correct": 0, "explanation": "Referring to fees (especially lower-than-customary), advertising free/gratuitous services, bonuses, premiums, discounts, sales, or prizes to attract patronage is unprofessional and unethical."}'),
  ('34c40d7d-2i','{"options": ["Set solely by each optometrist", "Higher than, and not to be placed on the same level as, the standards of practice in the marketplace", "Lower than commercial standards", "Equal to the standards of the marketplace"], "correct": 1, "explanation": "The standards of professional conduct for optometrists are higher than, and shall not be placed on the same level as, the standards of practice in the marketplace."}'),
  ('80d325a7-3d','{"options": ["Thirty (30) days", "Fifteen (15) days", "Sixty (60) days", "Ninety (90) days"], "correct": 0, "explanation": "The optometrist must notify the Board of the location of his office/clinic within thirty (30) days from securing the premises, and any subsequent change of location must likewise be reported."}'),
  ('985a55e6-2z','{"options": ["A slit-lamp biomicroscope (or equivalent)", "A fundus camera", "A visual field analyzer", "An OCT machine"], "correct": 0, "explanation": "Required equipment includes visual acuity charts, trial lenses/phoropter, ophthalmoscope and retinoscope, ophthalmic chair, a slit-lamp biomicroscope (or equivalent), and dispensing tools."}'),
  ('6f3aadc8-1x','{"options": ["Only with permission and under the auspices of public health officials and/or the accredited association through its local chapter, for public service", "Only in shopping malls", "No, never under any circumstance", "Yes, without any restriction"], "correct": 0, "explanation": "Mobile units may be used only with permission and under the auspices of national/local public health officials and/or the accredited and integrated association (through its local chapter) in relation to public services."}'),
  ('09f07487-2j','{"options": ["Permitted with patient consent", "Permitted if supervised", "Allowed for emergencies only", "An unlawful/prohibited act"], "correct": 3, "explanation": "The use of DPAs by a non-DPA-certified or untrained optometrist, whether or not it results in patient injury, is expressly an unlawful and prohibited act."}'),
  ('548799c4-29','{"options": ["Collecting professional fees", "Establishment or ownership of an optical clinic by foreigners, optical suppliers, or ophthalmic technicians", "Displaying the certificate of registration", "Keeping patient records for five years"], "correct": 1, "explanation": "Establishment or ownership of an optical clinic by foreigners, optical suppliers, or ophthalmic technicians is a prohibited act. Owning such a clinic is reserved to qualified optometrists."}'),
  ('1b70483a-2j','{"options": ["Committing a prohibited act and is subject to disciplinary action", "Exempt if he supervised the non-optometrist", "Not liable, since he did not personally practice illegally", "Only liable if the patient is injured"], "correct": 0, "explanation": "An optometrist who aids or abets any natural or juridical person in the unlawful practice of optometry commits a prohibited act and is subject to disciplinary action."}'),
  ('36a7f997-29','{"options": ["Conviction of a crime involving moral turpitude", "Charging the customary professional fee", "Advertising office hours", "Referring a patient to an ophthalmologist"], "correct": 0, "explanation": "Grounds include unprofessional/unethical conduct, malpractice, violations of RA 8050 or Board rules, conviction of a crime involving moral turpitude, immoral or dishonorable conduct, unauthorized practice, gross negligence/incompetence, chronic inebriety or drug habituation, and being declared mentally unsound."}'),
  ('d4ffe7c3-2j','{"options": ["Being a new graduate", "Being over 60 years old", "Owning a single optical shop", "Having been convicted by final judgment of a crime involving moral turpitude, or declared of unsound mind"], "correct": 3, "explanation": "Grounds for disqualification include failing the licensure exam, conviction by final judgment of a crime involving moral turpitude, being found guilty of immoral/dishonorable conduct, or being declared of unsound mind."}'),
  ('ae14fb99-o','{"options": ["Universal Health Care Act", "Continuing Professional Development (CPD) Act of 2016", "Revised Optometry Law", "PRC Modernization Act"], "correct": 1, "explanation": "RA 10912 is the Continuing Professional Development (CPD) Act of 2016, which made CPD mandatory for renewal of the professional license."}'),
  ('1fbc10a2-3q','{"options": ["Sixty (60) units", "One hundred twenty (120) units", "Forty-five (45) units", "Fifteen (15) units"], "correct": 3, "explanation": "The requirement was reduced to fifteen (15) CPD credit units for renewal of the PIC. (The original IRR figure of 60 units, later 45, was amended down to 15 units; Senior Citizens and PWDs need only 10 units.)"}'),
  ('3b80d125-3h','{"options": ["They are fully exempt", "Fifteen (15) units", "Ten (10) units", "Five (5) units"], "correct": 2, "explanation": "Senior Citizens and differently abled persons/PWDs are required to present ten (10) CPD credit units for renewal, versus 15 for other optometrists."}'),
  ('0ebe4c74-1l','{"options": ["Registered and licensed optometrists working overseas, and newly registered optometrists during their first renewal cycle", "Optometrists over 40 years old", "All optometrists in private practice", "Optometrists who own optical shops"], "correct": 0, "explanation": "Optometrists working overseas are not covered by the CPD requirement (as long as renewal falls within the 3-year period), and newly registered optometrists are not covered for their first renewal cycle (3 years) after obtaining their license."}'),
  ('a7aba311-1s','{"options": ["Two", "Three (one Chairperson and two members)", "Seven", "Five"], "correct": 1, "explanation": "The CPD Council is a three-person body: one Chairperson (a member of the Professional Regulatory Board) and two members (one from the AIPO/APO and one from the national organization of deans)."}'),
  ('694bd07c-2c','{"options": ["Passive membership without activity", "Online learning activities and professional work experience", "Formal learning", "Informal and self-directed learning"], "correct": 0, "explanation": "Recognized CPD program types include formal, non-formal, informal, self-directed, online learning activities, and professional work experience. Mere passive membership is not a CPD activity."}'),
  ('231b3347-1w','{"options": ["Samahan ng mga Optical Retailers", "Integrated Philippine Association of Optometrists, Inc. (IPAO)", "Philippine Optometric Association (POA)", "Optometric Association of the Philippines (OAP)"], "correct": 1, "explanation": "The Integrated Philippine Association of Optometrists, Inc. (IPAO) is the PRC-integrated, accredited national organization of optometrists. It was formerly known as the Samahan ng mga Optometrist sa Pilipinas (SOP)."}'),
  ('f084f61c-y','{"options": ["Samahan ng mga Optometrist sa Pilipinas (SOP)", "Optometric Association of the Philippines", "Philippine College of Optometrists", "Philippine Association of Optometrists"], "correct": 0, "explanation": "The IPAO was formerly the Samahan ng mga Optometrist sa Pilipinas (SOP), established in 1976. It adopted the name IPAO in 1998 upon integration."}'),
  ('144f4eb6-2c','{"options": ["Promulgate the Code of Ethics, define professional responsibilities, ensure adherence to ethics, and improve professional standards", "Control the price of eyeglasses", "Limit the number of practicing optometrists", "Increase membership dues"], "correct": 0, "explanation": "The integrated national organization promulgates the Code of Ethics, defines the professional responsibilities of members, ensures adherence to ethics, improves professional standards, and enables optometrists to discharge their public responsibility."}'),
  ('4c97f5aa-3e','{"options": ["Yes, it strictly prohibits all other associations", "No; integration does not prohibit the creation of other associations organized by optometrists themselves", "Only optical-retailer associations are allowed", "Other associations require Supreme Court approval"], "correct": 1, "explanation": "Integration into one national organization does not prohibit the creation of other associations of optometrists organized by the optometrists themselves."}'),
  ('2cf2f242-19','{"options": ["January 1-7", "March 26-31", "June 16-22", "June 1-7"], "correct": 3, "explanation": "Philippine Optometry Week is June 1-7 every year, per Presidential Proclamation No. 985 signed by President Fidel V. Ramos on March 26, 1997."}'),
  ('abac5eb9-2d','{"options": ["Dr. Federico Sarabia, Sr.", "Dr. Manuel Sabater (March 11, 1918)", "Dr. Justo Gonzales", "Dr. G. T. Herrmann"], "correct": 1, "explanation": "PRC records show that Certificate of Registration No. 1 was issued to Dr. Manuel Sabater on March 11, 1918. (The claim that Dr. Federico Sarabia, Sr. held No. 001 is common knowledge but NOT valid per PRC information.)"}'),
  ('fe665a87-3b','{"options": ["Directly to the Supreme Court", "To the PRC (through the Commissioner), and ultimately to the Office of the President", "To the Court of Appeals only", "To the Department of Health"], "correct": 1, "explanation": "Administrative-case decisions (Code of Ethics violations) by the Board are appealed to the Commission (PRC), through the Commissioner, and ultimately may reach the Office of the President. Court cases (civil/criminal) go through the Court of Appeals to the Supreme Court."}'),
  ('5bdbba71-22','{"options": ["Regional Trial Court", "Metropolitan Trial Court", "Supreme Court", "Court of Appeals"], "correct": 2, "explanation": "The Supreme Court is the highest court and the final appellate authority in the Philippine judicial hierarchy."}'),
  ('a255a27b-22','{"options": ["Subpoena duces tecum", "Subpoena ad testificandum", "Warrant of arrest", "Summons"], "correct": 0, "explanation": "A subpoena duces tecum orders a person to attend court and bring relevant documents (''duces tecum'' = bring with you). A subpoena ad testificandum orders a person to give oral testimony."}'),
  ('c6938848-1m','{"options": ["Bring documents to court", "Provide oral testimony (to testify)", "Cease practicing", "Pay a fine"], "correct": 1, "explanation": "A subpoena ad testificandum orders a person to provide oral testimony in response to questions at a deposition or trial (''ad testificandum'' = to testify)."}'),
  ('ef7137ed-15','{"options": ["They are identical", "A summons is issued only by the Board", "A summons is an order to appear (an invitation to respond); a subpoena is a court order compelling attendance once a case is filed", "A summons compels documents; a subpoena compels testimony"], "correct": 2, "explanation": "A summons is essentially an order/invitation to appear before a judge or to respond to a case; a subpoena is a court writ compelling a person to attend court (issued once a case is underway)."}'),
  ('2777a419-3x','{"options": ["Duty, Diligence, Discretion, and Discipline", "Duty, Dereliction, Direct causation, and Damages", "Damages, Deceit, Default, and Delay", "Diagnosis, Documentation, Disclosure, and Defense"], "correct": 1, "explanation": "The 4 Ds of malpractice/negligence are: Duty (a professional relationship existed), Dereliction (breach of the standard of care), Direct causation (the breach caused the harm), and Damages (actual injury resulted)."}'),
  ('02a83b30-1c','{"options": ["The actual injury suffered by the patient", "The financial loss to the practitioner", "The breach or failure to meet the accepted standard of care", "The existence of a doctor-patient relationship"], "correct": 2, "explanation": "Dereliction is the breach of duty: the practitioner failed to meet the accepted standard of care. Duty establishes the relationship, direct causation links breach to harm, and damages is the actual injury."}'),
  ('e36a78f6-42','{"options": ["Corporation", "Cooperative", "Sole proprietorship", "Partnership"], "correct": 2, "explanation": "A sole proprietorship is owned by one person who has full control and unlimited personal liability for the practice''s obligations. It is the simplest and most common form."}'),
  ('f505d72e-3d','{"options": ["Franchise", "Partnership", "Trust", "Sole proprietorship"], "correct": 1, "explanation": "A partnership is an association of two or more persons who contribute to a common fund and divide profits (and share liabilities). Compare with a corporation, which is a separate juridical entity."}'),
  ('618679a2-3t','{"options": ["The Food and Drug Administration (FDA)", "The Securities and Exchange Commission", "The Bureau of Customs", "The Department of Trade and Industry"], "correct": 0, "explanation": "RA 9711 (the FDA Act of 2009) empowers the Food and Drug Administration to require Medical Device Establishments a License to Operate (LTO). This helps limit dispensing of ophthalmic medical devices to licensed optometrists."}'),
  ('4fe42844-n','{"options": ["PRC Modernization Act", "CPD Act of 2016", "FDA Act of 2009", "Universal Health Care Act"], "correct": 2, "explanation": "RA 9711 is the Food and Drug Administration (FDA) Act of 2009, which reorganized and strengthened the former Bureau of Food and Drugs (BFAD)."}'),
  ('28e503fd-3l','{"options": ["The Technical Panel on Optometric Education (under CHED)", "The Board of Optometry", "The IPAO Board of Governors", "The CPD Council"], "correct": 0, "explanation": "The Technical Panel on Optometric Education, organized under the Commission on Higher Education (CHED) pursuant to RA 8050, sets minimum curriculum and teaching standards and evaluates optometry schools."}'),
  ('93d374b8-35','{"options": ["He passes an English proficiency test", "He has resided in the Philippines for 10 years", "His home country, by specific provision of law, admits Filipinos to practice optometry on terms of strict and absolute equality", "He is endorsed by the IPAO"], "correct": 2, "explanation": "Under foreign reciprocity, a foreigner is admitted to the board exam only if his country, by specific law, admits Filipino citizens to practice optometry without restriction or on terms of strict and absolute equality (including recognition of prerequisite degrees)."}'),
  ('37101192-24','{"options": ["A purely commercial activity", "A regular component of the primary health care system", "An optional wellness service", "A specialty of ophthalmology"], "correct": 1, "explanation": "RA 8050 declares that the State recognizes the essential role of optometry and that optometric services shall be promoted as a regular component of the primary health care system."}'),
  ('a909df3d-y','{"options": ["Prescribing oral medications", "Examining the eye with DPAs", "The act of filling, translating, or fitting of spectacles, contact lenses, visual aids, prosthetics, and low-vision aids for the aid, correction, or relief of the human eye", "Performing surgery"], "correct": 2, "explanation": "Dispensing is the act of filling, translating, or fitting spectacles/eyeglasses, contact lenses (with accessories and solutions), visual aids, prosthetics, low-vision aids, and other corrective optical devices for the aid, correction, rehabilitation, or relief of the human eye."}'),
  ('4480ba80-2t','{"options": ["Offered for at least four years", "Accredited by the IPAO only", "Recognized internationally only", "Duly accredited by the Board and the government (CHED)"], "correct": 3, "explanation": "A Doctor of Optometry is a degree from a school, college, university, or institution whose course of study has been duly accredited by the Board and the government (through CHED), after passing an optometry course."}'),
  ('0ba5b23c-2s','{"options": ["Any retail space shared with unrelated businesses", "Premises used exclusively for optometric practice, conducive to independent clinical judgment", "A mobile van as the primary clinic", "A residential kitchen"], "correct": 1, "explanation": "The practice of optometry shall be conducted only in premises used exclusively for optometric practice (a regular clinic/office) that is maintained to professional standards and conducive to the exercise of independent clinical judgment."}'),
  ('92a68c7f-2j','{"options": ["Only in government hospitals", "No, never", "Only with physicians", "Yes; an optometrist may hold office/clinic together with members of allied health professions"], "correct": 3, "explanation": "The IRR expressly allows an optometrist to hold office/clinic together with members of allied health professions, and permits multi-disciplinary management."}'),
  ('20dc5bcc-2b','{"options": ["Encouraged for cost savings", "A prohibited/unlawful act", "Allowed if the patient consents", "Permitted for imported products only"], "correct": 1, "explanation": "Prescribing or endorsing doubtful products other than those approved by the Bureau of Food and Drugs (FDA) and the Department of Trade and Industry (DTI) is an unlawful/prohibited act."}'),
  ('2b236d90-29','{"options": ["Marketing banners with fees", "Only price lists", "The Certificate of Registration and the Professional Identification Card (plus documents attesting to competence and educational qualifications)", "Personal photographs"], "correct": 2, "explanation": "The optometrist must prominently display the Certificate of Registration and PIC, and the clinic shall display only certificates, diplomas, and similar documents attesting to the competence and educational qualifications earned by the optometrist."}'),
  ('4e11d76a-3i','{"options": ["Not less than 6 years and 1 day to 12 years, or a fine, or both", "1 to 3 years only", "Not less than 6 months and 1 day to 6 years", "A fine only, with no imprisonment"], "correct": 0, "explanation": "Under RA 8981, manipulating exam results, leaking questions, or tampering with grades is punished by imprisonment of not less than six (6) years and one (1) day to not more than twelve (12) years, or a fine of P50,000 to P100,000, or both."}'),
  ('e3518346-2y','{"options": ["A one-year suspension", "A written warning", "Community service", "Removal from office and perpetual absolute disqualification from public office"], "correct": 3, "explanation": "Under RA 8981, if the offender is a PRC officer/employee or a regulatory board member, he/she shall be removed from office and suffer perpetual absolute disqualification from public office, in addition to the criminal penalties."}'),
  ('1c02ee95-4g','{"options": ["Ten (10) days", "Sixty (60) days", "Thirty (30) days", "Ninety (90) days"], "correct": 1, "explanation": "The Board shall report the ratings to the Commission within sixty (60) days after the last examination day, unless extended by the Commission. (Note: under RA 8981''s general rule, boards submit results within 10 days; the optometry IRR specifies 60 days for the report of results.)"}'),
  ('997609c6-29','{"options": ["They are interchangeable terms", "The Certificate of Registration is permanent while the PIC is renewable/expiring", "The PIC is permanent while the Certificate of Registration expires", "Both must be renewed yearly"], "correct": 1, "explanation": "The Certificate of Registration is a permanent, non-expiring proof of qualification; the PIC (professional license) is the renewable card that expires and must be renewed every 3 years."}'),
  ('dc33d70d-2p','{"options": ["RA 8050 → Optometry Law of 1917 → RA 1998", "Optometry Law of 1917 → RA 1998 (1957) → RA 8050 (1995)", "RA 8050 → RA 1998 → Optometry Law of 1917", "RA 1998 → Optometry Law of 1917 → RA 8050"], "correct": 1, "explanation": "The correct order: the Optometry Law of 1917 (first, amended 1919), then RA 1998 (1957), then RA 8050 (the Revised Optometry Law of 1995, current)."}'),
  ('400c2501-1z','{"options": ["Dr. Charlie Ho", "Dr. Vigan delos Reyes", "Dr. Manuel Sabater", "Dr. Justo Gonzales"], "correct": 1, "explanation": "Dr. Vigan delos Reyes is recognized as the Father of the SOP (Samahan ng mga Optometrist sa Pilipinas), which led the integration period and became the IPAO."}'),
  ('515ad536-2q','{"options": ["Board of Optometry", "Junta Examinadora (Board of Examiners)", "Professional Regulation Commission", "Supreme Court"], "correct": 1, "explanation": "The Junta Examinadora (Board of Examiners) administered the ''examination de gracia'' one year prior to March 11, 1917, in the early history of Philippine optometry regulation."}'),
  ('3579deac-2e','{"options": ["An owner of a foreign-controlled optical clinic", "A consultant to optical/ophthalmic manufacturing and distribution business/industry, or a staff optometrist/administrator for government, research, or health institutions", "A canvasser selling door-to-door", "An unlicensed dispenser"], "correct": 1, "explanation": "An optometrist may be engaged as a consultant to optical/ophthalmic manufacturing and distribution business/industry, or as a staff optometrist/optometric administrator for government offices, research organizations, educational institutions, insurance companies, or licensed health facilities/hospitals."}'),
  ('d504792c-36','{"options": ["Commission on Higher Education", "Board of Optometry", "Professional Regulation Commission", "IPAO"], "correct": 1, "explanation": "The Clinical Skills Assessment/Examination is the clinical competency examination developed, prepared, and scored/graded by the Board of Optometry as the clinical component of the licensure examination."}'),
  ('8143ecc2-2q','{"options": ["Physiological Optics", "Contact Lens Practice", "Jurisprudence and Ethics", "General Anatomy"], "correct": 1, "explanation": "The Clinical Skills Assessment (30%) includes Subjective Clinical Procedures, Objective Clinical Procedures, Contact Lens Practice, Binocular Vision and Low Vision Clinical Skills, and Ophthalmic Laboratory and Dispensing. Jurisprudence, Ethics, and Physiological Optics are written (theoretical) subjects."}'),
  ('79350d44-4h','{"options": ["A valid business practice", "Required for liability protection", "Allowed with a lawyer present", "A prohibited/unlawful act"], "correct": 3, "explanation": "Entering into contracts that compromise the optometrist''s professional judgment/diagnosis, or that prevent a patient from obtaining due treatment or redress for gross negligence causing injury, is an unlawful/prohibited act."}'),
  ('0f1e725f-47','{"options": ["Civil Code", "Revised Penal Code", "Code of Professional Ethics for Optometrists", "Labor Code"], "correct": 2, "explanation": "The Code of Professional Ethics for Optometrists prescribes the standards of conduct, integrity, and moral duties toward patients, the public, and fellow optometrists."}'),
  ('e2792f87-2p','{"options": ["The Professional Regulation Commission", "The Civil Service Commission", "The Department of Labor and Employment", "The Commission on Higher Education"], "correct": 0, "explanation": "The PRC administers and conducts the licensure examinations of the various regulatory boards in accordance with its rules, and admits successful examinees to the practice of the profession."}'),
  ('cd78e2ad-1x','{"options": ["It includes therapeutic agents such as antibiotics", "It is set by the DTI", "It is limited to diagnostic agents (mydriatics, cycloplegics, anesthetics, and a dye)", "It includes oral analgesics"], "correct": 2, "explanation": "The authorized agents are strictly DIAGNOSTIC: mydriatics (Phenylephrine, Tropicamide), a cycloplegic (Cyclopentolate), anesthetics (Proparacaine, Benoxinate/Oxybuprocaine), and a dye (Fluorescein). Therapeutic agents like antibiotics or anti-glaucoma drugs are not DPAs."}'),
  ('41328f60-2l','{"options": ["RA 10912", "RA 8050", "RA 9711", "RA 8981"], "correct": 0, "explanation": "RA 10912 (the CPD Act of 2016) made CPD mandatory for the renewal of PRC professional licenses."}'),
  ('8a62441f-2h','{"options": ["There is an unsolicited request because the patient, for health or occupational reasons, cannot visit the regular clinic", "The patient prefers privacy", "The optometrist advertises house calls", "It is more profitable"], "correct": 0, "explanation": "An optometrist shall not examine patients outside the regular clinic UNLESS there is an unsolicited request for patients who are not ambulant or who, for health or occupational reasons, are unable to visit the regular office/clinic."}'),
  ('2bd231e8-22','{"options": ["Licensure law governs entry into and the standards of the profession", "Civil law imposes imprisonment for professional violations", "Public opinion law is enacted by Congress", "Criminal law governs contracts between optometrists"], "correct": 0, "explanation": "Licensure law governs entry into and the standards/regulation of the profession. The regulatory framework of optometry includes licensure laws, the code of ethics, criminal law, civil law, optometric-society rules, and public opinion."}'),
  ('570b57c8-3r','{"options": ["The Asia Optometric Congress", "The Philippine Optical Retailers Association", "The Optometric Association of the Philippines", "The Integrated Philippine Association of Optometrists (IPAO)"], "correct": 3, "explanation": "The IPAO is the PRC-accredited and integrated professional organization (AIPO) that promulgates the Code of Ethics for Filipino optometrists."}'),
  ('123877af-3d','{"options": ["Metropolitan/Municipal Trial Court", "Regional Trial Court (RTC)", "Barangay (Lupong Tagapamayapa)", "Court of Appeals"], "correct": 1, "explanation": "The Regional Trial Courts (RTCs) are the principal second-level trial courts. Below them are the first-level courts (Metropolitan/Municipal Trial Courts) and barangay-level dispute resolution; above them are the Court of Appeals and the Supreme Court."}'),
  ('5647ae87-20','{"options": ["Failure to renew the PIC on time", "Conduct that is base, vile, or depraved and contrary to accepted moral standards", "A billing dispute", "A minor traffic violation"], "correct": 1, "explanation": "Moral turpitude is conduct that is base, vile, or depraved and contrary to the accepted rules of morality. Conviction of a crime involving moral turpitude is a ground for disqualification and disciplinary action."}'),
  ('5c2dd2f3-4v','{"options": ["Only civilly liable", "Committing a prohibited act", "Exempt if unaware of the suspension", "Acting lawfully"], "correct": 1, "explanation": "Accepting employment or associating with an optometrist whose certificate of registration is suspended or revoked, during the period of such suspension or revocation, is a prohibited/unlawful act."}'),
  ('8df2eebc-3f','{"options": ["Color vision defects", "Cataract surgery backlog", "Diabetic retinopathy screening only", "Uncorrected refractive error (URE)"], "correct": 3, "explanation": "The DOH Prevention of Blindness Program prioritizes uncorrected refractive error (URE) as a public health issue, with optometrists in the frontline of providing refractive services and eyeglasses."}'),
  ('46fde7f8-28','{"options": ["Signed by the DOH Secretary", "Signed only by the Board chairman", "Signed by the President of the Philippines", "Signed by the PRC Chairperson and by the chairman and all members of the Board of Optometry, bearing its seal"], "correct": 3, "explanation": "The Certificate of Registration is signed by the Chairperson of the PRC and by the chairman and all members of the Board of Optometry, and bears its seal."}'),
  ('192821d6-1g','{"options": ["Shared ownership with technicians", "Maximum sales volume", "Dependence on optical suppliers", "Autonomy of management and the exercise of independent clinical judgment"], "correct": 3, "explanation": "The clinic environment must be conducive to the exercise of independent clinical judgment and shall promote autonomy of management procedures (except in multi-disciplinary management with allied health professionals)."}'),
  ('fb433115-37','{"options": ["The IPAO Board of Governors", "The Supreme Court", "The Department of Health", "The Technical Panel on Optometry Education (under RA 8050 / CHED)"], "correct": 3, "explanation": "The Technical Panel on Optometry Education, created pursuant to RA 8050, integrates the pharmacology course into the six-year optometry curriculum, enabling qualified new graduates to use DPAs."}'),
  ('3b00f7b4-2z','{"options": ["RA 8050 is the IRR of the Board Resolution", "The Board Resolution repealed RA 8050", "The Board Resolution is the Implementing Rules and Regulations (IRR) that operationalize RA 8050", "They are unrelated laws"], "correct": 2, "explanation": "Board of Optometry Resolution No. 01, Series of 2008 is the IRR of RA 8050 — the detailed rules and regulations implementing the Revised Optometry Law of 1995."}'),
  ('eb635f08-2i','{"options": ["Sworn statements attesting to good conduct and non-practice during revocation, plus an NBI clearance, and a Board resolution approved by the Commission", "Approval by the Supreme Court", "A new licensure examination", "Only payment of a fee"], "correct": 0, "explanation": "Reinstatement requires sworn statements (from a recognized practitioner and an incumbent officer of the accredited association) attesting to good conduct and that the applicant never practiced during revocation, an NBI clearance, and a Board resolution subject to Commission approval."}'),
  ('41afaf64-1j','{"options": ["Vulgar advertising is acceptable if effective", "Self-laudatory advertising claiming superiority of methods or exclusivity is unethical", "Optometrists may claim superiority over other practitioners", "Advertising the lowest fees is encouraged"], "correct": 1, "explanation": "Self-laudatory advertising regarding performance, exclusivity, or superiority of methods and instrumentation is unethical, as are deceptive, undignified, immodest, or vulgar advertisements and fee-based inducements."}'),
  ('a5f2c4d3-3s','{"options": ["Canvassing", "Delegation", "Confidentiality (privileged communication)", "Advertising"], "correct": 2, "explanation": "Maintaining confidentiality of patient records and information is a core ethical duty of the optometrist toward the patient, reflecting the privileged nature of the professional relationship."}'),
  ('f5323470-4j','{"options": ["RA 8050", "The Labor Code", "RA 10912", "RA 8981 (PRC Modernization Act)"], "correct": 3, "explanation": "RA 8981 provides that all subjects for licensure examinations shall be taught by persons who hold valid certificates of registration and valid professional licenses of the profession and who comply with CHED requirements."}'),
  ('fb4e59ea-3f','{"options": ["Only Centro Escolar University offers optometry", "No new schools have been added since 1951", "Only medical schools may offer optometry", "Programs such as Emilio Aguinaldo College, National University, and CEU-Malolos are recent additions"], "correct": 3, "explanation": "Recent additions to optometry education include Emilio Aguinaldo College, Lyceum of the Philippines, National University, and CEU-Malolos, alongside long-standing schools like Centro Escolar University and Manila Central University."}'),
  ('38372ed0-1i','{"options": ["Appoint the PRC Commissioners", "Promulgate rules for the practice of optometry (subject to PRC approval), enforce them, and prepare/rate the licensure examinations", "Try criminal cases in court", "Enact national laws"], "correct": 1, "explanation": "The Board promulgates rules and regulations for optometric practice (subject to PRC approval and consistent with RA 8050), administers and enforces them, and determines/prepares/checks/rates the licensure examinations."}'),
  ('667535b6-2l','{"options": ["Undercutting their fees to win patients", "Refraining from maligning colleagues and avoiding unfair competition", "Advertising superiority over them", "Soliciting their patients through canvassing"], "correct": 1, "explanation": "Ethical duty toward colleagues includes refraining from maligning or disparaging fellow optometrists, avoiding unfair competition and solicitation of their patients, and upholding the dignity of the profession."}'),
  ('32f2f781-2g','{"options": ["Allied Interdisciplinary Practice of Optometry", "Asian Institute of Professional Optometry", "Association of Independent Practicing Optometrists", "Accredited and Integrated Professional Organization"], "correct": 3, "explanation": "AIPO stands for the Accredited and Integrated Professional Organization — the PRC-recognized national organization (IPAO for optometry) that promulgates the Code of Ethics and represents the profession."}'),
  ('6ab1ebe2-3b','{"options": ["Unprofessional conduct", "Unauthorized practice of optometry", "Malpractice", "Unethical conduct"], "correct": 1, "explanation": "Malpractice and unprofessional/unethical conduct are grounds for disciplinary action against a REGISTERED optometrist. ''Unauthorized practice of optometry'' is a criminal act by non-licensees (or acting beyond one''s authority), prosecuted in the regular courts, not a ground for suspending an existing certificate."}'),
  ('40ae1c45-1u','{"options": ["June 1, 1992", "August 1, 1995", "June 7, 1995", "June 1, 1998"], "correct": 2, "explanation": "RA 8050 was signed on June 7, 1995 by President Fidel V. Ramos."}'),
  ('341b96f0-1i','{"options": ["August 1-7", "May 1-7", "June 1-7", "July 1-7"], "correct": 2, "explanation": "Philippine Optometry Week is June 1-7 (Proclamation No. 985, signed by President Fidel V. Ramos on March 26, 1997)."}'),
  ('caf54ee3-1k','{"options": ["Fidel V. Ramos", "Joseph Ejercito Estrada", "Benigno Simeon Aquino III", "Gloria Macapagal Arroyo"], "correct": 0, "explanation": "RA 8050 (June 7, 1995) was signed by President Fidel V. Ramos. (RA 8981, the PRC Modernization Act, was later signed by Estrada in 2000.)"}'),
  ('4c6ab764-3c','{"options": ["Integrated Philippine Association of Optometrists, Inc.", "Philippine Academy of Optometry", "Philippine College of Optometrists", "Philippine Council of Optometry"], "correct": 0, "explanation": "The Integrated Philippine Association of Optometrists, Inc. (IPAO), formerly the Samahan ng mga Optometrist sa Pilipinas (SOP, established 1976), is the PRC-accredited integrated national organization."}'),
  ('bd1faf85-20','{"options": ["Eminent domain", "Executive power", "Police power", "Taxation"], "correct": 2, "explanation": "Police power is the inherent power of the State to enact reasonable laws for public welfare, and is the basis for regulating professions."}'),
  ('d2fff1bf-1f','{"options": ["Right", "Obligation", "Privilege", "Duty"], "correct": 2, "explanation": "The practice of a profession is a privilege granted by the State (through licensure), not a natural right, and may be regulated or withdrawn."}'),
  ('93695aa2-1t','{"options": ["Professional license", "Certificate of registration", "Professional identification card", "None of the above"], "correct": 2, "explanation": "The Professional Identification Card (PIC) is the renewable card that expires every three years; the certificate of registration is permanent."}'),
  ('7a910869-2w','{"options": ["A delinquent professional", "Dropped from the roster of optometrists in good standing", "All of the above", "None of the above"], "correct": 2, "explanation": "After five or more consecutive years of unpaid annual registration fees, the optometrist is both considered delinquent AND dropped from the Roll of Registered Optometrists in Good Standing."}'),
  ('2d923289-2r','{"options": ["RA No. 1998", "RA No. 9711", "RA No. 8050", "RA No. 8981"], "correct": 3, "explanation": "RA 8981 (PRC Modernization Act of 2000) removed the mandatory continuing-education requirement for renewal; CPD was later made mandatory again by RA 10912 (2016)."}'),
  ('64596d29-2p','{"options": ["Licensed by the BFAD", "Registered with the FDA", "Authorized for sale by FDA-DOH", "Certified by the FDA"], "correct": 1, "explanation": "Medical devices must be registered with the FDA (Certificate of Product Registration); the establishment handling them needs a License to Operate."}'),
  ('b2db929c-2d','{"options": ["License to fit", "Disclosure of authority to practice", "License to practice", "License to operate"], "correct": 3, "explanation": "Contact lenses are regulated medical devices; the clinic/establishment needs an FDA License to Operate (LTO) under RA 9711."}'),
  ('291d1d30-1p','{"options": ["Use of pharmaceutical agents other than those authorized", "Aiding and abetting the unlawful practice of optometry", "Advertisement in media outlets implying superiority", "Engaging in unauthorized practice of optometry as defined in Section 5, RA 8050"], "correct": 3, "explanation": "A licensed optometrist performing optometric acts is authorized, so ''unauthorized practice'' (a crime aimed at non-licensees) is not a prohibition directed at a licensed optometrist. The other three are expressly prohibited acts."}'),
  ('c8065cf7-2m','{"options": ["Slit-lamp", "Dispensing tools", "Tonometer", "Ophthalmoscope"], "correct": 2, "explanation": "The minimum required equipment is VA charts, trial lenses/phoropter, ophthalmoscope and retinoscope, ophthalmic chair, slit-lamp biomicroscope, and dispensing tools. A tonometer is not on the minimum required list."}'),
  ('76e5a54e-2l','{"options": ["EENT specialists", "Physicians in the course of physical examination of patients", "Foreigners under the principle of reciprocity", "None of the above"], "correct": 2, "explanation": "Exempted are physicians with postgraduate eye training (e.g., EENT specialists) and physicians examining the eye during a physical exam. Reciprocity only lets a qualified foreigner be admitted to the board exam; it is not an exemption to practice without a license."}'),
  ('2dbe402c-2u','{"options": ["RA No. 7160", "PD No. 223", "RA No. 9711", "RA No. 8981"], "correct": 3, "explanation": "RA 8981 (PRC Modernization Act of 2000) prescribes the powers and functions of the PRC and the professional regulatory boards. (PD 223 originally created the PRC.)"}'),
  ('7ded6ec0-2t','{"options": ["A corporation", "A member of the Board of Optometry", "A non-optometrist", "An optometrist"], "correct": 1, "explanation": "The PRC may investigate on its own initiative (motu proprio) an erring member of the Board of Optometry."}'),
  ('448e9007-23','{"options": ["Prohibited by the rules and regulations of RA 8050 only", "Prohibited by the Local Government Code", "Not prohibited by any law or rules", "Prohibited by the optometry law only"], "correct": 0, "explanation": "Self-promotional advertising is prohibited by the IRR (rules and regulations) of RA 8050, which details unethical advertising; the statute itself does not enumerate it."}'),
  ('e966b3c2-30','{"options": ["Not prohibited", "Prohibited by the rules and regulations of RA 8050 only", "Prohibited by the optometry law only", "Prohibited by the FDA Act of 2009 only"], "correct": 1, "explanation": "This is prohibited by the IRR of RA 8050 (Sec. 45), which bars prescribing or endorsing doubtful products not approved by the FDA (BFAD) and DTI."}'),
  ('0c8cfd99-34','{"options": ["Imprisonment and/or fine at the discretion of the court", "Reprimand, suspension, or revocation of his/her professional license", "Both a and b", "None of the above"], "correct": 2, "explanation": "It is a prohibited act carrying both a possible criminal penalty (Sec. 33) and administrative sanctions (reprimand, suspension, or revocation)."}'),
  ('52cf15f4-14','{"options": ["Integrated national organization of optometrists", "Board of Optometry", "Professional Regulation Commission", "All of the above"], "correct": 0, "explanation": "Under RA 8050 (Sec. 40), the integrated national organization of optometrists promulgates the Code of Ethics (adopted by the Board upon PRC approval)."}'),
  ('0ce5b1e0-1x','{"options": ["Integrated national organization of optometrists", "Board of Optometry", "Professional Regulation Commission", "All of the above"], "correct": 1, "explanation": "The Board of Optometry promulgates the rules and regulations, subject to approval by the Commission."}'),
  ('342c0415-1a','{"options": ["Sections 3 & 4 of the Optometry Law", "Sections 3, 4 & 5 of the Optometry Law", "Pertinent provisions of both the law and the rules and regulations", "All of the above"], "correct": 2, "explanation": "The scope is set out in RA 8050 and elaborated in its IRR — the pertinent provisions of both the law and the rules and regulations."}'),
  ('95cabecb-2z','{"options": ["Oxybuprocaine HCl", "Cyclopentolate HCl", "Benoxinate HCl", "a & b", "b & c"], "correct": 4, "explanation": "RA 8050''s original list already included Oxybuprocaine 0.4%. The 2008 IRR added Cyclopentolate HCl 1.0% and restated the anesthetic as Benoxinate 0.4% (Benoxinate = Oxybuprocaine), so the additions are read as b & c."}'),
  ('d9e19407-2f','{"options": ["A faculty member/lecturer of a school teaching optometry", "An owner or stockholder of a school teaching optometry", "An officer of an optometric association", "None of the above"], "correct": 3, "explanation": "Each listed disqualification is curable: a faculty member or one with pecuniary interest may relinquish it, and an association officer may resign, before taking the oath. None is an absolute, uncurable bar."}'),
  ('6b39c5d7-3k','{"options": ["Allowed by exemption under Section 5, RA 8050", "Unprofessional", "Illegal", "Unethical"], "correct": 2, "explanation": "Public health workers in the blindness-prevention program may perform ONLY visual acuity tests and visual screening. Dispensing optical devices is beyond that exemption and constitutes illegal (unauthorized) practice."}'),
  ('9ac92c81-3h','{"options": ["Taking his oath", "Certification from the Commission to use authorized DPAs", "Issuance of the certificate of registration and professional license", "Payment of the annual registration fee"], "correct": 1, "explanation": "Six-year-course graduates are authorized to use DPAs without a separate certification. Taking the oath, paying fees, and issuance of the certificate/PIC are what is required to begin practice."}'),
  ('85b40115-2p','{"options": ["Professional identification card", "Diploma from the optometry school", "CPE credit units", "Certificate of registration"], "correct": 3, "explanation": "The certificate of registration is the permanent proof that the registrant is qualified to practice; the PIC is proof of good standing/authority to practice at a given time."}'),
  ('7413b0e5-2k','{"options": ["Carry-over capacity", "Hold-over capacity", "Re-appointment by the President", "Term extension by the President"], "correct": 1, "explanation": "A Board member holds office until a successor is appointed and qualifies — a hold-over capacity. The term itself is non-renewable."}'),
  ('092a9450-2s','{"options": ["Majority vote of the Commission", "Secretary of Labor", "Chairperson of the PRC", "President of the Philippines"], "correct": 3, "explanation": "The power to suspend or remove a Board member (after due process) rests with the President of the Philippines."}'),
  ('c972e7ba-2y','{"options": ["Unethical conduct", "Unprofessional conduct", "Criminal negligence", "Immorality"], "correct": 2, "explanation": "Grounds are neglect of duty, incompetence, malpractice, and unprofessional/unethical/immoral or dishonorable conduct. ''Criminal negligence'' is not among the enumerated grounds."}'),
  ('74d8a1f5-1x','{"options": ["Policies and standards on optometry education", "Competency standards for optometry", "Table of specifications", "None of the above"], "correct": 2, "explanation": "The Table of Specifications (syllabi/scope prepared by the Board) is the basis for the coverage of the licensure examination."}'),
  ('418487ea-35','{"options": ["Failure to take his/her professional oath", "Failure to pay the registration fee", "Having been found guilty by the courts of immoral or dishonorable conduct", "None of the above"], "correct": 3, "explanation": "All three listed circumstances bar admission to practice, so ''none of the above'' is the exception (there is no additional exception)."}'),
  ('bed2e7c0-46','{"options": ["A special permit", "Foreign reciprocity", "PD No. 541", "PD No. 223"], "correct": 2, "explanation": "PD 541 allows former Filipino professionals (who lost their citizenship) to practice their professions in the Philippines."}'),
  ('757f7413-2k','{"options": ["Violation of his oath", "Unethical conduct", "Illegal conduct", "Malpractice"], "correct": 1, "explanation": "Breaching patient confidentiality is unethical conduct — a violation of the duty of confidentiality and privileged communication."}'),
  ('09860d4a-1s','{"options": ["Law-making power", "Determinative power", "Adjudicatory power", "Rule-making power"], "correct": 0, "explanation": "Administrative agencies exercise rule-making (quasi-legislative), adjudicatory (quasi-judicial), and determinative/investigative powers. Law-making belongs to the legislature."}'),
  ('5283fca4-1z','{"options": ["Mandatory", "Discretionary", "Optional", "All of the above"], "correct": 0, "explanation": "Renewal of the PIC is mandatory; an optometrist cannot lawfully practice with an expired card."}'),
  ('1d05264e-2t','{"options": ["Original certificate of registration/professional license and PRC ID", "Duplicate certificate of registration/professional license and PRC ID", "Photocopy of the certificate of registration/professional license and PRC ID", "None of the above"], "correct": 2, "explanation": "A photocopy (ideally a scanned/certified copy) is displayed so the originals are kept safe, while still disclosing authority to practice."}'),
  ('4eae9606-2q','{"options": ["Endorsed by church organizations", "With the permission of IPAO or its local chapter", "Because the patient is unable to visit the regular clinic", "None of the above"], "correct": 0, "explanation": "Outside-clinic exams are allowed for non-ambulant patients (upon unsolicited request) or under public-health/IPAO auspices. A church endorsement is not, by itself, a valid basis."}'),
  ('d84d8fd0-2q','{"options": ["Declaration by a court of being mentally unsound", "Dishonorable conduct", "Immoral conduct", "Being guilty of a crime involving moral turpitude"], "correct": 3, "explanation": "Estafa is a crime involving moral turpitude; conviction by final judgment is a ground for disciplinary action."}'),
  ('4563fb69-2h','{"options": ["When the decision becomes final and executory", "From the moment the license is surrendered to the PRC", "When the optometrist does not appeal", "Upon the lapse of the period to file a motion for reconsideration"], "correct": 0, "explanation": "The suspension takes effect when the decision becomes final and executory."}'),
  ('48672655-29','{"options": ["July 17", "July 16", "June 7", "June 30"], "correct": 1, "explanation": "Board of Optometry Resolution No. 01, Series of 2008 is dated July 16, 2008 (its effectivity clause provides for 30 days after publication)."}'),
  ('b0b00361-18','{"options": ["Non-renewable term of 5 years", "Non-renewable term of 6 years", "Non-renewable term of 8 years", "Non-renewable term of 7 years"], "correct": 3, "explanation": "Under RA 8981, the PRC Chairperson and Commissioners serve a non-renewable term of seven (7) years."}'),
  ('a961d1fd-2l','{"options": ["EO No. 496", "RA No. 8050", "PD No. 223", "RA No. 8981"], "correct": 0, "explanation": "Executive Order No. 496 (s. 1991) prescribes the nomination procedure for members of the professional regulatory boards, as referenced by RA 8981."}'),
  ('2e726413-2u','{"options": ["30 days from receipt", "15 days from receipt", "10 days from receipt", "5 days from receipt"], "correct": 1, "explanation": "A motion for reconsideration is filed within 15 days from receipt of the decision; otherwise the decision becomes final and executory."}'),
  ('b6b97945-1d','{"options": ["RA No. 3720", "RA No. 8981", "RA No. 5720", "RA No. 9711"], "correct": 0, "explanation": "RA 9711 amended RA 3720, the original Food, Drug, and Cosmetic Act, and reorganized the former BFAD into the FDA."}'),
  ('045fc72c-1f','{"options": ["Medical device", "Health-related device", "Cosmetic device", "Radiation device"], "correct": 0, "explanation": "All contact lenses, including plano/cosmetic colored lenses, are regulated as medical devices under the FDA."}'),
  ('9f6685a2-1q','{"options": ["PhilHealth", "Home Development Mutual Fund (Pag-IBIG)", "SSS", "Provident fund"], "correct": 3, "explanation": "The mandatory government remittances are SSS, PhilHealth, and Pag-IBIG (which is itself the Home Development Mutual Fund / provident fund). ''Provident fund'' listed separately is redundant."}'),
  ('d930d99b-1j','{"options": ["5 years", "Never", "3 years", "Birth date of the optometrist"], "correct": 1, "explanation": "The certificate of registration is permanent and is never renewed; only the professional identification card is renewed (every 3 years, on the birth month)."}'),
  ('2b0cd1d0-2z','{"options": ["NBI-DOJ", "Board of Optometry-PRC", "IPAO", "Regular courts"], "correct": 3, "explanation": "Unauthorized practice by a non-licensee is a criminal matter tried in the regular courts. The Board-PRC has administrative jurisdiction over registered optometrists."}'),
  ('8ffda010-1e','{"options": ["P380", "P400", "P420", "None of the above"], "correct": 3, "explanation": "None of the above — the NCR daily minimum wage has since risen well above these figures (over P600). Always check the latest NCR Wage Order."}'),
  ('f4751f16-23','{"options": ["Subpoena duces tecum", "Interlocutory order", "Subpoena ad testificandum", "Writ of execution"], "correct": 2, "explanation": "A subpoena ad testificandum commands a person to appear and give oral testimony. A subpoena duces tecum commands a person to appear and bring documents."}'),
  ('c467c34a-29','{"options": ["Board of directors", "Executive committee", "Managing officer responsible for its commission", "President and CEO of the corporation"], "correct": 2, "explanation": "Liability attaches to the responsible officer — the managing officer/head who is responsible for the commission of the offense."}'),
  ('780c9fac-c','{"options": ["General law", "Criminal statute", "Special law", "Codification of all optometry statutes"], "correct": 2, "explanation": "RA 8050 is a special law — it regulates a specific profession, as opposed to a general law of universal application."}'),
  ('540bd11e-u','{"options": ["Optometrists only", "Professionals only", "Anybody", "The public at large only"], "correct": 2, "explanation": "As a special law that also penalizes unauthorized practice by non-licensees, RA 8050 is enforceable against anybody, not just optometrists."}'),
  ('4f8952ec-v','{"options": ["Criminal prosecution", "Civil cases", "Administrative sanctions", "All of the above"], "correct": 3, "explanation": "A single act of malpractice can give rise to criminal, civil, and administrative liability simultaneously."}'),
  ('7fadb4cb-11','{"options": ["An annual regulatory fee paid to the national government as tax", "An annual regulatory fee paid to the PRC as a registration fee", "An annual regulatory fee paid to the local government as tax", "None of the above"], "correct": 2, "explanation": "The PTR is a professional tax paid annually to the local government (city/municipality) where the professional practices."}'),
  ('22172afb-1w','{"options": ["Percentage tax of 2%", "Percentage tax of 5%", "Percentage tax of 12%", "None of the above"], "correct": 3, "explanation": "None of the above — the percentage (non-VAT) tax under Sec. 116 of the Tax Code is 3% (temporarily reduced to 1% during the CREATE-law period), not 2%, 5%, or 12%."}'),
  ('b5bef57f-2m','{"options": ["Regular courts", "NBI-DOJ", "IPAO", "Board of Optometry-PRC"], "correct": 3, "explanation": "The Board of Optometry-PRC has administrative jurisdiction over registered optometrists who violate the law or the rules and regulations (contrast: non-licensees go to the regular courts)."}'),
  ('c5d33365-29','{"options": ["Service incentive leave", "Vacation leave", "Sick leave", "Paternity leave"], "correct": 0, "explanation": "The Labor Code mandates a 5-day Service Incentive Leave. Vacation and sick leave are not statutory (they are company-granted); paternity leave is under a separate law (RA 8187)."}'),
  ('78b1698d-35','{"options": ["Regular employee", "Contractual employee", "Seasonal employee", "Casual employee"], "correct": 0, "explanation": "Regularity of employment depends on the nature of the work, not the number of hours; a part-timer performing work necessary or desirable to the business can be a regular employee."}'),
  ('7d8eb777-2h','{"options": ["Choose his/her patient", "Limit his/her practice", "Perform certain services only", "All of the above"], "correct": 1, "explanation": "Choosing to specialize is an exercise of the optometrist''s right to limit his/her practice to a particular field or set of services."}'),
  ('1e23c0f6-3x','{"options": ["Contingent fee", "Salary", "Retainer fee", "Dichotomous fee"], "correct": 2, "explanation": "A retainer fee is a fixed fee for a professional''s availability over a period of time, without an employer-employee relationship."}'),
  ('33729c7a-2g','{"options": ["Negligence", "Malpractice", "Ignorance", "Incompetence"], "correct": 3, "explanation": "Incompetence is the lack of ability, fitness, or adequate expertise to perform a required duty or specific act."}'),
  ('85c2a9f9-27','{"options": ["Simple negligence", "Gross ignorance", "Reckless imprudence", "Gross negligence"], "correct": 3, "explanation": "Gross negligence is the want of even slight care — an entire disregard of and indifference to the safety and welfare of others."}'),
  ('99636b97-2m','{"options": ["Malpractice", "Incompetence", "Ignorance", "Negligence"], "correct": 0, "explanation": "Malpractice is professional negligence — the failure to exercise the reasonable degree of skill and care expected of the practitioner in treating the patient."}'),
  ('684a1078-2t','{"options": ["Doctrine of proximate cause", "Doctrine of last clear chance", "Doctrine of common fault", "Doctrine of vicarious liability"], "correct": 3, "explanation": "Vicarious liability (respondeat superior) holds a non-negligent person (e.g., an employer) responsible for the negligence of another (e.g., an employee)."}'),
  ('fdd30c86-55','{"options": ["Doctrine of vicarious liability", "Borrowed-servant doctrine", "Doctrine of contributory negligence", "Captain-of-the-ship doctrine"], "correct": 2, "explanation": "Under contributory negligence (Art. 2179, Civil Code), the plaintiff may still recover, but the court shall mitigate the damages because the plaintiff''s own negligence contributed to the injury."}'),
  ('59b5cdec-2b','{"options": ["RA No. 7160", "RA No. 8981", "RA No. 8424", "RA No. 7394"], "correct": 3, "explanation": "The Price Tag requirement is found in RA 7394, the Consumer Act of the Philippines."}'),
  ('79b39004-2o','{"options": ["Disclosure of authority to practice", "Right to confidential information", "Right to privacy", "Right to disclosure of information"], "correct": 3, "explanation": "The right to disclosure of information is the patient''s right to be told all pertinent facts about his/her condition (the basis of informed consent)."}'),
  ('d5149dcf-3c','{"options": ["Right to information", "Right to privacy", "Right to confidential information", "Privileged communication"], "correct": 3, "explanation": "Privileged communication protects the confidential subject matter of the practitioner-patient relationship from being disclosed as testimony in court."}'),
  ('99e24fc5-39','{"options": ["Damages", "Fine", "Claims", "Awards"], "correct": 0, "explanation": "Damages are the pecuniary compensation recoverable for a breach of duty or a violation of a right recognized by law. A fine, by contrast, is paid to the State as a penalty."}'),
  ('90a446be-2e','{"options": ["Liquidated damages", "Actual damages", "Moral damages", "Temperate damages"], "correct": 1, "explanation": "Actual (compensatory) damages compensate only for the pecuniary loss actually suffered and duly proven."}'),
  ('0482fc99-3i','{"options": ["Actual damages", "Moral damages", "Temperate damages", "Liquidated damages"], "correct": 1, "explanation": "Moral damages compensate for physical suffering, mental anguish, fright, serious anxiety, besmirched reputation, wounded feelings, moral shock, and social humiliation."}'),
  ('35268816-3i','{"options": ["March 15", "January 15", "April 15", "February 15"], "correct": 2, "explanation": "Annual income tax returns are due on or before April 15 of the following year (calendar-year taxpayers)."}'),
  ('da74885a-18','{"options": ["Profit and loss statement", "Balance sheet", "Cash flow statement", "Statement of account"], "correct": 0, "explanation": "The income statement is also called the profit and loss (P&L) statement; it reports revenues and expenses over a period."}'),
  ('fb99e106-39','{"options": ["Public health", "Occupational health and safety", "Sanitation", "Hygiene"], "correct": 0, "explanation": "This is the classic Winslow definition of public health — preventing disease, prolonging life, and promoting health through organized community effort."}'),
  ('3de6d7fe-25','{"options": ["Glaucoma", "Trauma", "Vitamin A deficiency", "Cataract"], "correct": 3, "explanation": "Cataract is the leading cause of blindness worldwide; it is treatable/reversible, which is why blindness-prevention programs prioritize it."}'),
  ('5e0ff7fc-p','{"options": ["A quasi-contract", "Criminal in nature", "Independent of contract", "Based on contract"], "correct": 2, "explanation": "A quasi-delict (culpa aquiliana, Art. 2176) arises from fault or negligence and is independent of any pre-existing contractual relation."}'),
  ('6a69b358-24','{"options": ["Resolution No. 06-342(A), series of 2006", "Resolution No. 03, series of 1997", "Resolution No. 01, series of 2008", "Resolution No. 02-137, series of 2004"], "correct": 0, "explanation": "PRC Resolution No. 06-342(A), series of 2006, provides the rules of procedure in administrative investigations."}'),
  ('c7673de3-24','{"options": ["Toxicology", "Epidemiology", "Health", "Hygiene"], "correct": 1, "explanation": "Epidemiology studies the distribution, origin, and spread (determinants) of disease in populations."}'),
  ('3ca0626d-2j','{"options": ["Credit standing is unreliable", "Professional judgment may be influenced by business decisions", "Operations wind up upon dissolution", "Financial management is not transparent"], "correct": 1, "explanation": "A key concern with corporate/commercial practice is that professional (clinical) judgment may be influenced or compromised by business/profit decisions."}'),
  ('07a014c1-3v','{"options": ["45 days", "15 days", "60 days", "30 days"], "correct": 2, "explanation": "During investigation, the President may suspend the Board member for a period not exceeding sixty (60) days and appoint a temporary member."}'),
  ('21c16d5a-1w','{"options": ["Legislative power", "Subordinate legislation", "Police power", "Delegated legislative power"], "correct": 3, "explanation": "The Board''s authority to issue rules comes from delegated legislative power (the legislature delegates rule-making to the administrative body). The rules themselves are the resulting ''subordinate legislation.''"}'),
  ('922de82c-19','{"options": ["The provisions of the rules and regulations of RA 8050", "Guidelines set by the Chairperson of the Board", "Guidelines set by the Commission", "The provisions of the optometry law"], "correct": 3, "explanation": "Administrative rules cannot exceed, expand, or contravene the enabling statute; the optometry law itself is the limit on the Board''s rule-making power."}'),
  ('6a5ef483-26','{"options": ["Succession", "Chairperson of the PRC", "Operation of law", "President of the Philippines"], "correct": 3, "explanation": "The President of the Philippines appoints the members and the Chairperson of the Board of Optometry (upon PRC recommendation)."}'),
  ('1fe1377f-2g','{"options": ["6 months and 1 day to 6 years", "1 to 10 years", "1 to 8 years", "6 years and 1 day to 12 years"], "correct": 2, "explanation": "RA 8050 (Sec. 33) imposes imprisonment of 1 to 8 years, or a fine of P10,000 to P40,000, or both, at the court''s discretion. Do not confuse this with the RA 8981 exam-tampering penalty of 6 years and 1 day to 12 years."}'),
  ('a76836c5-1n','{"options": ["Rough endoplasmic reticulum", "Golgi complex", "Mitochondria", "Lysosome"], "correct": 2, "explanation": "Mitochondria generate ATP (the powerhouse). The Golgi handles carbohydrate metabolism, rough ER handles protein synthesis, and lysosomes hold digestive enzymes."}'),
  ('b159e174-1h','{"options": ["Smooth ER", "Golgi complex", "Lysosome", "Rough endoplasmic reticulum (via ribosomes)"], "correct": 3, "explanation": "The rough ER, studded with ribosomes, is the main site of protein synthesis. The smooth ER handles lipid metabolism."}'),
  ('bc37f947-15','{"options": ["Catalase only", "Amylase and lipase", "Lysozyme and hydrolase", "Pepsin and trypsin"], "correct": 2, "explanation": "Lysosomes contain digestive enzymes such as lysozyme and hydrolase, used for intracellular digestion."}'),
  ('4223cf8a-1i','{"options": ["Amitosis", "Mitosis", "Binary fission", "Meiosis"], "correct": 3, "explanation": "Meiosis produces sex cells (gametes), halving the chromosome number. Mitosis produces somatic cells."}'),
  ('cecc3062-2f','{"options": ["Epithelial", "Muscular", "Connective", "Nervous"], "correct": 0, "explanation": "Epithelial tissue covers surfaces and lines hollow organs/cavities. Connective tissue supports; muscular contracts; nervous conducts impulses."}'),
  ('3ed0971f-2a','{"options": ["Transverse", "Median (mid-sagittal)", "Sagittal", "Coronal"], "correct": 1, "explanation": "The median (mid-sagittal) plane divides the body accurately into equal left and right halves. A sagittal plane divides it unequally."}'),
  ('af59ca27-1b','{"options": ["Anterior (ventral) and posterior (dorsal)", "Superior and inferior", "Proximal and distal", "Left and right"], "correct": 0, "explanation": "The coronal/frontal plane divides the body into anterior (ventral) and posterior (dorsal) parts. The transverse plane divides superior from inferior."}'),
  ('92196d13-1j','{"options": ["Superficial", "Distal", "Proximal", "Caudal"], "correct": 2, "explanation": "Proximal means nearer the point of origin/attachment; distal means farther from it."}'),
  ('d12ebce7-1d','{"options": ["Abdominopelvic cavity", "Dorsal cavity", "Thoracic cavity", "Ventral cavity"], "correct": 1, "explanation": "The dorsal (posterior) cavity comprises the cranial cavity (brain) and spinal cavity (spinal cord). The ventral cavity holds the thoracic and abdominopelvic cavities."}'),
  ('0ab1acc7-1p','{"options": ["Left upper quadrant", "Right lower quadrant", "Right upper quadrant", "Left lower quadrant"], "correct": 1, "explanation": "The vermiform appendix lies in the right lower quadrant (RLQ). The liver/gallbladder are RUQ; the spleen is LUQ."}'),
  ('697303ce-28','{"options": ["Trachea and esophagus", "Thymus", "Spleen", "Heart"], "correct": 2, "explanation": "The mediastinum contains the heart, trachea, bronchi, esophagus, and thymus. The spleen is an abdominal (LUQ) organ."}'),
  ('91f6a74a-10','{"options": ["Lung", "Brain", "Liver", "Skin"], "correct": 3, "explanation": "The skin is the largest organ of the body. The liver is the largest gland/internal organ."}'),
  ('59a2a482-1v','{"options": ["Stratum lucidum", "Stratum spinosum", "Stratum corneum", "Stratum granulosum"], "correct": 0, "explanation": "The stratum lucidum (eleidin layer) is found only in thick skin (palms and soles) and is absent in thin skin."}'),
  ('e7e3301e-1y','{"options": ["Stratum granulosum", "Stratum corneum", "Stratum germinativum (basale)", "Stratum lucidum"], "correct": 2, "explanation": "Melanin is contained in the stratum germinativum (basale), the deepest, mitotically active layer."}'),
  ('40e5a155-1s','{"options": ["Lucidum, corneum, granulosum, spinosum, germinativum", "Germinativum, spinosum, granulosum, lucidum, corneum", "Corneum, lucidum, granulosum, spinosum, germinativum", "Corneum, granulosum, lucidum, spinosum, germinativum"], "correct": 2, "explanation": "Outer to inner: Corneum, Lucidum, Granulosum, Spinosum, Germinativum (''Come Let''s Get Some Guys'')."}'),
  ('12e8a9cf-21','{"options": ["Intercellular bridges (cytodesmata)", "Dead flat cells", "Eleidin content", "Keratohyalin granules"], "correct": 0, "explanation": "The stratum spinosum has polyhedral cells joined by intercellular bridges (cytodesmata), giving a prickly appearance; it is mitotically active."}'),
  ('a344ff11-1c','{"options": ["305", "270", "206", "365"], "correct": 2, "explanation": "The adult skeleton has 206 bones; a neonate/infant has 270-305 that later fuse."}'),
  ('6e5af267-18','{"options": ["Malleus", "Lacrimal", "Stapes (stirrup)", "Coccyx"], "correct": 2, "explanation": "The stapes (stirrup), a middle-ear ossicle, is the smallest bone in the body. The stapedius is the smallest skeletal muscle."}'),
  ('a92a288d-y','{"options": ["Largest, longest, strongest, and heaviest bone", "Smallest bone", "Only sesamoid bone", "Longest but not strongest bone"], "correct": 0, "explanation": "The femur is the largest, longest, strongest, and heaviest bone in the body. The patella is a sesamoid bone."}'),
  ('01916474-21','{"options": ["Being cube-shaped", "Containing air sinuses (radiolucent on x-ray)", "Developing within tendons", "Being purely spongy"], "correct": 1, "explanation": "Pneumatic bones contain air-filled sinuses and appear radiolucent on x-ray (maxilla, frontal, ethmoid, sphenoid). Sesamoid bones (patella) develop within tendons."}'),
  ('29e57d11-1b','{"options": ["5", "8", "12", "28"], "correct": 1, "explanation": "The skull has 8 paired bones (palatine, parietal, temporal, inferior nasal concha, maxilla, nasal, zygomatic, lacrimal) and 5 unpaired (frontal, ethmoid, sphenoid, occipital, vomer)."}'),
  ('fc3b85cb-20','{"options": ["18-24 months", "6 months", "5 years", "2 months"], "correct": 0, "explanation": "The anterior fontanel is the largest (diamond-shaped) and closes at 18-24 months. The posterior fontanel closes at about 2 months."}'),
  ('79aed946-1j','{"options": ["Amphiarthrosis (slightly movable)", "Symphysis", "Synarthrosis (immovable)", "Diarthrosis (freely movable)"], "correct": 2, "explanation": "A suture is a synarthrosis (immovable joint). Gomphosis (teeth) and synchondrosis (epiphyseal plate) are also synarthroses."}'),
  ('e1c49dfb-26','{"options": ["Amphiarthrosis (slightly movable)", "Suture", "Diarthrosis", "Synarthrosis"], "correct": 0, "explanation": "Amphiarthroses are slightly movable joints, including symphyses (pubic symphysis, intervertebral discs) and syndesmoses."}'),
  ('2dcd83a9-2h','{"options": ["L3-L4 or L4-L5", "S2-S3", "L5-S1", "T12-L1"], "correct": 0, "explanation": "Lumbar puncture is done at L3-L4 or L4-L5; the L4 vertebra lies at the level of the iliac crests, safely below the spinal cord."}'),
  ('1628b623-1r','{"options": ["C2", "C1", "C7", "T1"], "correct": 1, "explanation": "C1 is the atlas, which supports the skull. C2 is the axis (dens), and C7 is the vertebra prominens."}'),
  ('6815cb83-10','{"options": ["T8-T10, attaching via a costal arch", "T1-T7, attaching directly to the sternum", "T11-T12, with no attachment", "All 12 pairs"], "correct": 1, "explanation": "True ribs (T1-T7) attach directly to the sternum. False ribs (T8-T10) attach via the costal arch, and floating ribs (T11-T12) have no anterior attachment."}'),
  ('cd4c2de4-26','{"options": ["Sarcolemma", "Sarcoplasmic reticulum", "Myofibril", "Sarcomere"], "correct": 3, "explanation": "The sarcomere, spanning two Z-lines, is the contractile unit of skeletal muscle."}'),
  ('73a3e70b-1q','{"options": ["Troponin T", "Troponin C", "Tropomyosin", "Troponin I"], "correct": 1, "explanation": "Troponin C has affinity for calcium. Troponin T binds tropomyosin, and troponin I binds actin."}'),
  ('3625c015-1f','{"options": ["Sarcolemma", "Mitochondria", "Sarcoplasmic reticulum", "Golgi complex"], "correct": 2, "explanation": "The sarcoplasmic reticulum releases calcium during the spike potential, triggering contraction; the calcium binds troponin C."}'),
  ('eba60feb-2m','{"options": ["Intercalated discs", "Striations", "Involuntary control", "Central nucleus"], "correct": 0, "explanation": "Intercalated discs are unique to cardiac muscle, allowing synchronised contraction. Cardiac and skeletal muscle are both striated; cardiac and smooth are both involuntary."}'),
  ('6e137743-15','{"options": ["Center of the cell", "Intercalated disc", "Sarcomere", "Periphery of the cell"], "correct": 3, "explanation": "Skeletal muscle is multinucleated with peripheral nuclei. Cardiac and smooth muscle have single, centrally located nuclei."}'),
  ('9c60e991-1p','{"options": ["Stapedius", "Sartorius", "Styloglossus", "Tensor tympani"], "correct": 0, "explanation": "The stapedius (in the middle ear) is the smallest and weakest skeletal muscle. Sartorius is the longest; quadriceps femoris is the strongest."}'),
  ('e6aa2fb4-1l','{"options": ["Widest skeletal muscle", "Longest skeletal muscle", "Shortest smooth muscle", "Strongest skeletal muscle"], "correct": 2, "explanation": "Mueller''s muscle (superior tarsal muscle) in the eyelids is the shortest smooth muscle, sympathetically innervated (its loss contributes to Horner''s ptosis)."}'),
  ('22a81b6a-12','{"options": ["Undergoes a single twitch", "Shortens and thickens while lifting a load", "Partially contracts in rotation", "Does not shorten because it contracts against a load it cannot move"], "correct": 3, "explanation": "In isometric contraction the muscle develops tension but does not shorten (it contracts against an immovable load), so no external work is done. Isotonic contraction shortens the muscle."}'),
  ('9dd82e38-1j','{"options": ["Requires two stimuli to respond", "Never fully contracts", "Responds proportionally to stimulus strength", "Responds maximally or not at all once the threshold is reached"], "correct": 3, "explanation": "By the all-or-none law, a fiber responds maximally or not at all once the stimulus reaches threshold; sub-threshold stimuli produce no response."}'),
  ('df865f09-2l','{"options": ["Brainstem", "Cerebellum", "Diencephalon", "Cerebrum"], "correct": 3, "explanation": "The cerebrum is the largest brain part, split into hemispheres by the longitudinal fissure, with four lobes."}'),
  ('cba13225-1q','{"options": ["Parietal", "Temporal", "Occipital", "Frontal"], "correct": 2, "explanation": "The occipital lobe handles visual perception (primary visual cortex, Brodmann area 17). The frontal lobe handles motor/planning."}'),
  ('8a88cf9d-z','{"options": ["Broca''s area", "Primary motor cortex", "Primary visual cortex (calcarine fissure)", "Wernicke''s area"], "correct": 2, "explanation": "Brodmann area 17 is the primary visual cortex at the calcarine fissure of the medial occipital lobe; injury causes cortical blindness."}'),
  ('2143a621-2k','{"options": ["Area 17", "Area 4", "Area 44", "Area 8"], "correct": 3, "explanation": "Brodmann area 8 is the frontal eye fields, governing conscious (voluntary) control of eye movements."}'),
  ('6e23e963-36','{"options": ["Brodmann area 18", "Brodmann area 17", "Brodmann area 19", "Brodmann area 22"], "correct": 2, "explanation": "Brodmann area 19 (associative visual/visuo-psychic cortex) injury causes visual agnosia. Area 17 injury causes cortical blindness."}'),
  ('326b895c-2e','{"options": ["Midbrain", "Medulla oblongata", "Pons", "Cerebellum"], "correct": 0, "explanation": "The Edinger-Westphal nucleus lies in the midbrain, providing parasympathetic fibres to CN III for the pupillary light reflex. The midbrain houses CN III and IV nuclei."}'),
  ('1ffed502-26','{"options": ["Thalamus", "Midbrain", "Pons", "Medulla oblongata"], "correct": 3, "explanation": "The medulla oblongata contains the vital cardiac, vasomotor, and respiratory centers, plus reflexes for coughing, vomiting, and swallowing."}'),
  ('ebd64e14-15','{"options": ["33", "12", "31", "24"], "correct": 2, "explanation": "There are 31 pairs of spinal nerves: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral, and 1 coccygeal. Cranial nerves number 12 pairs."}'),
  ('71062125-2z','{"options": ["It has no motor role", "Contralateral", "Bilateral only", "Ipsilateral (same side)"], "correct": 3, "explanation": "The cerebellum coordinates voluntary movement ipsilaterally (same side) and maintains balance and posture."}'),
  ('11985587-1j','{"options": ["Neuronal cell bodies with Nissl (tigroid) bodies and capillary blood", "Myelin sheaths", "Adipose tissue", "Cerebrospinal fluid"], "correct": 0, "explanation": "Grey matter contains neuronal cell bodies, dendrites, and unmyelinated axons with Nissl/tigroid bodies (rough ER); white matter is white due to myelinated tracts."}'),
  ('4c975efa-20','{"options": ["GABA", "Dopamine", "Acetylcholine", "Serotonin"], "correct": 1, "explanation": "The substantia nigra secretes dopamine; its degeneration is associated with Parkinson''s disease. The basal ganglia control motor activity."}'),
  ('82f57332-1f','{"options": ["Tricuspid valve", "Aortic semilunar valve", "Pulmonary semilunar valve", "Bicuspid (mitral) valve"], "correct": 3, "explanation": "The bicuspid (mitral) valve is the left atrioventricular valve. The tricuspid valve is the right atrioventricular valve."}'),
  ('b8abb1ba-1m','{"options": ["Portal circuit", "Systemic circuit", "Pulmonary circuit (to the lungs)", "Coronary circuit only"], "correct": 2, "explanation": "The right heart pumps deoxygenated blood to the lungs (pulmonary circuit). The left heart pumps oxygenated blood to the body (systemic circuit)."}'),
  ('dde7be59-3b','{"options": ["Venule", "Vein", "Artery", "Capillary"], "correct": 2, "explanation": "Arteries carry blood away from the heart, usually oxygenated (the pulmonary artery is the exception, carrying deoxygenated blood to the lungs)."}'),
  ('b105e336-1h','{"options": ["Lymph", "Plasma", "Buffy coat", "Serum"], "correct": 1, "explanation": "Plasma (about 55% of blood) is the liquid portion containing water, proteins (albumin, globulin, fibrinogen), electrolytes, and hormones. Formed elements are ~45%."}'),
  ('509cd992-22','{"options": ["Leukocyte", "Thrombocyte", "Erythrocyte (RBC)", "Monocyte"], "correct": 2, "explanation": "Erythrocytes (RBCs) carry oxygen via hemoglobin, lack a nucleus when mature, and live about 120 days."}'),
  ('4a3a54c2-1o','{"options": ["Potassium (K+)", "Sodium (Na+)", "Chloride (Cl-)", "Calcium (Ca2+)"], "correct": 0, "explanation": "Potassium (K+) is the dominant intracellular electrolyte; sodium and chloride dominate the extracellular fluid (ECF)."}'),
  ('eb4e0d0c-1l','{"options": ["One-quarter", "Two-thirds (about 66%)", "One-half", "One-third"], "correct": 1, "explanation": "About two-thirds (66%) of total body weight is water, split into intracellular (40%) and extracellular (20%) compartments."}'),
  ('55b09488-1s','{"options": ["Goblet cells", "Type II pneumocytes", "Type I pneumocytes", "Ciliated cells"], "correct": 1, "explanation": "Type II pneumocytes secrete surfactant; its deficiency causes respiratory distress syndrome (RDS) in premature infants."}'),
  ('d9da6f12-2j','{"options": ["Narrower and more horizontal", "Longer than the left", "Cartilage-free", "Wider, shorter, and more vertical"], "correct": 3, "explanation": "The right primary bronchus is wider, shorter, and more vertical, so aspirated foreign bodies tend to lodge there."}'),
  ('457dae06-x','{"options": ["4", "3", "5", "2"], "correct": 1, "explanation": "The right lung has 3 lobes (upper, middle, lower); the left lung has 2 (upper, lower) to accommodate the heart."}'),
  ('9cad3386-1v','{"options": ["Cricoid cartilage", "Sternal angle of Louis (T4-T5)", "Xiphoid process", "Hyoid bone"], "correct": 1, "explanation": "The trachea bifurcates at the carina at the sternal angle of Louis (T4-T5)."}'),
  ('f0c0ae85-1x','{"options": ["Stomach", "Small intestine", "Pancreas", "Liver"], "correct": 0, "explanation": "The stomach produces intrinsic factor (from parietal cells) for vitamin B12 absorption, along with HCl and pepsin."}'),
  ('282c0fd2-1o','{"options": ["Stomach", "Large intestine", "Esophagus", "Small intestine"], "correct": 3, "explanation": "The small intestine is the major site of digestion and absorption, aided by villi and microvilli that increase surface area."}'),
  ('83890dc0-19','{"options": ["Delta cells", "Alpha cells", "Beta cells (islets of Langerhans)", "Acinar cells"], "correct": 2, "explanation": "Beta cells of the islets of Langerhans produce insulin (lowers blood glucose). Alpha cells produce glucagon (raises blood glucose)."}'),
  ('abf448bd-1z','{"options": ["Liver", "Spleen", "Pancreas", "Gallbladder"], "correct": 0, "explanation": "The liver is the largest gland/internal organ; it produces bile (emulsifies fats), detoxifies, and stores glycogen."}'),
  ('3a32c7d9-1h','{"options": ["Submandibular", "Buccal", "Sublingual", "Parotid"], "correct": 3, "explanation": "The parotid is the largest salivary gland, innervated by CN IX (glossopharyngeal)."}'),
  ('be70ef8a-14','{"options": ["Ureter", "Collecting duct", "Glomerulus", "Nephron"], "correct": 3, "explanation": "The nephron is the functional unit of the kidney (about 1 million per kidney); it filters blood and forms urine."}'),
  ('1bb01269-1t','{"options": ["Stomach", "Liver", "Pancreas", "Spleen"], "correct": 1, "explanation": "The right kidney is slightly lower than the left due to the large liver above it. The kidneys are retroperitoneal at about T12-L3."}'),
  ('c1dc893c-2a','{"options": ["Pituitary", "Pineal", "Adrenal", "Thyroid"], "correct": 0, "explanation": "The pituitary is the master gland (GH, TSH, ACTH, FSH, LH, ADH, oxytocin), regulating other endocrine glands."}'),
  ('6aaad9cd-1c','{"options": ["Raising it by stimulating osteoclasts", "Lowering it via calcitonin", "Having no effect on calcium", "Storing it in muscle"], "correct": 0, "explanation": "PTH raises blood calcium by stimulating osteoclasts (bone resorption). Calcitonin from the thyroid lowers blood calcium."}'),
  ('5754e596-1t','{"options": ["Thyroid", "Pineal gland", "Adrenal medulla", "Pituitary"], "correct": 1, "explanation": "The pineal gland secretes melatonin, regulating the sleep-wake (circadian) cycle."}'),
  ('1f3d0ec5-24','{"options": ["Insulin and glucagon", "Cortisol and aldosterone", "T3 and T4", "Epinephrine and norepinephrine"], "correct": 3, "explanation": "The adrenal medulla secretes epinephrine and norepinephrine (fight-or-flight). The adrenal cortex secretes cortisol and aldosterone."}'),
  ('ee921eac-24','{"options": ["22", "44 and 45", "41", "3, 1, 2"], "correct": 1, "explanation": "Broca''s area (Brodmann 44/45) in the dominant frontal lobe governs speech production. Wernicke''s area (area 22) handles language comprehension."}'),
  ('d5b81d30-1u','{"options": ["4", "17", "22", "8"], "correct": 2, "explanation": "Brodmann area 22 is Wernicke''s area, for language comprehension and semantic processing. Broca''s area (44/45) is for speech production."}'),
  ('4cf63bba-27','{"options": ["Cerebellum", "Pons Varolii", "Medulla oblongata", "Midbrain"], "correct": 1, "explanation": "The pons contains the pneumotaxic center (with apneustic and expiration centers). The medulla contains the basic respiratory rhythm center."}'),
  ('f2b37976-1c','{"options": ["CN I and II", "CN V through VIII", "CN IX through XII", "CN III and IV"], "correct": 1, "explanation": "The pons houses the nuclei of CN V through VIII. The midbrain has CN III and IV; the medulla has CN IX through XII."}'),
  ('ebf493e5-13','{"options": ["Childhood autobiography", "Motor skills without conscious recall", "Numbers and words for language (facts)", "Personal experiences at a specific time and place"], "correct": 2, "explanation": "Semantic memory is recall of facts, numbers, and words for language. Episodic memory is personal experiences; procedural memory is skills without conscious recall."}'),
  ('4696c03e-1a','{"options": ["Sacrum", "Ischium", "Pubis", "Ilium"], "correct": 1, "explanation": "The ischium is the strongest pelvic bone; the ilium is the largest, and the pubis is the most anterior (fused at the symphysis pubis)."}'),
  ('8d299ddb-1a','{"options": ["Sartorius", "Quadriceps femoris", "Latissimus dorsi", "Gastrocnemius"], "correct": 0, "explanation": "The sartorius is the longest skeletal muscle. The quadriceps femoris is the strongest, and the latissimus dorsi is the widest."}'),
  ('3a2ee4f7-28','{"options": ["Tibialis anterior", "Quadriceps", "Sartorius", "Gastrocnemius"], "correct": 3, "explanation": "The Achilles (calcaneal) tendon connects the gastrocnemius to the calcaneus and is the largest tendon in the body."}'),
  ('f8cdafd9-2k','{"options": ["Synarthrosis", "Suture", "Amphiarthrosis", "Diarthrosis (freely movable)"], "correct": 3, "explanation": "Ball-and-socket (enarthrosis) joints are diarthroses (freely movable), like the shoulder and hip. Hinge, pivot, condyloid, and saddle joints are also diarthroses."}'),
  ('01b20208-23','{"options": ["Diarthrosis", "Synarthrosis (immovable)", "Symphysis", "Amphiarthrosis"], "correct": 1, "explanation": "Gomphosis (tooth in socket) is a synarthrosis (immovable joint), like sutures and synchondroses."}'),
  ('4657d73d-16','{"options": ["126", "33", "80", "206"], "correct": 2, "explanation": "The axial skeleton has 80 bones; the appendicular skeleton has 126, totalling 206."}'),
  ('cd4f2b1a-n','{"options": ["Store fat", "Destroy/resorb bone", "Produce red blood cells", "Build new bone"], "correct": 1, "explanation": "Osteoclasts are bone destroyers (resorption); osteoblasts are bone builders. Their balance controls bone remodelling."}'),
  ('63f1e53d-u','{"options": ["Fat storage", "Calcium storage only", "Hematopoiesis (blood cell formation)", "Bile production"], "correct": 2, "explanation": "Red bone marrow contains stem cells and produces blood cells (hematopoiesis). Yellow marrow is mostly fat."}'),
  ('dd9fb644-2l','{"options": ["Calcium phosphate", "Cartilage", "Elastin", "Collagen protein"], "correct": 0, "explanation": "The inorganic portion (~2/3) is calcium phosphate, giving bone hardness, rigidity, and radiographic opacity; the organic third (protein) gives resilience."}'),
  ('00e084dc-22','{"options": ["20 stimuli/sec", "5 stimuli/sec", "100 stimuli/sec", "1 stimulus/sec"], "correct": 0, "explanation": "Complete tetanus (fully fused contractions) occurs above about 20 stimuli/sec; incomplete tetanus is below 20/sec."}'),
  ('3d5a890a-15','{"options": ["Complete muscle relaxation", "Summation where successive twitches progressively increase in strength", "Isometric contraction", "A single twitch"], "correct": 1, "explanation": "The Treppe or staircase phenomenon is a form of summation in which successive twitches grow stronger as the muscle ''warms up.''"}'),
  ('62305241-24','{"options": ["Tropomyosin", "Actin", "Myosin", "Troponin"], "correct": 3, "explanation": "Smooth muscle lacks troponin; it uses calmodulin instead to regulate the actin-myosin interaction, but the sliding mechanism is otherwise similar."}'),
  ('5b824eb5-1o','{"options": ["Potassium and phosphate", "Sodium and chloride", "Calcium and magnesium", "Bicarbonate only"], "correct": 1, "explanation": "Sodium (Na+) and chloride (Cl-) dominate the ECF; potassium (K+) dominates the ICF."}'),
  ('bc7b62c4-27','{"options": ["Intracellular fluid", "Transcellular fluid (part of ECF)", "Plasma", "Lymph only"], "correct": 1, "explanation": "Aqueous humor, CSF, and endolymph are transcellular fluids, a subset of the extracellular fluid compartment."}'),
  ('04227b56-w','{"options": ["From low to high solute concentration", "From high to low solute concentration", "Against a pressure gradient using carriers", "Only with ATP"], "correct": 0, "explanation": "Osmosis moves water from an area of low solute concentration to high solute concentration (down its own concentration gradient), requiring no energy."}'),
  ('3976b14f-1r','{"options": ["Only for gases", "Only by filtration", "Down the gradient without energy", "From low to high concentration, requiring ATP"], "correct": 3, "explanation": "Active transport moves solutes from low to high concentration against the gradient and requires ATP and a carrier."}'),
  ('741f8bf2-r','{"options": ["Filter inhaled air", "Prevent food from entering the airway during swallowing", "Warm inhaled air", "Produce voice"], "correct": 1, "explanation": "The epiglottis covers the laryngeal opening during swallowing to prevent food from entering the airway."}'),
  ('04f85e57-1w','{"options": ["Protein", "Nucleic acid", "Carbohydrate", "Fat"], "correct": 2, "explanation": "Salivary amylase begins carbohydrate (starch) digestion in the mouth. Protein digestion begins in the stomach (pepsin); fat digestion mainly in the small intestine."}'),
  ('8da339c6-2a','{"options": ["Pancreas", "Duodenum", "Gallbladder", "Spleen"], "correct": 2, "explanation": "Bile is produced by the liver and stored/concentrated in the gallbladder before release into the duodenum."}'),
  ('31a7d06e-1n','{"options": ["Does not carry urine", "Is longer (~20 cm) and also carries semen", "Has no sphincter", "Is shorter (~4 cm)"], "correct": 1, "explanation": "The male urethra is about 20 cm and carries both urine and semen; the female urethra is about 4 cm and carries only urine."}'),
  ('a813bef0-1f','{"options": ["Cortisol", "Calcitonin", "Parathyroid hormone", "T3"], "correct": 1, "explanation": "Calcitonin from the thyroid lowers blood calcium (opposing PTH). T3/T4 regulate metabolism."}'),
  ('045906b6-2b','{"options": ["Spleen", "Bone marrow", "Kidneys", "Liver"], "correct": 2, "explanation": "The kidneys produce erythropoietin, stimulating red blood cell production in the bone marrow, alongside their filtration role."}'),
  ('441ecb61-1s','{"options": ["Maxilla", "Nasal", "Vomer", "Palatine"], "correct": 2, "explanation": "The vomer is an unpaired bone forming the inferior nasal septum. Maxilla, palatine, and nasal bones are paired."}'),
  ('3fbdee19-1o','{"options": ["26", "33", "24", "31"], "correct": 0, "explanation": "The adult has 26 vertebrae (with sacral and coccygeal fusions); a child has 33 before fusion."}'),
  ('58be002e-1j','{"options": ["Bronchioles", "Alveoli", "Trachea", "Bronchi"], "correct": 1, "explanation": "The alveoli (about 300 million) are the site of gas exchange, with thin walls adjacent to capillaries."}'),
  ('708c8f42-v','{"options": ["Pleural cavity", "Mediastinum", "Cranial cavity", "Abdominal cavity"], "correct": 1, "explanation": "The heart lies in the mediastinum (the central compartment of the thoracic cavity), enclosed by the pericardium."}'),
  ('c921b730-20','{"options": ["Only gastric acid", "Bile and pancreatic juice", "Lymph", "Only saliva"], "correct": 1, "explanation": "The duodenum receives bile (from the liver/gallbladder) and pancreatic juice (enzymes), making it the major site of chemical digestion in the small intestine."}'),
  ('d3849a60-1a','{"options": ["Water and electrolyte reabsorption", "Nutrient absorption", "Protein digestion", "Bile production"], "correct": 0, "explanation": "The large intestine reabsorbs water and electrolytes, compacts waste, and houses gut flora. Most nutrient absorption occurs in the small intestine."}'),
  ('e8aed0e9-27','{"options": ["Rotation", "Flexion and extension only", "Gliding only", "No movement"], "correct": 0, "explanation": "A pivot (trochoid) joint, like the atlanto-axial joint, permits rotation. It is a type of diarthrosis (freely movable joint)."}'),
  ('6ce53efe-24','{"options": ["Plasma exclusively", "Extracellular fluid", "Neither", "Intracellular fluid"], "correct": 1, "explanation": "Transcellular fluids (CSF, aqueous humor, endolymph) are part of the extracellular fluid compartment, which is about 20% of total body water."}'),
  ('e6179779-11','{"options": ["The study of poisons", "The study of drug dosage", "What the body does to the drug (ADME)", "What the drug does to the body"], "correct": 2, "explanation": "Pharmacokinetics is ''what the body does to the drug'' (absorption, distribution, metabolism, excretion). Pharmacodynamics is ''what the drug does to the body.''"}'),
  ('a6f09695-23','{"options": ["Pharmacodynamics", "Pharmacognosy", "Pharmacokinetics", "Posology"], "correct": 0, "explanation": "Pharmacodynamics studies drug effects and mechanisms on the body. Pharmacognosy identifies natural crude drugs; posology is the study of dosage."}'),
  ('89b44770-l','{"options": ["Time to reach steady state", "Duration of drug action", "Maximum effect a drug can produce", "Lowest concentration needed to produce the desired effect (EC50/ED50)"], "correct": 3, "explanation": "Potency is the lowest concentration/dose needed for the desired effect (EC50/ED50). Efficacy is the maximum effect achievable (Emax)."}'),
  ('7b3c4753-q','{"options": ["Volume of distribution", "Rate of metabolism", "Dose producing 50% response", "Maximum effect a drug can produce (Emax)"], "correct": 3, "explanation": "Efficacy is the maximal response a drug can produce (Emax). A drug can be very potent yet have low efficacy."}'),
  ('802f96d0-g','{"options": ["Increased sensitivity from denervation", "An idiosyncratic reaction", "Reduced sensitivity from antibody formation", "Tolerance developing rapidly after only a few doses"], "correct": 3, "explanation": "Tachyphylaxis is rapidly developing tolerance after just a few doses. Tolerance in general is reduced response from prior exposure (often via enzyme induction)."}'),
  ('9c9dd0a1-32','{"options": ["Tolerance", "Idiosyncratic reaction", "Tachyphylaxis", "Supersensitivity"], "correct": 1, "explanation": "An idiosyncratic reaction is an unexpected response with no clear pharmacodynamic or hypersensitivity basis, often genetically determined."}'),
  ('8a3e91c7-2r','{"options": ["Phase III", "Phase II", "Phase IV", "Phase I"], "correct": 2, "explanation": "Phase IV is post-approval surveillance in the general population, monitoring for problems after the New Drug Application is approved."}'),
  ('864a9b72-15','{"options": ["Limits damage from the process", "Prevents the disease", "Reverses the basic pathologic process", "Relieves symptoms without modifying the causal process"], "correct": 3, "explanation": "A palliative drug relieves symptoms without changing the underlying cause. A curative drug reverses the pathology; a protective drug limits damage."}'),
  ('5559b50d-1l','{"options": ["About 50%", "Variable and unpredictable", "100%", "Less than 10%"], "correct": 2, "explanation": "IV administration delivers 100% bioavailability (zero-order absorption kinetics), bypassing first-pass metabolism, with rapid onset and short duration."}'),
  ('23773150-1a','{"options": ["Inhalational", "Sublingual", "Intravenous", "Oral"], "correct": 3, "explanation": "Orally administered drugs pass through the liver before reaching systemic circulation, so they undergo first-pass metabolism. IV and sublingual routes largely bypass it."}'),
  ('5aedaa1c-2r','{"options": ["Facilitated diffusion", "Passive diffusion", "Active transport", "Filtration"], "correct": 2, "explanation": "Active transport moves drug against the gradient using ATP and a carrier, and is saturable. Passive diffusion needs no energy or carrier."}'),
  ('1c214b29-17','{"options": ["A prodrug", "Pharmacologically active and able to reach the site of action", "A metabolite", "Bound to albumin"], "correct": 1, "explanation": "The free/unbound drug is active and can leave the blood to act; the albumin-bound fraction is inactive until released."}'),
  ('bff2e07c-1e','{"options": ["Spleen", "Lung", "Kidney", "Liver (cytochrome P450 system)"], "correct": 3, "explanation": "The liver, via the cytochrome P450 microsomal enzyme system, is the primary site of drug metabolism."}'),
  ('3dff7e63-1v','{"options": ["Oxidation", "Acetylation", "Conjugation", "Methylation"], "correct": 0, "explanation": "Oxidation (addition of O2 or removal of hydrogen) is the most common Stage I reaction, carried out by cytochrome P450. Stage II is conjugation."}'),
  ('1e341b80-16','{"options": ["Induces microsomal oxidation enzymes", "Inhibits microsomal oxidation", "Has zero bioavailability", "Is excreted unchanged"], "correct": 0, "explanation": "Phenobarbital (and chlorpromazine) induce microsomal oxidation enzymes, increasing metabolism. Metronidazole is an inhibitor."}'),
  ('29abff02-2s','{"options": ["1-2", "10-12", "20", "4-5"], "correct": 3, "explanation": "Steady state (dynamic equilibrium between intake and elimination) is reached after about 4-5 half-lives."}'),
  ('c123b980-1h','{"options": ["Zero", "Constant regardless of concentration", "Independent of clearance", "Proportional to the drug''s plasma concentration"], "correct": 3, "explanation": "First-order elimination removes a constant FRACTION per unit time, so the rate is proportional to plasma concentration. Zero-order removes a constant amount regardless of concentration."}'),
  ('58408d24-2d','{"options": ["Half-life", "Clearance", "Volume of distribution", "AUC"], "correct": 1, "explanation": "Clearance (Cl) is the volume of plasma cleared of drug per unit time. Volume of distribution relates concentration to total drug in the body."}'),
  ('b9757eed-x','{"options": ["High intrinsic activity", "Submaximal activity", "Negative intrinsic activity", "Zero intrinsic activity — it blocks the agonist but has no effect alone"], "correct": 3, "explanation": "An antagonist has affinity but ZERO intrinsic activity: it blocks agonist binding and has no effect alone. An inverse agonist has NEGATIVE intrinsic activity."}'),
  ('d1eb8562-1k','{"options": ["Produces a maximal response", "Has no affinity", "Has negative intrinsic activity, actively opposing baseline receptor activity", "Is always irreversible"], "correct": 2, "explanation": "An inverse agonist has negative intrinsic activity, reducing receptor activity below baseline even without an agonist present. An antagonist merely blocks (zero intrinsic activity)."}'),
  ('f72ec61b-1m','{"options": ["Is metabolised faster", "Has no affinity", "Binds a different receptor", "Occupies the receptor but produces only a submaximal effect"], "correct": 3, "explanation": "A partial agonist binds with full affinity but low intrinsic activity, so it produces a submaximal effect and competes with (thus reduces) the action of a full agonist."}'),
  ('2a187c72-1i','{"options": ["Chemical neutralisation", "Increasing the agonist dose", "Lowering the agonist dose", "Adding an inverse agonist"], "correct": 1, "explanation": "Competitive antagonists bind reversibly at the same active site, so increasing agonist concentration can overcome (surmount) the block. Non-competitive antagonism cannot be overcome this way."}'),
  ('1e0d2234-25','{"options": ["Synergism", "Potentiation", "Antagonism", "Addition"], "correct": 0, "explanation": "Synergism is a supra-additive effect (1+1=3). Potentiation is 0+1=2 (a drug with no effect alone enhances another); addition is 1+1=2."}'),
  ('ede1214d-15','{"options": ["Emax / EC50", "TD50 / ED50", "LD50 x ED50", "ED50 / TD50"], "correct": 1, "explanation": "TI = TD50 / ED50. A larger TI means a wider safety margin; drugs like digoxin, warfarin, and lithium have low TIs."}'),
  ('2ee01a27-1s','{"options": ["Cannot cause toxicity", "Has a narrow margin of safety and needs careful monitoring", "Has no toxic dose", "Is very safe with a wide margin"], "correct": 1, "explanation": "A low therapeutic index means the toxic and effective doses are close, so a narrow margin of safety requires monitoring."}'),
  ('059f0176-1g','{"options": ["Determine half-life", "Show maximal efficacy of a drug", "Assess a drug''s margin of safety across a population", "Measure receptor affinity"], "correct": 2, "explanation": "The quantal dose-response plots the percentage of a population responding versus dose and is used to assess the margin of safety (ED50, TD50, LD50)."}'),
  ('b5ff3f00-1t','{"options": ["Subscription", "Signa", "Superscription", "Inscription"], "correct": 2, "explanation": "The superscription is the Rx symbol. The inscription names the drug and strength; the subscription directs the dispenser; the signa directs the patient."}'),
  ('0db16289-18','{"options": ["Every hour", "As needed", "At bedtime", "Before meals"], "correct": 2, "explanation": "''h.s.'' (hora somni) means at bedtime. ''q.h.'' is every hour, ''a.c.'' is before meals, ''p.r.n.'' is as needed."}'),
  ('b684bd34-q','{"options": ["Left eye", "Every hour", "Each/both eyes", "Right eye"], "correct": 2, "explanation": "''O.U.'' (oculo utro/uterque) means each or both eyes. O.D. is right eye, O.S. is left eye."}'),
  ('b03a541d-1i','{"options": ["N-acetylcysteine", "Flumazenil", "Naloxone", "Sodium bicarbonate"], "correct": 0, "explanation": "N-acetylcysteine is the antidote for acetaminophen hepatotoxicity, effective when given 8-24 hours after ingestion. Aspirin overdose is managed with sodium bicarbonate."}'),
  ('e8e96a25-p','{"options": ["Acetaminophen toxicity", "Digitalis toxicity", "Benzodiazepine overdose", "Acute opioid overdose"], "correct": 3, "explanation": "Naloxone is an opioid antagonist used for acute opioid overdose. Naltrexone is a maintenance agent for opioid addiction programs."}'),
  ('58215d2f-1j','{"options": ["Nystagmus", "Mydriasis", "Cycloplegia only", "Miosis (pinpoint pupils)"], "correct": 3, "explanation": "Opioids cause miosis (pinpoint pupils), plus decreased accommodation and a myopic shift."}'),
  ('5f708b49-17','{"options": ["Opening calcium channels", "Decreasing sodium permeability of the nerve membrane, preventing depolarisation", "Increasing potassium permeability", "Blocking acetylcholinesterase"], "correct": 1, "explanation": "Local anesthetics decrease Na+ permeability, blocking depolarisation and nerve conduction."}'),
  ('f837f562-1b','{"options": ["The liver", "The lung", "Plasma (blood) esterases", "The kidney"], "correct": 2, "explanation": "Esters are hydrolysed by plasma esterases and have shorter action; amides are metabolised by the liver and act longer."}'),
  ('49428220-2b','{"options": ["Both are equally active", "Amides remain active while esters do not", "Neither works at all", "Esters remain fully active"], "correct": 1, "explanation": "Amides remain active in the acidic environment of purulent inflammation, whereas esters are not active there."}'),
  ('6989f88a-2e','{"options": ["Tetracaine", "Benzocaine", "Proparacaine 0.5%", "Cocaine"], "correct": 2, "explanation": "Proparacaine 0.5% is the most common topical ophthalmic anesthetic: fast onset (5-15 sec), short duration, and least irritating."}'),
  ('78bee208-18','{"options": ["Has no anesthetic effect", "Causes miosis", "Softens the cornea and gives falsely low IOP readings", "Is too weak"], "correct": 2, "explanation": "Cocaine softens the corneal epithelium, producing falsely low IOP values, so it is unsuitable for tonometry. It is the only natural local anesthetic and has adrenergic (mydriatic, vasoconstrictive) effects."}'),
  ('987dc719-2m','{"options": ["Epinephrine", "Bicarbonate", "Hyaluronidase", "Sodium chloride"], "correct": 0, "explanation": "Epinephrine causes local vasoconstriction, reducing systemic absorption and prolonging anesthesia. Hyaluronidase spreads the drug; bicarbonate raises the non-ionised fraction."}'),
  ('b5c71a97-2d','{"options": ["Bradycardia", "Convulsive seizures", "Hypotension", "Drowsiness"], "correct": 1, "explanation": "Convulsive seizures are the most serious early excitatory CNS sign of local anesthetic toxicity, before the late depressive phase (coma, respiratory failure)."}'),
  ('ad12b0cf-1l','{"options": ["Inorganic salt", "Ester", "Amide", "Natural alkaloid"], "correct": 2, "explanation": "Lidocaine (Xylocaine) is an amide, the most common injectable local anesthetic; it is also used IV for ventricular arrhythmias."}'),
  ('bb8adaf5-2x','{"options": ["Orthostatic hypotension", "Weight gain", "Bradycardia", "Hyperkalemia"], "correct": 0, "explanation": "Orthostatic (postural) hypotension is common to most antihypertensive classes because of their vasodilatory/sympatholytic actions."}'),
  ('dcad7d67-1f','{"options": ["Hydrochlorothiazide", "Mannitol", "Spironolactone", "Furosemide"], "correct": 0, "explanation": "Hydrochlorothiazide (a thiazide) is the most commonly used antihypertensive diuretic and is often combined with ACE inhibitors, beta-blockers, or ARBs."}'),
  ('b60f0378-1q','{"options": ["Blocking beta-1 receptors", "Blocking calcium channels", "Direct arteriolar dilation", "Inhibiting the angiotensin-converting enzyme and reducing sodium/water retention"], "correct": 3, "explanation": "ACE inhibitors block conversion of angiotensin I to II, reducing vasoconstriction and aldosterone-driven sodium/water retention."}'),
  ('090eb2b6-3c','{"options": ["Cause hyperkalemia", "Cause sodium and water retention (and reflex tachycardia)", "Are too weak alone", "Cause hypoglycemia"], "correct": 1, "explanation": "Direct vasodilators cause reflex sodium/water retention and tachycardia, so they are paired with diuretics and beta-blockers. Minoxidil is also used as a hair grower."}'),
  ('8d632ef7-3t','{"options": ["Gout", "Hyperkalemia", "Bradycardia", "Elevated liver enzymes (ALT/SGOT)"], "correct": 3, "explanation": "Statins inhibit HMG-CoA reductase in the liver and can elevate hepatic transaminases (ALT/SGOT), requiring monitoring."}'),
  ('ec3b6db7-1m','{"options": ["Diet, Diuretics, Digitalis", "Diet, Dobutamine, Dialysis", "Digoxin, Dopamine, Diltiazem", "Diuretics, Dilators, Dobutamine"], "correct": 0, "explanation": "The classic 3-D management of CHF is Diet, Diuretics, and Digitalis."}'),
  ('8e39da89-2e','{"options": ["The chloride channel", "The sodium-potassium (Na-K) ATPase pump", "The calcium pump", "The proton pump"], "correct": 1, "explanation": "Digitalis inhibits the myocardial Na-K ATPase, raising intracellular calcium for a positive inotropic effect (and slows the heart, a negative chronotropic effect)."}'),
  ('c71b486f-1l','{"options": ["Seizure", "Anorexia", "Xanthopsia", "Arrhythmia"], "correct": 1, "explanation": "Anorexia is typically the earliest sign of digitalis toxicity, followed by nausea and vomiting. Xanthopsia is the classic ocular sign."}'),
  ('93630e19-1c','{"options": ["Red-green defect", "Bull''s-eye maculopathy", "Cornea verticillata", "Xanthopsia (yellow vision) with a glare phenomenon"], "correct": 3, "explanation": "Digitalis toxicity causes xanthopsia (yellow vision), colored halos, and a ''glare phenomenon'' (objects appear brown-orange or snow-covered)."}'),
  ('20996c21-2h','{"options": ["Digoxin", "Aspirin", "Beta-blockers", "Calcium channel blockers"], "correct": 3, "explanation": "Prinzmetal (variant) angina from coronary vasospasm is best treated with calcium channel blockers (plus organic nitrates). Beta-blockers can worsen vasospasm."}'),
  ('0acb5dd8-1s','{"options": ["Increases cGMP to relax vascular smooth muscle", "Blocks beta receptors", "Blocks calcium channels directly", "Inhibits the Na-K pump"], "correct": 0, "explanation": "Nitrates are metabolised to nitric oxide, which raises cGMP and relaxes vascular smooth muscle, reducing preload and cardiac oxygen demand."}'),
  ('9bc504bb-27','{"options": ["Quinidine", "Amiodarone", "Verapamil", "Lidocaine"], "correct": 3, "explanation": "Lidocaine is the class IB sodium-channel blocker and DOC for ventricular arrhythmias. Amiodarone is class III; verapamil is class IV."}'),
  ('350f46d7-1u','{"options": ["Thoraco-lumbar", "Adrenergic", "Sympathomimetic", "Cranio-sacral"], "correct": 3, "explanation": "The parasympathetic division is cranio-sacral (cholinergic). The sympathetic division is thoraco-lumbar (adrenergic)."}'),
  ('8a0db72c-37','{"options": ["Dobutamine", "Epinephrine", "Phenylephrine", "Norepinephrine"], "correct": 0, "explanation": "Dobutamine selectively stimulates beta-1 receptors, improving contractility in CHF without significant vasoconstriction."}'),
  ('8dd78298-1p','{"options": ["Muscarinic M2", "Alpha-1", "Central alpha-2 (inhibitory)", "Beta-1"], "correct": 2, "explanation": "Clonidine is a central alpha-2 agonist; stimulating the inhibitory alpha-2 pathway decreases sympathetic outflow and lowers blood pressure."}'),
  ('0e09af3c-3a','{"options": ["M2", "M1", "NM", "M3"], "correct": 3, "explanation": "M3 muscarinic receptors (Gq pathway) mediate sphincter and ciliary muscle contraction, producing miosis, accommodation, and opening of the trabecular meshwork."}'),
  ('026cf48d-2o','{"options": ["Gq → phospholipase C", "Gi → inhibit adenylyl cyclase → decrease cAMP", "Gs → increase cAMP", "Direct ion channel only"], "correct": 1, "explanation": "Cardiac M2 receptors use the Gi pathway (inhibiting adenylyl cyclase, decreasing cAMP), slowing heart rate and AV conduction."}'),
  ('e44d37aa-30','{"options": ["Beta-1 selectivity", "Intrinsic sympathomimetic activity (ISA)", "Lipophilicity", "Membrane-stabilising activity (MSA)"], "correct": 3, "explanation": "Membrane-stabilising activity (MSA), a local-anesthetic-like effect, damages corneal epithelium, so MSA-possessing beta-blockers (labetalol, propranolol, metoprolol) are not used topically in the eye."}'),
  ('b1bc9ea8-22','{"options": ["Beta-2 receptors", "Muscarinic M3 receptors", "Nicotinic (NN) receptors in BOTH sympathetic and parasympathetic ganglia", "Alpha-1 receptors"], "correct": 2, "explanation": "Ganglionic blockers block nicotinic neuronal (NN) receptors in both autonomic ganglia, arresting the entire ANS, producing complex effects and rare clinical use."}'),
  ('dafcacdd-1u','{"options": ["Aphakic eyes", "Glaucoma patients", "Adults over 40", "Children"], "correct": 3, "explanation": "Cyclopentolate is the DOC for cycloplegic refraction in children (with 0.5-1% to limit CNS effects). Atropine is used when maximum cycloplegia is needed."}'),
  ('f0e3327a-2u','{"options": ["Naloxone", "Methadone only IV", "Naltrexone", "Flumazenil"], "correct": 2, "explanation": "Naltrexone is used for maintenance in opioid-dependence programs; naloxone is the acute overdose reversal agent."}'),
  ('b4e13700-2n','{"options": ["30S ribosomal subunit", "Cell wall", "DNA gyrase", "50S ribosomal subunit"], "correct": 0, "explanation": "These classes bind the 30S ribosomal subunit. Chloramphenicol, macrolides, and lincosamides bind the 50S subunit."}'),
  ('ab844bcf-26','{"options": ["Protein synthesis at 50S", "Folic acid synthesis", "DNA gyrase", "Cell wall synthesis (transpeptidase/PBP)"], "correct": 3, "explanation": "Beta-lactams inhibit the transpeptidase (penicillin-binding proteins) that cross-links peptidoglycan, blocking cell wall synthesis."}'),
  ('e2a943b8-1b','{"options": ["RNA polymerase", "Dihydrofolate reductase", "DNA gyrase (topoisomerase II)", "Carbonic anhydrase"], "correct": 2, "explanation": "Fluoroquinolones inhibit DNA gyrase (topoisomerase II), preventing DNA supercoiling and replication."}'),
  ('e2579676-28','{"options": ["Tetrahydrofolate", "Dihydrofolate", "Thymidine", "PABA (para-aminobenzoic acid)"], "correct": 3, "explanation": "Sulfonamides are PABA analogues that competitively inhibit dihydropteroate synthetase, blocking bacterial folate synthesis."}'),
  ('29c6e777-1q','{"options": ["Lipoxygenase only", "Carbonic anhydrase", "Phospholipase A2", "Cyclooxygenase"], "correct": 2, "explanation": "Corticosteroids inhibit phospholipase A2, reducing arachidonic acid and therefore both prostaglandins and leukotrienes. NSAIDs inhibit cyclooxygenase only."}'),
  ('a02b86f2-13','{"options": ["Acetylcholinesterase", "Phospholipase A2", "Cyclooxygenase (COX)", "The Na-K pump"], "correct": 2, "explanation": "NSAIDs inhibit cyclooxygenase (COX), decreasing prostaglandin synthesis, giving analgesic, antipyretic, and anti-inflammatory effects."}'),
  ('bec1e960-t','{"options": ["The name only used in research", "The manufacturer''s trademark", "A shortened scientific name based on the active ingredient", "The complete chemical structure description"], "correct": 2, "explanation": "The generic name is a shortened scientific name based on the active ingredient and is widely used. The chemical name describes the full structure; the brand/trade name is the manufacturer''s."}'),
  ('f7071d3a-20','{"options": ["Reach its peak", "Reach steady state", "Decrease by 50%", "Double"], "correct": 2, "explanation": "Half-life is the time for the plasma concentration to fall by 50% after discontinuation (rate constant = 0.693/t1/2)."}'),
  ('f0106c3e-1k','{"options": ["Enzyme induction", "Rapid dosing", "Antibody formation", "Denervation"], "correct": 3, "explanation": "Supersensitivity is increased sensitivity resulting from denervation. Tolerance comes from enzyme induction; immunity from antibody formation."}'),
  ('a1c53059-1g','{"options": ["Hydrogen bond", "Covalent bond", "Van der Waals bond", "Ionic bond"], "correct": 1, "explanation": "The covalent bond is the strongest and produces an irreversible effect. Van der Waals bonds are weakest but most common; ionic and hydrogen bonds are reversible."}'),
  ('1ae88146-2q','{"options": ["Relative bioavailability", "Volume of distribution", "Clearance", "Absolute bioavailability"], "correct": 3, "explanation": "Absolute bioavailability compares a non-IV route to the IV route (100%). Relative bioavailability compares two non-IV formulations of the same drug."}'),
  ('455fd9d3-1r','{"options": ["Tetracaine", "Benoxinate", "Cocaine", "Proparacaine"], "correct": 0, "explanation": "Tetracaine is preferred for ERG. Proparacaine or benoxinate are used for applanation tonometry and gonioscopy; cocaine is used for corneal epithelial debridement and Horner''s testing."}'),
  ('7c55ae24-22','{"options": ["Benzocaine", "Lidocaine 2%", "Cocaine 4-10%", "Proparacaine 0.5%"], "correct": 2, "explanation": "Cocaine 4-10% is used to diagnose Horner''s syndrome (it fails to dilate the sympathetically denervated pupil)."}'),
  ('cf59deb9-1j','{"options": ["Weaker than procaine and less toxic", "About 10x more potent than cocaine and 10x more toxic than procaine", "Non-toxic", "Equal to lidocaine"], "correct": 1, "explanation": "Tetracaine is roughly 10x more potent than cocaine and 10x more toxic than procaine, used for surface anesthesia only."}'),
  ('464266d6-3h','{"options": ["More resting bradycardia", "Bronchospasm", "Less resting bradycardia and less rebound hypertension on withdrawal", "Corneal damage"], "correct": 2, "explanation": "ISA (partial agonist) beta-blockers cause less resting bradycardia, fewer adverse lipid effects, and less rebound hypertension on withdrawal."}'),
  ('47b791c9-1d','{"options": ["Propranolol", "Metoprolol", "Betaxolol", "Atenolol"], "correct": 0, "explanation": "Propranolol is the prototype non-selective beta-blocker. Practolol was the first cardioselective agent."}'),
  ('eff120b4-2c','{"options": ["Class III", "Class I", "Class IV", "Class II"], "correct": 0, "explanation": "Class III antiarrhythmics prolong repolarisation and include amiodarone and bretylium. Class I are Na-channel blockers, class II beta-blockers, class IV calcium channel blockers."}'),
  ('a6bcb079-1s','{"options": ["Prolonging repolarisation", "Blocking sodium channels", "Blocking voltage-gated calcium channels", "Blocking beta receptors"], "correct": 2, "explanation": "Class IV antiarrhythmics block voltage-gated calcium channels; verapamil is more effective for supraventricular arrhythmias."}'),
  ('eb23199c-1u','{"options": ["Antiarrhythmic agents (lidocaine, phenytoin)", "More digitalis", "Potassium administration", "Discontinuing the drug"], "correct": 1, "explanation": "Treatment of digitalis toxicity is to stop the drug, give K+ (and K+-sparing diuretics), and use antiarrhythmics. Giving more digitalis would worsen toxicity."}'),
  ('c1587c0b-2w','{"options": ["Dipyridamole", "Verapamil", "Nitroglycerin", "Aspirin"], "correct": 0, "explanation": "Dipyridamole inhibits adenosine uptake by RBCs (coronary vasodilation) and inhibits platelet aggregation. Aspirin also inhibits platelet aggregation but via COX."}'),
  ('0124ad04-2l','{"options": ["Sodium chloride", "Hyaluronidase", "Epinephrine", "Bicarbonate"], "correct": 1, "explanation": "Hyaluronidase is the spreading factor that enhances the infiltration and dispersion of injected anesthetic, giving a more effective motor block."}'),
  ('b6e0abac-1n','{"options": ["Cocaine", "Marijuana", "Amphetamine", "Methamphetamine"], "correct": 0, "explanation": "Cocaine is detected in urine as its metabolite benzoylecgonine. Methamphetamine''s metabolite is amphetamine."}'),
  ('74ed6bbc-2p','{"options": ["No acid-base change", "Metabolic alkalosis only", "Mixed metabolic acidosis and respiratory alkalosis", "Pure respiratory acidosis"], "correct": 2, "explanation": "Salicylate (aspirin) overdose causes a mixed metabolic acidosis and respiratory alkalosis, with fever and coma; treatment includes sodium bicarbonate."}'),
  ('1719d2f7-2d','{"options": ["Echothiophate", "Neostigmine", "Physostigmine", "Pilocarpine"], "correct": 1, "explanation": "Neostigmine is the reversible anticholinesterase used to treat myasthenia gravis and to reverse neuromuscular blockade."}'),
  ('b02857b4-2d','{"options": ["Inhibiting acetylcholinesterase", "Blocking calcium channels", "Depolarising the motor end plate persistently", "Competitively blocking nicotinic (NM) receptors at the neuromuscular junction"], "correct": 3, "explanation": "Non-depolarising blockers (curare, pancuronium, vecuronium, atracurium) competitively antagonise nicotinic NM receptors. Succinylcholine is the depolarising blocker."}'),
  ('a762124e-2o','{"options": ["Atenolol", "Betaxolol", "Labetalol", "Esmolol"], "correct": 2, "explanation": "Labetalol (and carvedilol) block both alpha-1 and beta receptors, giving vasodilation plus reduced cardiac output, useful in hypertensive emergencies."}'),
  ('0ddacc68-1q','{"options": ["High LDL cholesterol only", "Arrhythmia", "Elevated triglycerides", "Hypertension"], "correct": 2, "explanation": "Fibric acids lower elevated triglycerides (and LDL) by increasing peripheral lipase activity; gemfibrozil can cause cholelithiasis."}'),
  ('12853938-2e','{"options": ["Opioid overdose", "Angle-closure glaucoma", "Fungal infection", "Digitalis intoxication"], "correct": 3, "explanation": "K+-sparing diuretics (spironolactone, amiloride, triamterene) help treat digitalis intoxication and provide modest antihypertensive effect with minimal potassium loss."}'),
  ('0b2af3ec-1y','{"options": ["Nitroprusside", "Diazoxide", "Minoxidil", "Hydralazine"], "correct": 3, "explanation": "Hydralazine, a direct arteriolar vasodilator, is considered safe in pre-eclampsia. Minoxidil is also used as a hair grower."}'),
  ('369c392f-1r','{"options": ["A constant fraction is absorbed", "It applies to oral drugs", "It applies only to IV, intra-arterial, and intracardiac routes where 100% reaches the blood", "It never reaches the systemic circulation"], "correct": 2, "explanation": "Zero-order absorption (100% reaching blood) applies to IV, intra-arterial, and intracardiac routes. All other routes follow first-order kinetics (constant fraction)."}'),
  ('1cfee87a-1m','{"options": ["The Rx symbol", "Directions to the dispenser", "The drug name and strength", "Directions to the patient"], "correct": 3, "explanation": "The signa (Sig.) gives directions to the patient. The superscription is Rx; the inscription is the drug/strength; the subscription directs the dispenser."}'),
  ('63eb8667-21','{"options": ["Naloxone", "Neostigmine", "Pralidoxime", "Physostigmine"], "correct": 3, "explanation": "Physostigmine, a reversible anticholinesterase that crosses into the CNS, is the antidote for atropine poisoning."}'),
  ('e9299e62-2j','{"options": ["Antagonism", "Synergism", "Potentiation", "Addition"], "correct": 2, "explanation": "Potentiation (0+1=2) is when a drug with no effect of its own enhances the effect of another drug."}'),
  ('79cd8d43-1u','{"options": ["Van der Waals", "Ionic", "Hydrogen", "Covalent"], "correct": 0, "explanation": "Van der Waals forces are the weakest but the most common drug-receptor interaction; most drugs contain cationic and anionic groups."}'),
  ('e15888b7-1n','{"options": ["Aldosterone receptor", "Na-Cl cotransporter in the distal tubule", "Na-K-2Cl cotransporter in the loop of Henle", "Carbonic anhydrase"], "correct": 2, "explanation": "Loop diuretics inhibit the Na-K-2Cl cotransporter in the thick ascending loop of Henle, making them potent diuretics though weaker antihypertensives."}'),
  ('7d0d8b31-2b','{"options": ["Tinnitus", "Restlessness and tremor", "Convulsive seizures", "Coma and respiratory failure"], "correct": 3, "explanation": "The late depressive phase of local anesthetic CNS toxicity includes drowsiness, unconsciousness, coma, and respiratory failure, following the early excitatory phase (seizures)."}'),
  ('bd5ef5b4-1h','{"options": ["Benzocaine", "Cocaine or lidocaine", "Tetracaine", "Benoxinate"], "correct": 1, "explanation": "The forced duction test is performed with cocaine or lidocaine anesthesia. Tetracaine is used for ERG; proparacaine/benoxinate for tonometry."}'),
  ('d97238f7-1b','{"options": ["Mydriatic", "Vasopressor to raise blood pressure", "Antiarrhythmic", "Bronchodilator"], "correct": 1, "explanation": "Norepinephrine acts on alpha-1, alpha-2, and beta-1 receptors and is used as a vasopressor to raise blood pressure in shock."}'),
  ('fe145f91-1x','{"options": ["Esmolol", "Betaxolol", "Atenolol", "Metoprolol"], "correct": 0, "explanation": "Esmolol is an ultra-short-acting cardioselective (beta-1) blocker given IV, useful for acute rate control."}'),
  ('b454da66-y','{"options": ["Stimulating beta-1 receptors", "Inhibiting storage and release of norepinephrine", "Blocking calcium channels", "Blocking angiotensin receptors"], "correct": 1, "explanation": "Reserpine is a pre-ganglionic adrenergic blocker that depletes norepinephrine by inhibiting its storage and release."}'),
  ('d68dcd11-1h','{"options": ["a1", "a2", "b2", "M3"], "correct": 0, "explanation": "Alpha-1 (a1) receptors on the iris dilator muscle cause mydriasis (pupil dilation) when activated."}'),
  ('029f2d23-16','{"options": ["Trabecular meshwork", "Anterior uveal vasculature", "Muller''s smooth muscle", "Ciliary process"], "correct": 3, "explanation": "Alpha-1 receptors are found in the trabecular meshwork, anterior uveal vasculature, and Muller''s smooth muscle. The ciliary process is not a primary alpha-1 site."}'),
  ('9637c50a-2b','{"options": ["alpha-1", "beta-2", "alpha-2", "beta-1"], "correct": 0, "explanation": "Alpha-1 receptors act via phospholipase C (PLC), not adenylyl cyclase. Beta receptors stimulate adenylyl cyclase; alpha-2 inhibits it."}'),
  ('5cc4de1c-3d','{"options": ["Autonomic Nervous system", "Somatic Nervous system", "Central Nervous system", "Peripheral Nervous system", "Nervous system"], "correct": 1, "explanation": "The somatic nervous system controls voluntary skeletal muscle movement for locomotion."}'),
  ('ede37d6d-1m','{"options": ["miosis", "cycloplegia", "accomodation", "opening of trabecula"], "correct": 1, "explanation": "M3 muscarinic activation causes miosis, accommodation, and opening of the trabecular meshwork. It produces accommodation, not cycloplegia (which is paralysis of accommodation)."}'),
  ('08df2f4e-1w','{"options": ["Ganglia close to or within the organ innervated", "Ach is the NT for postganglionic neurotransmission", "Ach is the NT at parasympathetic ganglia", "Long unmyelinated postganglionic neurons"], "correct": 3, "explanation": "Cholinergic (parasympathetic) postganglionic neurons are short, not long unmyelinated. The other three are true characteristics."}'),
  ('2c45ffd1-1p','{"options": ["Nervous system", "Central Nervous system", "Peripheral Nervous system", "Somatic Nervous system", "Autonomic Nervous system"], "correct": 2, "explanation": "The peripheral nervous system consists of neurons located outside the brain and spinal cord."}'),
  ('e858267a-3m','{"options": ["I only", "I and II", "III only", "III and IV"], "correct": 2, "explanation": "Beta-2 (b2) receptors stimulate adenylyl cyclase to produce cAMP. Alpha-2 inhibits cAMP; alpha-1 and M3 act via the PLC pathway."}'),
  ('2e37d263-69','{"options": ["IV only", "I and III", "I and II", "III and IV"], "correct": 3, "explanation": "Both beta-1 and beta-2 receptors couple to Gs and stimulate adenylyl cyclase, raising cAMP."}'),
  ('449b1fe9-2y','{"options": ["I, II, IV", "I, III, IV", "I, II, III", "I and II"], "correct": 0, "explanation": "Alpha-1, alpha-2, and muscarinic-3 activation lower IOP. Beta-2 activation increases aqueous production (beta blockers lower IOP), so III is excluded."}'),
  ('a5e283ae-60','{"options": ["I, II, III", "IV only", "II, IV", "I, II"], "correct": 1, "explanation": "The sympathetic NS CAN discharge as a complete unit (mass response), so statement IV is the exception. The other three statements are correct."}'),
  ('9b91ee75-2z','{"options": ["Inhibition of NE release", "Stimulation of EPI release", "Stimulation of NE release", "Inhibition of Ach release"], "correct": 0, "explanation": "Presynaptic alpha-2 receptors provide negative feedback, inhibiting further norepinephrine (NE) release."}'),
  ('8c9d922e-1h','{"options": ["ciliary muscle", "brucke''s muscle", "muller''s muscle", "extraocular muscle"], "correct": 3, "explanation": "Nicotinic receptors are found at the neuromuscular junction of skeletal muscle, including the extraocular muscles."}'),
  ('e9c19224-17','{"options": ["Somatic Nervous system", "Central Nervous system", "Autonomic Nervous system", "Peripheral Nervous system", "Nervous system"], "correct": 1, "explanation": "The central nervous system is composed of the brain and spinal cord."}'),
  ('b4c32565-34','{"options": ["Central Nervous system", "Nervous system", "Autonomic Nervous system", "Peripheral Nervous system", "Somatic Nervous system"], "correct": 2, "explanation": "The autonomic nervous system regulates involuntary vital functions without conscious control."}'),
  ('5c0ec875-2s','{"options": ["Activation of PLC", "Stimulation of guanylyl cyclase", "Stimulation of adenylyl cyclase", "Decrease IP3, DAG"], "correct": 0, "explanation": "M1/M3 muscarinic receptors couple to Gq, activating phospholipase C (PLC) to increase IP3 and DAG."}'),
  ('c12f86a4-4l','{"options": ["prednisolone", "cortisone", "dexamethasone", "budesonide"], "correct": 3, "explanation": "Budesonide has high airway retention but is rapidly cleared systemically (high first-pass metabolism), minimizing systemic toxicity."}'),
  ('27ac4d4e-14','{"options": ["Inflammation", "Inhibit collagen activity", "Blepharoptosis", "Mydriasis"], "correct": 0, "explanation": "Glucocorticoids suppress inflammation rather than cause it. They can inhibit collagen activity, cause blepharoptosis, and mydriasis."}'),
  ('dc993add-3a','{"options": ["naproxen", "mefenamic acid", "aspirin", "celecoxib"], "correct": 3, "explanation": "Celecoxib is a selective COX-2 inhibitor, sparing the GI tract (less PUD) but increasing cardiovascular/thrombotic risk."}'),
  ('5992ff22-1e','{"options": ["peptic ulcer", "fluid retention", "tinnitus"], "correct": 0, "explanation": "Chronic NSAID use most importantly causes peptic ulcer disease from COX-1 inhibition of protective gastric prostaglandins."}'),
  ('8335b085-1a','{"options": ["cetirizine", "diphenhydramine", "meclizine", "fexofenadine"], "correct": 3, "explanation": "Fexofenadine is a non-sedating second-generation antihistamine that does not penetrate the CNS, making it suitable for pilots."}'),
  ('5c7b621d-2n','{"options": ["COX-3", "COX-2", "COX-1", "COX-4"], "correct": 1, "explanation": "COX-2 is the inducible isoform expressed in inflammatory cells during inflammation."}'),
  ('7590828c-3x','{"options": ["PGE1", "PGF2a", "TXA2", "PGE2"], "correct": 3, "explanation": "PGE2 maintains ductus arteriosus patency in the fetus and ripens the cervix at term."}'),
  ('6a362d88-20','{"options": ["aspirin", "mefenamic acid", "ibuprofen", "celecoxib"], "correct": 0, "explanation": "Aspirin irreversibly acetylates both COX-1 and COX-2 (nonselective); other NSAIDs are reversible inhibitors."}'),
  ('0bc45e11-25','{"options": ["II and IV", "II and III", "I and II", "I and III"], "correct": 0, "explanation": "COX-1 is constitutive (always present) and performs housekeeping functions such as gastric protection. COX-2 is the inducible, inflammation-causing isoform."}'),
  ('06fe3f04-2p','{"options": ["diphenhydramine", "cromolyn", "loratadine", "epinephrine"], "correct": 3, "explanation": "Epinephrine physiologically opposes histamine''s effects (vasoconstriction, bronchodilation) and is first-line for anaphylaxis."}'),
  ('9d52667b-35','{"options": ["H4", "H1", "H3", "H2"], "correct": 1, "explanation": "H1 receptors mediate allergic responses: vasodilation, increased vascular permeability, and bronchoconstriction."}'),
  ('1562975e-22','{"options": ["antiplatelet", "anti-inflammatory", "analgesic", "antipyretic"], "correct": 0, "explanation": "NSAIDs are analgesic, antipyretic, and anti-inflammatory. Only aspirin has a clinically significant irreversible antiplatelet effect, so antiplatelet is not common to all NSAIDs."}'),
  ('387940f5-1x','{"options": ["mineralocorticoid", "cathecolamines", "CRH", "glucocorticoids"], "correct": 3, "explanation": "The zona fasciculata secretes glucocorticoids (cortisol). The zona glomerulosa makes mineralocorticoids; the medulla makes catecholamines."}'),
  ('e84ae0ea-3s','{"options": ["indomethacin", "aspirin", "phenylbutazone", "ketorolac"], "correct": 1, "explanation": "Aspirin is linked to Reye''s syndrome (encephalopathy and liver damage) in children with viral illness, so it is avoided in pediatric fever."}'),
  ('6c6e4d43-51','{"options": ["I, II, III and IV", "I and III", "I, II, and IV", "II and IV"], "correct": 0, "explanation": "All four statements are correct: first-gen antihistamines are lipid-soluble, cross the CNS, and sedate; second-gen agents are less lipid-soluble and non-sedating."}'),
  ('d3487da0-2k','{"options": ["aspirin", "ketorolac", "ibuprofen", "nabumetone"], "correct": 3, "explanation": "Nabumetone is a non-acidic ketone prodrug converted in the liver to its active acidic metabolite (6-MNA)."}'),
  ('6c310ab8-1a','{"options": ["cataract", "conjunctival disease", "eyelids diseases", "scleritis"], "correct": 0, "explanation": "Corticosteroids can cause cataract (a side effect), not treat it. They are used for conjunctival disease, eyelid disease, and scleritis."}'),
  ('8a6c87c7-2n','{"options": ["topical", "intravitreal", "periocular", "systemic"], "correct": 0, "explanation": "Topical drops penetrate poorly to the posterior segment. Intravitreal, periocular, and systemic routes are used for posterior segment disease."}'),
  ('7cba8c1c-4h','{"options": ["phenylbutazone", "aspirin", "indomethacin", "ketorolac"], "correct": 3, "explanation": "Ketorolac is a potent analgesic NSAID limited to short-term use (up to ~5 days; parenteral often 72 h) due to GI and renal toxicity."}'),
  ('d63babfe-1q','{"options": ["PGF2a", "TXA2", "PGE2", "PGI2"], "correct": 0, "explanation": "PGF2-alpha (and its analogs like latanoprost) lowers IOP by increasing uveoscleral outflow."}'),
  ('2efb4f83-z','{"options": ["inhibiting LOX", "inhibiting COX", "inhibiting PLA2", "inhibiting LT receptors"], "correct": 3, "explanation": "Montelukast and zafirlukast are leukotriene (LT) receptor antagonists used in asthma."}'),
  ('2a0c8c6d-1o','{"options": ["nephrotoxicity", "hepatotoxicity", "peptic ulcer", "cardiotoxicity"], "correct": 1, "explanation": "Paracetamol (acetaminophen) overdose causes dose-dependent hepatotoxicity via the toxic metabolite NAPQI."}'),
  ('b1c2578b-28','{"options": ["piperazines", "alkylamines", "ethanolamines", "phenothiazines"], "correct": 2, "explanation": "Ethanolamines (e.g., diphenhydramine) are the most sedating first-generation antihistamines and have strong anticholinergic effects."}'),
  ('9232fb75-3q','{"options": ["PLA2", "LT receptor", "COX", "LOX"], "correct": 0, "explanation": "Corticosteroids induce lipocortin (annexin A1), which inhibits phospholipase A2 (PLA2), blocking arachidonic acid release."}'),
  ('ac940e31-38','{"options": ["II and IV", "I and III", "II and III", "I and II"], "correct": 0, "explanation": "Paracetamol is analgesic and antipyretic but has weak anti-inflammatory action and is not classified as a true NSAID."}'),
  ('1bb329cf-1y','{"options": ["cardioselective", "depressant effect on the heart", "vasoselective", "includes verapamil and diltiazem"], "correct": 2, "explanation": "Non-dihydropyridines (verapamil, diltiazem) are cardioselective and depress the heart. They are not vasoselective; the dihydropyridines (amlodipine, nifedipine) are the vasoselective group."}'),
  ('38a4b6c0-2b','{"options": ["Diazoxide", "Hydralazine", "Sodium nitroprusside", "Minoxidil"], "correct": 2, "explanation": "Sodium nitroprusside is metabolized to cyanide, which can accumulate and cause toxicity, especially with prolonged infusion."}'),
  ('b26a3169-2w','{"options": ["ACE inhibitors", "Diuretics", "B blockers", "Calcium channel blockers"], "correct": 0, "explanation": "ACE inhibitors reduce intraglomerular pressure and proteinuria, making them renoprotective in chronic kidney disease."}'),
  ('936561f7-1l','{"options": ["Elevation of IP3, therefore, relaxing the vascular smooth muscle", "Elevation of cAMP, therefore, relaxing the vascular smooth muscle", "Elevation of cGMP, therefore, relaxing the vascular smooth muscle"], "correct": 2, "explanation": "Nitric oxide activates guanylyl cyclase, raising cGMP, which relaxes vascular smooth muscle."}'),
  ('4ae75d2b-2i','{"options": ["Aquaretics", "Diuretics", "Cholinergics", "Natriuretics"], "correct": 3, "explanation": "Natriuretics increase urine volume specifically by increasing sodium excretion. Aquaretics increase water excretion without sodium loss."}'),
  ('51c11e4a-4n','{"options": ["Propranolol", "Verapamil", "Losartan", "Sodium nitroprusside"], "correct": 0, "explanation": "Propranolol is a non-selective beta blocker; blocking beta-2 receptors causes bronchoconstriction, worsening asthma."}'),
  ('ce358b8d-61','{"options": ["Minoxidil", "Hydralazine", "Bepridil", "Sodium nitroprusside"], "correct": 0, "explanation": "Minoxidil causes reflex tachycardia, fluid retention (edema), and hypertrichosis (increased hair growth)."}'),
  ('be6319af-30','{"options": ["Lupus-like side effect", "Hypertrichosis", "Reflex tachycardia", "Glucose intolerance"], "correct": 2, "explanation": "All three are arteriolar vasodilators, so they share reflex tachycardia (baroreceptor-mediated). The other effects are drug-specific."}'),
  ('c6529ae0-5o','{"options": ["Metoprolol", "Captopril", "Nifedipine", "Losartan"], "correct": 3, "explanation": "Losartan is an angiotensin II receptor blocker (ARB), directly antagonizing the AT1 receptor. Captopril inhibits the enzyme, not the receptor."}'),
  ('9ac3980e-1y','{"options": ["Mannitol", "Furosemide", "HCTZ", "Vasopressin"], "correct": 0, "explanation": "Mannitol is an osmotic diuretic that draws fluid out of tissues, lowering both intracranial and intraocular pressure."}'),
  ('d852c09f-25','{"options": ["Felodipine", "Verapamil", "Amlodipine", "Nifedipine"], "correct": 1, "explanation": "Verapamil (a non-dihydropyridine) preferentially blocks cardiac L-type calcium channels, affecting rate and conduction."}'),
  ('fa2f23f2-1v','{"options": ["Sodium Nitroprusside", "Hydralazine", "Minoxidil", "Diazoxide"], "correct": 0, "explanation": "Sodium nitroprusside dilates both arterioles and veins (mixed). Hydralazine, minoxidil, and diazoxide are pure arteriolar dilators."}'),
  ('a743dc50-2k','{"options": ["Diazoxide", "Nitrates", "Minoxidil", "Hydralazine"], "correct": 0, "explanation": "Diazoxide opens K-ATP channels in pancreatic beta cells, inhibiting insulin release and causing hyperglycemia."}'),
  ('d65687c2-q','{"options": ["Loop diuretics", "Potassium-sparing diuretics", "Thiazide diuretics", "Osmotic diuretics"], "correct": 0, "explanation": "Loop diuretics are called high-ceiling because they produce the greatest diuresis (up to ~25% of filtered sodium)."}'),
  ('930b9635-1v','{"options": ["Hyperlipidemia", "Hyperuricemia", "Hyperglycemia", "Hypocalcemia"], "correct": 3, "explanation": "Thiazides cause hyperCALCEMIA (they increase calcium reabsorption), not hypocalcemia. They do cause hyperlipidemia, hyperuricemia, and hyperglycemia."}'),
  ('ac5a6366-2k','{"options": ["Methyldopa", "Captopril", "Losartan", "Furosemide"], "correct": 0, "explanation": "Methyldopa is the classic safe antihypertensive in pregnancy. ACE inhibitors and ARBs are teratogenic and contraindicated."}'),
  ('c0ff08af-1g','{"options": ["ARBs", "B-blockers", "ACE inhibitors", "CCBs"], "correct": 2, "explanation": "ACE inhibitors cause dry cough due to bradykinin accumulation. ARBs do not, and are used as an alternative."}'),
  ('0ea99cfc-x','{"options": ["BP = CO - SVR", "BP = CO + SVR", "BP = CO x SVR", "BP = CO/SVR"], "correct": 2, "explanation": "Blood pressure equals cardiac output multiplied by systemic vascular resistance (BP = CO x SVR)."}'),
  ('9b17271e-1c','{"options": ["Bradycardia", "Lupus like syndrome", "Atherosclerosis", "Hyperglycemia"], "correct": 1, "explanation": "Hydralazine can cause a drug-induced lupus-like syndrome, especially in slow acetylators."}'),
  ('116c5676-2e','{"options": ["Minimize bicarbonaturia", "Reduce risk of hypokalemia", "Minimize hyperglycemia", "Reduce risk of renal stone formation"], "correct": 1, "explanation": "Thiazides cause potassium loss; adding potassium-sparing spironolactone offsets this and reduces the risk of hypokalemia."}'),
  ('d2b5a3be-27','{"options": ["Diazoxide", "Sodium nitroprusside", "Hydralazine", "Minoxidil"], "correct": 2, "explanation": "IV hydralazine is a first-line vasodilator for hypertensive emergencies in pregnancy. Nitroprusside risks fetal cyanide toxicity."}'),
  ('c9f58a67-1c','{"options": ["NRTI", "NNRTI", "PI", "II"], "correct": 0, "explanation": "Emtricitabine is a nucleoside reverse transcriptase inhibitor (NRTI) used in HIV therapy."}'),
  ('5cd2dad8-1y','{"options": ["Fluconazole", "Ketoconazole", "Voriconazole", "Itraconazole"], "correct": 2, "explanation": "Voriconazole is first-line for invasive aspergillosis."}'),
  ('69e367da-29','{"options": ["Voriconazole", "Caspofungin", "Flucytosine", "Amphotericin B"], "correct": 3, "explanation": "Amphotericin B is the broad-spectrum agent reserved for severe, life-threatening systemic fungal infections."}'),
  ('5d4065cb-1p','{"options": ["Pyrimethamine", "Clindamycin", "Steroids", "Ciprofloxacin"], "correct": 3, "explanation": "Toxoplasmosis is treated with pyrimethamine, clindamycin, and steroids (for inflammation). Ciprofloxacin is an antibacterial with no antiprotozoal role here."}'),
  ('20807419-1a','{"options": ["Erythromycin", "Gentamicin", "Ciprofloxacin", "Polymyxin B"], "correct": 0, "explanation": "Erythromycin 0.5% ophthalmic ointment is the standard prophylaxis for ophthalmia neonatorum."}'),
  ('3c298f14-23','{"options": ["Trifluridine", "Acyclovir", "Famciclovir", "Valacyclovir"], "correct": 0, "explanation": "Trifluridine is a topical ophthalmic antiviral for herpes simplex keratitis and keratoconjunctivitis."}'),
  ('e681d97a-42','{"options": ["Staphylococcus aureus", "Bacillus subtilis", "Streptococcus pneumoniae", "Pseudomonas aeruginosa"], "correct": 3, "explanation": "Piperacillin (an antipseudomonal penicillin) is notable for activity against Pseudomonas aeruginosa."}'),
  ('2148acea-2y','{"options": ["Carboxypenicillin", "Isoxazolylpenicillin", "Aminopenicillin", "Ureidopenicillin"], "correct": 1, "explanation": "MRSA is resistant to the isoxazolyl (antistaphylococcal) penicillins such as methicillin, oxacillin, and cloxacillin."}'),
  ('3654c732-1n','{"options": ["Decarboxylation of the phospholipid that carries the peptidoglycan subunit", "Dephosphorylation of the phospholipid that carries the peptidoglycan subunit", "Phosphorylation of the phospholipid that carries the peptidoglycan subunit", "Carboxylation of the phospholipid that carries the peptidoglycan subunit"], "correct": 1, "explanation": "Bacitracin blocks dephosphorylation of the lipid carrier (bactoprenol pyrophosphate), halting cell wall synthesis."}'),
  ('f6d1533c-14','{"options": ["Gentamicin", "Azithromycin", "Chloramphenicol", "Linezolid"], "correct": 0, "explanation": "Gentamicin (an aminoglycoside) acts on the 30S subunit. Azithromycin, chloramphenicol, and linezolid act on the 50S subunit."}'),
  ('d6283d46-1i','{"options": ["Doxycycline", "Chlortetracycline", "Minocycline", "Demeclocycline"], "correct": 0, "explanation": "Doxycycline is used for prophylaxis of leptospirosis and malaria."}'),
  ('b96ddffe-38','{"options": ["Chloramphenicol", "Erythromycin", "Clindamycin", "Tetracycline"], "correct": 0, "explanation": "Chloramphenicol binds the 50S subunit and inhibits peptidyltransferase activity."}'),
  ('684fd589-j','{"options": ["Penicillin", "Erythromycin", "Vancomycin", "Streptomycin"], "correct": 1, "explanation": "Erythromycin (a macrolide) is bacteriostatic. Penicillin, vancomycin, and streptomycin are bactericidal."}'),
  ('b6a4f499-s','{"options": ["Doxycycline", "Erythromycin", "Cefalexin", "Chloramphenicol"], "correct": 2, "explanation": "Cefalexin (a cephalosporin) is bactericidal. Doxycycline, erythromycin, and chloramphenicol are bacteriostatic."}'),
  ('33274708-24','{"options": ["Host defense mechanisms, such as phagocytosis, are required to kill the bacteria.", "Inhibit the growth of bacteria but does not kill them.", "Useful in certain infections especially those that are immediately life-threatening.", "Bacteria can grow again when the drug is withdrawn."], "correct": 2, "explanation": "Bacteriostatic drugs rely on host defenses and are not ideal for immediately life-threatening infections; bactericidal drugs are preferred there."}'),
  ('76575b00-18','{"options": ["Tazocin", "Co-trimoxazole", "Sultamicillin", "Co-amoxiclav"], "correct": 1, "explanation": "Co-trimoxazole (trimethoprim + sulfamethoxazole) is the classic example of synergism, sequentially blocking folate synthesis."}'),
  ('efa9a040-56','{"options": ["Jarisch-Herxheimer reaction", "Gray baby syndrome", "Steven-Johnson''s syndrome", "Pseudomembranous colitis"], "correct": 3, "explanation": "Pseudomembranous colitis results from C. difficile overgrowth after normal gut flora is suppressed, classically by clindamycin."}'),
  ('7d7e4521-26','{"options": ["Quinolones", "Rifampicin", "Trimethoprim", "Sulfonamides"], "correct": 0, "explanation": "Quinolones/fluoroquinolones inhibit DNA gyrase (topoisomerase II) and topoisomerase IV, blocking DNA synthesis."}'),
  ('805cbc4c-2y','{"options": ["Ethambutol", "Rifampin", "Pyrazinamide", "Isoniazid"], "correct": 3, "explanation": "Isoniazid increases pyridoxine (vitamin B6) excretion, causing peripheral neuropathy; B6 is co-administered to prevent it."}'),
  ('9547f20d-3b','{"options": ["Steven-Johnson''s syndrome", "Gray baby syndrome", "Red man syndrome", "Pseudomembranous colitis"], "correct": 1, "explanation": "Gray baby syndrome results from chloramphenicol accumulation in neonates who cannot glucuronidate the drug."}'),
  ('976c3884-10','{"options": ["Trimethoprim", "Rifampicin", "Sulfonamides", "Quinolones"], "correct": 2, "explanation": "Sulfonamides inhibit dihydropteroate synthetase in bacterial folate synthesis. Trimethoprim inhibits the later enzyme dihydrofolate reductase."}'),
  ('e0df9be0-12','{"options": ["Ototoxicity", "Cardiotoxicity", "Hepatotoxicity", "Photosensitivity"], "correct": 0, "explanation": "Aminoglycosides are classically ototoxic (and nephrotoxic)."}'),
  ('78f6004a-d','{"options": ["2nd gen CEPH", "1st gen CEPH", "4th gen CEPH", "3rd gen CEPH"], "correct": 0, "explanation": "Cefuroxime is a second-generation cephalosporin."}'),
  ('04ae7359-1s','{"options": ["Nalidixic acid", "Nitrofurantoin", "Ciprofloxacin", "Methenamine"], "correct": 2, "explanation": "Ciprofloxacin is a systemic fluoroquinolone, not a urinary antiseptic. Nalidixic acid, nitrofurantoin, and methenamine act as urinary antiseptics."}'),
  ('40bf39e0-2b','{"options": ["Pyrazinamide", "Isoniazid", "Rifampicin", "Ethambutol"], "correct": 2, "explanation": "Rifampicin causes harmless orange-red discoloration of body fluids and can stain soft contact lenses."}'),
  ('00c8cfc3-1z','{"options": ["Pyrazinamide", "Isoniazid", "Ethambutol", "Rifampicin"], "correct": 2, "explanation": "Ethambutol can cause dose-related optic neuritis with loss of visual acuity and red-green color vision."}'),
  ('d82f52bb-27','{"options": ["Clarithromycin", "Roxithromycin", "Azithromycin", "Erythromycin"], "correct": 2, "explanation": "Azithromycin has a long half-life allowing once-daily dosing for a short 3-day course."}'),
  ('a1d50202-3k','{"options": ["Azithromycin", "Clarithromycin", "Roxithromycin", "Erythromycin"], "correct": 3, "explanation": "Erythromycin is the classic macrolide alternative for penicillin-allergic patients."}'),
  ('7b71214f-1z','{"options": ["Ethambutol", "Isoniazid", "Pyrazinamide", "Streptomycin", "Rifampicin"], "correct": 3, "explanation": "Streptomycin is the aminoglycoside with anti-tuberculous activity (a second-line anti-TB agent)."}'),
  ('613e046b-4r','{"options": ["Famciclovir", "Acyclovir", "Ganciclovir", "Trifluridine"], "correct": 1, "explanation": "Acyclovir is selectively activated in infected cells and strongly inhibits viral DNA polymerase, giving low host toxicity and oral/IV use."}'),
  ('e033315f-4n','{"options": ["Amphotericin B", "Natamycin", "Miconazole", "Fluconazole"], "correct": 0, "explanation": "Amphotericin B can be given topically, intravitreally/intraocularly, and intravenously for fungal infections."}'),
  ('b903838f-2b','{"options": ["Toxoplasmosis", "Acanthamoeba", "Herpes simplex virus", "Bacterial conjunctivitis"], "correct": 1, "explanation": "PHMB is a first-line agent for Acanthamoeba keratitis."}'),
  ('9e902e80-35','{"options": ["Rectal", "Topical", "Peroral", "Parenteral"], "correct": 1, "explanation": "Polymyxin B is given topically (as in combination eye preparations) because systemic use is nephro- and neurotoxic."}'),
  ('b04e1a6c-3u','{"options": ["Macrolides", "Aminoglycosides", "Lincosamides", "Tetracyclines"], "correct": 3, "explanation": "Tetracyclines chelate calcium and deposit in developing teeth and bone, causing permanent discoloration; avoided in pregnancy and young children."}'),
  ('693c87d9-3l','{"options": ["Amoxicillin", "Clindamycin", "Ciprofloxacin", "Cefalexin"], "correct": 1, "explanation": "Clindamycin is active against anaerobes and used topically/systemically for acne vulgaris."}'),
  ('93d3a56f-4p','{"options": ["Streptogramins", "Linezolid", "Pleuromutilins", "Colistin"], "correct": 1, "explanation": "Linezolid binds the 23S rRNA of the 50S subunit and is used against resistant Gram-positives including VRE, VRSE, and VRSA."}'),
  ('70b15f18-20','{"options": ["Chloramphenicol", "Tetracycline", "Levofloxacin", "Vancomycin"], "correct": 3, "explanation": "Vancomycin is the drug of choice for MRSA infections."}'),
  ('bb4ab10c-1j','{"options": ["Meropenem", "Cefixime", "Bacitracin", "Amoxicillin"], "correct": 2, "explanation": "Bacitracin is a cyclic polypeptide, not a beta-lactam. Meropenem, cefixime, and amoxicillin are beta-lactams."}'),
  ('de528a41-42','{"options": ["Cycloserine", "Colistin", "Roxifloxacin", "Bacitracin"], "correct": 1, "explanation": "Colistin (polymyxin E) is reserved as last-line therapy for multidrug-resistant Gram-negative infections."}'),
  ('f193a348-1v','{"options": ["Propofol", "Midazolam", "Ketamine", "Thiopental"], "correct": 2, "explanation": "Ketamine produces dissociative anesthesia (a trance-like cataleptic state) by antagonizing NMDA receptors."}'),
  ('1c092fc8-1v','{"options": ["Methoxyflurane", "Nitrous oxide", "Isoflurane", "Halothane"], "correct": 1, "explanation": "Nitrous oxide has a very high MAC (>100%), meaning it is the least potent inhaled anesthetic and cannot alone produce surgical anesthesia."}'),
  ('fc59b9ae-1q','{"options": ["Bupivacaine", "Procaine", "Tetracaine", "Lidocaine"], "correct": 0, "explanation": "Bupivacaine is a long-acting amide local anesthetic. Procaine is short-acting; lidocaine is intermediate."}'),
  ('82553fc5-14','{"options": ["Zinc sulfate", "Borate", "Naphazoline", "Phenylephrine"], "correct": 1, "explanation": "Borate (boric acid) solution is an OTC agent used for eyelid hygiene and as a mild eye wash."}'),
  ('8826f4c3-41','{"options": ["Tetracaine", "Benoxinate", "Proparacaine", "Cocaine"], "correct": 2, "explanation": "Proparacaine is the preferred topical ocular anesthetic because it causes the least irritation and has a low allergy rate."}'),
  ('4a874294-28','{"options": ["Analgesia", "Excitement", "Surgical anesthesia", "Medullary paralysis"], "correct": 3, "explanation": "Medullary paralysis (stage IV) depresses the respiratory and vasomotor centers and can be fatal; it is an anesthetic overdose state to be avoided."}'),
  ('c76bad9e-32','{"options": ["Lidocaine", "Cocaine", "Proparacaine", "Benoxinate"], "correct": 3, "explanation": "Benoxinate (oxybuprocaine) has intrinsic antibacterial activity against common ocular pathogens."}'),
  ('770f8498-13','{"options": ["Cl channels", "Na channels", "Ca channels", "K channels"], "correct": 1, "explanation": "Local anesthetics block voltage-gated sodium (Na) channels, preventing nerve impulse conduction."}'),
  ('4b3e0e5f-1s','{"options": ["General anesthesia", "Anti-inflammatory", "Analgesia", "Local anesthesia"], "correct": 0, "explanation": "General anesthesia produces loss of pain perception together with loss of consciousness. Local anesthesia blocks pain in one area without loss of consciousness."}'),
  ('5ed2f1d6-25','{"options": ["Benoxinate", "Tetracaine", "Proparacaine", "Cocaine"], "correct": 0, "explanation": "Benoxinate is commonly used topically at 0.4% concentration."}'),
  ('2fdfdfdc-15','{"options": ["Slow onset", "Allergic reaction is common", "Rapid metabolism", "Longer acting"], "correct": 3, "explanation": "Ester local anesthetics are generally shorter acting (rapidly hydrolyzed by plasma esterases), so ''longer acting'' is the exception."}'),
  ('3b3c8b88-24','{"options": ["Proparacaine", "Benoxinate", "Tetracaine", "Cocaine"], "correct": 3, "explanation": "Topical cocaine is used in the diagnostic test for Horner''s syndrome; it fails to dilate the affected pupil due to absent norepinephrine release."}'),
  ('fc92e9a5-1k','{"options": ["GABA", "Norepinephrine", "Acetylcholine", "Glutamate"], "correct": 0, "explanation": "Most general anesthetics enhance inhibitory GABA-A receptor activity, depressing CNS function."}'),
  ('9275f2c1-18','{"options": ["Methylcellulose", "Carbopol", "Polyvinyl alcohol", "Hydroxymethylcellulose"], "correct": 1, "explanation": "Per this item, carbopol is identified as not a standard artificial tear component; methylcellulose, polyvinyl alcohol, and hydroxymethylcellulose are common demulcents."}'),
  ('c6a08211-1t','{"options": ["Low systemic toxicity", "Short duration", "Cheap", "Stable"], "correct": 1, "explanation": "An ideal local anesthetic should have an adequate/long enough duration of action, not a short duration; the other traits are desirable."}'),
  ('cd413e9f-1b','{"options": ["No renal side effect", "No cardiovascular side effect", "Poor recovery", "No residual effects"], "correct": 2, "explanation": "Local anesthesia offers rapid, good recovery. ''Poor recovery'' is not an advantage; it is the opposite."}'),
  ('571423e1-1n','{"options": ["Cocaine", "Benoxinate", "Lidocaine", "Proparacaine"], "correct": 1, "explanation": "Benoxinate is commonly used as the topical anesthetic for gonioscopy."}'),
  ('1b28e237-1i','{"options": ["Spinal", "Epidural", "Peripheral", "Transdermal"], "correct": 1, "explanation": "Epidural anesthesia is commonly employed for caesarean delivery, allowing the mother to remain awake with a controllable block."}'),
  ('348358f8-1j','{"options": ["Etidocaine", "Lidocaine", "Benzocaine", "Bupivacaine"], "correct": 2, "explanation": "Benzocaine is an ester local anesthetic. Etidocaine, lidocaine, and bupivacaine are amides (their names contain two ''i''s)."}'),
  ('cb8a6147-2t','{"options": ["Benzocaine", "Bupivacaine", "Cocaine", "Lidocaine"], "correct": 3, "explanation": "Lidocaine is often combined with a vasoconstrictor (epinephrine) to prolong its action and reduce systemic absorption. Cocaine is itself a vasoconstrictor."}'),
  ('63da1263-3x','{"options": ["Less", "Highest", "Least", "More"], "correct": 2, "explanation": "Unmyelinated fibers require the least amount of anesthetic to block conduction because there is no myelin barrier and no need to cover nodes of Ranvier."}'),
  ('def7f25e-1q','{"options": ["Zinc Sulfate", "Naphazoline", "Phenylephrine", "Oxymetazoline"], "correct": 0, "explanation": "Zinc sulfate is an astringent, not a vasoconstrictor. Naphazoline, phenylephrine, and oxymetazoline are decongestant vasoconstrictors."}'),
  ('7fd4462e-1i','{"options": ["Muscle contraction", "Analgesia", "Amnesia", "Sedation"], "correct": 0, "explanation": "Anesthesia aims for muscle relaxation, not muscle contraction. Analgesia, amnesia, and sedation are intended benefits."}'),
  ('cf6c52b4-1i','{"options": ["Ketamine", "Fentanyl", "Droperidol", "Laughing gas"], "correct": 0, "explanation": "Neuroleptanesthesia classically combines an opioid (fentanyl), a neuroleptic (droperidol), and nitrous oxide (laughing gas). Ketamine is not a component."}'),
  ('61706de1-2h','{"options": ["Allergy", "Stinging", "Corneal edema", "Vasodilation"], "correct": 1, "explanation": "Transient stinging or burning on instillation is the most common side effect of topical ocular anesthetics."}'),
  ('85910509-35','{"options": ["Less than 5° from fixation", "Less than 20° from fixation", "Less than 10° from fixation", "20° in the widest meridian"], "correct": 2, "explanation": "WHO blindness uses a visual field less than 10° from fixation (with VA 20/200 or worse). WHO low vision uses less than 20°, and legal blindness uses 20° or less in the widest meridian."}'),
  ('88fc989f-32','{"options": ["Less than 20° from fixation", "Of exactly 20°", "Greater than 30°", "Less than 10° from fixation"], "correct": 0, "explanation": "WHO low vision is VA worse than 20/70 with a field less than 20° from fixation. The 10° cutoff belongs to WHO blindness."}'),
  ('6ad51ed9-2o','{"options": ["20° or less in the widest meridian of the better eye", "Less than 10° from fixation", "40° or less", "Less than 30°"], "correct": 0, "explanation": "Legal blindness uses a visual field of 20° or less in the widest meridian of the better eye (correction including contact lenses), or VA 20/200 or less. Note it uses the widest meridian, unlike the WHO field cutoffs measured from fixation."}'),
  ('67c586e5-2b','{"options": ["WHO low vision and WHO blindness", "ICD-11 mild and moderate", "WHO low vision and legal blindness", "WHO blindness and legal blindness"], "correct": 3, "explanation": "Both WHO blindness and legal blindness use the 20/200 acuity threshold. WHO low vision instead uses worse than 20/70."}'),
  ('e3f600ab-1w','{"options": ["Is limited to a visual field defect", "Is always congenital", "Cannot be fully remediated by conventional spectacles, contact lenses, or medical intervention and restricts everyday life", "Always progresses to blindness"], "correct": 2, "explanation": "The functional definition centres on impairment of visual function that conventional correction or medical treatment cannot fully remedy and that restricts the person''s daily life. It is task- and function-based, not a single acuity number."}'),
  ('7346eccd-22','{"options": ["Worse than 20/60 to 20/200", "Worse than 20/200 to 20/400", "20/25 to 20/40", "20/40 (6/12) to 20/60 (6/18)"], "correct": 3, "explanation": "ICD-11 mild impairment is 20/40 (6/12) to 20/60 (6/18). Moderate is worse than 20/60 to 20/200; severe is worse than 20/200 to 20/400; blindness is worse than 20/400."}'),
  ('2a710691-1u','{"options": ["Moderate", "Blindness", "Severe", "Mild"], "correct": 2, "explanation": "Severe impairment is worse than 20/200 (6/60) to 20/400 (3/60); 20/300 lies in this band. Moderate stops at 20/200 and blindness begins worse than 20/400."}'),
  ('4bbb58d4-1u','{"options": ["M1.0 at 40 cm", "N6 or M.08 at 40 cm", "N8 at 33 cm", "N12 at 25 cm"], "correct": 1, "explanation": "ICD-11 defines near vision impairment as near VA worse than N6 or M.08 at 40 cm."}'),
  ('a8e0a88b-2q','{"options": ["Congenital", "Due to cataract", "Acquired in adulthood", "Due to trauma"], "correct": 0, "explanation": "Habilitation applies to congenital loss (developing skills never had). Rehabilitation applies to acquired loss (restoring previously present skills)."}'),
  ('529e3bc1-3l','{"options": ["Visual disability", "Visual disorder", "Visual handicap", "Visual impairment"], "correct": 2, "explanation": "Visual handicap refers to the psychosocial and economic consequences. A visual disorder is the anatomical change; disability is the change in measurable skills; handicap is the resulting life impact."}'),
  ('ad21fa05-10','{"options": ["A refractive error only", "A change in the person''s measurable skills", "An anatomical change in the visual organs", "The economic impact of vision loss"], "correct": 2, "explanation": "A visual disorder gives rise to anatomical changes in the visual organs (e.g., early glaucoma), which may be unnoticed. It can cause functional loss, then disability, then handicap."}'),
  ('04c44c31-25','{"options": ["Age-related macular degeneration", "Uncorrected refractive error", "Glaucoma", "Cataract"], "correct": 1, "explanation": "Uncorrected refractive error is the leading cause of visual impairment worldwide. Cataract is the leading cause of blindness in low- and middle-income countries."}'),
  ('d6cbeba8-1p','{"options": ["Corneal opacity (0.9%)", "Glaucoma (5.8%)", "Refractive error (19.7%)", "Cataract (62.6%)"], "correct": 3, "explanation": "In the over-50 group cataract accounts for about 62.6% of blindness, far ahead of refractive error (19.7%) and glaucoma (5.8%)."}'),
  ('57e2a009-1r','{"options": ["Congenital eye anomalies", "Vitamin A deficiency", "Refractive error", "Retinal degeneration"], "correct": 2, "explanation": "In children refractive error leads at about 33.3%, followed by congenital eye anomalies (25%), retinal degeneration (16.7%), and vitamin A deficiency (8.3%)."}'),
  ('683088a5-2o','{"options": ["246 million", "5 million", "100 million", "39 million"], "correct": 3, "explanation": "Of 285 million visually impaired people, about 39 million are blind and 246 million have low vision. Roughly 80% of blindness is considered avoidable."}'),
  ('912ecf04-1f','{"options": ["Protanomaly", "Deuteranomaly", "Tritanomaly", "Tritanopia"], "correct": 1, "explanation": "Deuteranomaly (green-weak, reduced M-cone sensitivity) is the most common colour vision deficiency, an X-linked trait affecting about 5% of white males."}'),
  ('3a2f29c0-w','{"options": ["Blue-weakness", "Total colour blindness", "Green-weakness", "Red-weakness"], "correct": 3, "explanation": "Protanomaly is red-weakness: the L (red) cone has reduced sensitivity, so reds look weaker and orange, yellow, and yellow-green appear paler."}'),
  ('f9cf1b22-1i','{"options": ["Deuteranomaly", "Protanopia", "Deuteranopia", "Tritanopia"], "correct": 2, "explanation": "Absence of green (M) cone function is deuteranopia, a dichromacy. Deuteranomaly is only reduced M-cone sensitivity, not absence."}'),
  ('045ff9ac-1m','{"options": ["Deuteranomaly", "Protanopia", "Tritanopia", "Deuteranopia"], "correct": 2, "explanation": "Tritanopia (absent S/blue cones) is the rarest dichromacy, roughly 10 per million, and causes yellow-blue confusion. Protanopia is the most common dichromacy."}'),
  ('b46da293-1k','{"options": ["Rod", "Green (M)", "Blue (S)", "Red (L)"], "correct": 2, "explanation": "Tritanomaly is blue-weakness from reduced S (blue) cone sensitivity. It is very rare (< 0.01%)."}'),
  ('ae16955b-2f','{"options": ["Reduced visual acuity", "Hemeralopia and a central scotoma", "Nystagmus", "Preserved normal visual acuity"], "correct": 3, "explanation": "Rod monochromacy has reduced VA, nystagmus, hemeralopia (day blindness), and a central scotoma. Preserved normal acuity is a feature of cone monochromacy, the milder incomplete form."}'),
  ('d671457f-2g','{"options": ["Visual acuity remains near normal", "It is sex-linked", "It only affects women", "It causes total blindness"], "correct": 0, "explanation": "In cone monochromacy a single cone type still functions, so visual acuity remains near normal, unlike rod monochromacy where acuity is markedly reduced."}'),
  ('47fa2f65-18','{"options": ["Only achromatopsia", "Only anomalous trichromacy", "Both the anomalous (weak) and dichromatic (absent) forms", "Only dichromacy"], "correct": 2, "explanation": "Protan, Deutan, and Tritan each cover both the anomalous trichromatic (weak) and the dichromatic (absent) versions of that cone defect."}'),
  ('f3f1a847-2u','{"options": ["Anomaloscope", "Ishihara plates", "Farnsworth Lantern (FALANT)", "Farnsworth D-15"], "correct": 0, "explanation": "The anomaloscope is the reference standard: the subject matches a red-green mixture to a standard yellow. Ishihara is a screening plate test; D-15 is an arrangement test; FALANT is a lantern test."}'),
  ('217f25b3-1v','{"options": ["Lantern test", "Pseudoisochromatic plate", "Colour arrangement test", "Anomaloscope"], "correct": 2, "explanation": "The Farnsworth D-15 (dichotomous) and the Lanthony test are colour arrangement tests. Ishihara and HRR are pseudoisochromatic plates; FALANT and Holmes-Wright are lantern tests."}'),
  ('4d569985-1f','{"options": ["Anomaloscope and Ishihara", "Farnsworth Lantern (FALANT) and Holmes-Wright", "D-15 and Lanthony", "Ishihara and HRR"], "correct": 1, "explanation": "FALANT and the Holmes-Wright lantern are lantern tests, often used for occupational screening. Ishihara/HRR are plates; D-15/Lanthony are arrangement tests."}'),
  ('8d0c9f2f-1h','{"options": ["Autosomal dominant", "X-linked and far more common than blue-yellow defects", "Equally common in both sexes", "Only acquired"], "correct": 1, "explanation": "Protan and deutan defects are X-linked, so they are far more common in males and much more common than the rare blue-yellow (tritan) defects."}'),
  ('da9e8d7f-2b','{"options": ["Temporal field", "Nasal field", "Superior field", "Central field"], "correct": 1, "explanation": "The temporal retina maps to the nasal field (and nasal retina to the temporal field), because the optics of the eye invert the field onto the retina."}'),
  ('e25167cf-1m','{"options": ["Arcuate scotoma", "Central scotoma", "Bitemporal hemianopia", "Peripheral constriction"], "correct": 1, "explanation": "Loss of foveal/macular function produces a central scotoma. Peripheral constriction points to retinitis pigmentosa and arcuate defects to glaucoma."}'),
  ('20d131ed-1q','{"options": ["Retinitis pigmentosa", "Glaucoma", "Diabetic or hypertensive retinopathy", "Macular hole"], "correct": 2, "explanation": "Multiple discrete retinal lesions in diabetic or hypertensive retinopathy produce scattered scotomas. A macular hole gives a central scotoma."}'),
  ('2c3105af-n','{"options": ["Doubling of the image", "An area of depressed vision surrounded by a normal field", "Complete loss of the entire field", "A generalised dimming of the whole field"], "correct": 1, "explanation": "A scotoma is an area of depressed or absent vision surrounded by a comparatively normal field. It is classified positive vs negative and absolute vs relative."}'),
  ('6e4e48d3-1y','{"options": ["Point of fixation", "Peripheral rim", "Blind spot", "Nasal step"], "correct": 2, "explanation": "The optic disc, having no photoreceptors, corresponds to the physiological blind spot. The fovea corresponds to the point of fixation."}'),
  ('39941532-28','{"options": ["Pelli-Robson chart", "Tangent screen", "Amsler grid", "Perimeter"], "correct": 0, "explanation": "Amsler grid, tangent screen, perimeter, and confrontation are field tests. The Pelli-Robson chart measures contrast sensitivity, not the visual field."}'),
  ('4ccf5f68-23','{"options": ["Distinguish an object from its background", "Adapt to darkness", "Resolve fine high-contrast detail", "Perceive colour differences"], "correct": 0, "explanation": "Contrast sensitivity is the ability to distinguish an object from its background. Contrast threshold is the smallest contrast needed to see a target."}'),
  ('6187ab1b-16','{"options": ["Visual impairment", "Normal contrast sensitivity (100%)", "Visual disability", "Complete loss"], "correct": 1, "explanation": "A score of 2.0 equals log contrast sensitivity 2, i.e., 100% (normal). Scores below 1.5 indicate impairment and below 1.0 indicate disability."}'),
  ('3d3f5f4e-2q','{"options": ["1.5", "0.5", "2.0", "1.0"], "correct": 3, "explanation": "Below 1.0 represents visual disability; below 1.5 represents visual impairment; 2.0 is normal."}'),
  ('20e4f259-1u','{"options": ["The letter size (a single 20/60 optotype)", "The viewing distance to 6 m", "The illumination only", "The number of colours"], "correct": 0, "explanation": "Pelli-Robson uses a single large letter size (20/60) and varies contrast across letter triples in 0.15 log-unit steps, testing low spatial frequency contrast sensitivity at 1 m."}'),
  ('755237bc-3t','{"options": ["VCTS (Vistech)", "Bailey-Lovie", "Cambridge low-contrast gratings", "Pelli-Robson"], "correct": 0, "explanation": "The Vision Contrast Test System (VCTS/Vistech) uses circular sine-wave gratings across five spatial frequencies and is frequently cited as the gold standard for contrast sensitivity."}'),
  ('c0ef5d7a-21','{"options": ["1 metre", "3 metres", "10 feet", "6 metres"], "correct": 2, "explanation": "Functional Acuity Contrast Testing (FACT) is done at 10 feet, testing five spatial frequencies and nine contrast levels with sine-wave gratings."}'),
  ('397cc987-1u','{"options": ["Adults with cataract", "Glaucoma suspects", "Colour-deficient drivers", "Infants and non-verbal patients using preferential looking"], "correct": 3, "explanation": "Hiding Heidi uses low-contrast face cards (black, 25, 10, 5, 2.5, 1.25%) with preferential looking, suited to infants and others who cannot respond verbally."}'),
  ('41252421-3k','{"options": ["100% and 10%", "90% and 45%", "50% and 25%", "100% and 2%"], "correct": 0, "explanation": "The Bailey-Lovie chart tests VA at 100% (high) and 10% (low) contrast, so it estimates acuity under both bright and dim conditions relevant to night driving."}'),
  ('03021f60-24','{"options": ["Only the middle frequencies", "All frequencies equally", "Lower spatial frequencies (large gratings)", "Higher spatial frequencies (fine detail)"], "correct": 3, "explanation": "Mild refractive error first reduces contrast sensitivity at higher spatial frequencies (fine detail); as the error grows, middle and then lower frequencies are affected."}'),
  ('2fdc392c-28','{"options": ["Optic neuropathy", "Emmetropia with clear media", "Cataract", "Glaucoma"], "correct": 1, "explanation": "Refractive error, age, cataract, contact lenses, refractive surgery, glaucoma, diabetic retinopathy, optic neuropathy, pituitary adenoma, drugs, and toxic chemicals all reduce contrast sensitivity. A healthy emmetropic eye with clear media does not."}'),
  ('d3f8baca-3o','{"options": ["Colour blindness", "A field defect", "Uncorrected astigmatism", "Reduced contrast sensitivity"], "correct": 3, "explanation": "These are classic contrast-sensitivity-related problems (night vision, reading, spotting low-contrast marks). High-contrast Snellen acuity can be normal while real-world low-contrast function is impaired."}'),
  ('4b544d8b-1r','{"options": ["Decimal notation", "Jaeger only", "LogMAR without reference distance", "M-notation"], "correct": 3, "explanation": "M-notation is recommended for recording low vision acuity, and Louise Sloan introduced the M-unit to avoid confusion with D (diopters). LogMAR requires stating the reference distance."}'),
  ('1dd082b3-23','{"options": ["Letter size (cm) / 2.5", "Letter size (mm) x 1.45", "1 / letter size (mm)", "Letter size (mm) / 1.45 mm"], "correct": 3, "explanation": "The M value equals the letter size in mm divided by 1.45 mm, allowing unknown reading material to be recorded in M-notation."}'),
  ('6331cc0d-32','{"options": ["Two", "Three", "Five", "Ten"], "correct": 0, "explanation": "Halving the test distance from 6 m to 3 m doubles the effective range, gaining a factor of two while keeping the same chart."}'),
  ('b5e80185-17','{"options": ["Retinoscopy through a telescope", "Retinoscopy performed off the visual axis", "Retinoscopy under cycloplegia", "Retinoscopy at a shorter working distance, then subtracting the working-distance value from the gross finding"], "correct": 3, "explanation": "Radical retinoscopy shortens the working distance to brighten a dim reflex; the dioptric value of that shorter distance is then subtracted from the gross result."}'),
  ('252ce89f-1p','{"options": ["High astigmatism", "Central cataract, because a brighter reflex is obtained off the line of sight", "Nystagmus only", "Normal media"], "correct": 1, "explanation": "Taking the reflex off the patient''s line of sight (off-axis) can yield a brighter reflex when a central cataract or central corneal scar blocks the axial reflex."}'),
  ('17c29187-2b','{"options": ["It is too fast", "It cannot measure astigmatism", "Poor fixation, eccentric viewing posture, and media opacities make it unreliable; a trial frame with wide-aperture lenses is preferred", "It requires cycloplegia"], "correct": 2, "explanation": "Poor fixation, eccentric viewing, and media opacity undermine the phoropter. A trial frame with wide-aperture trial lenses and the bracketing technique (large power steps) is preferred."}'),
  ('000f9583-33','{"options": ["+20.00 D", "+2.50 D", "+10.00 D", "+5.00 D"], "correct": 2, "explanation": "Kestenbaum: reciprocal of 20/200 is 200/20 = +10.00 D."}'),
  ('c86247af-23','{"options": ["+20.00 D", "+4.00 D", "+40.00 D", "+10.00 D"], "correct": 0, "explanation": "Reciprocal of 20/400 = 400/20 = +20.00 D."}'),
  ('60eb1675-33','{"options": ["+2.50 D", "+5.00 D", "+8.00 D", "+10.00 D"], "correct": 3, "explanation": "200/50 x +2.50 = 4 x 2.50 = +10.00 D. The +2.50 reflects the 40 cm reference working distance."}'),
  ('de3ed586-2c','{"options": ["+6.25 D", "+2.50 D", "+10.00 D", "+4.00 D"], "correct": 2, "explanation": "160/40 x +2.50 = 4 x 2.50 = +10.00 D."}'),
  ('283149a8-2r','{"options": ["+10.00 D", "+2.50 D", "+16.00 D", "+4.00 D"], "correct": 0, "explanation": "0.4/4 = x/1, so x = 0.1 m; D = 1/0.1 = +10.00 D."}'),
  ('cc00b921-2r','{"options": ["+2.50 D", "+20.00 D", "+10.00 D", "+5.00 D"], "correct": 2, "explanation": "0.4/8 = x/2, so x = 0.1 m; D = 1/0.1 = +10.00 D."}'),
  ('550662c6-2f','{"options": ["Starting near visual acuity", "Reciprocal of vision", "Trial-and-error only", "Kestenbaum''s rule"], "correct": 0, "explanation": "The starting-near-acuity method uses near testing distance and near acuity directly, needing no distance VA, and is described as the most accurate of the three."}'),
  ('f29a0ccf-2n','{"options": ["1 line smaller", "Equal to threshold", "5 lines smaller", "3 lines smaller"], "correct": 0, "explanation": "Spot reading needs a 1-line reserve; fluent reading needs 3 lines; maximum reading needs 5 lines smaller than threshold."}'),
  ('acd2b32e-1m','{"options": ["1 line smaller", "3 lines smaller", "No reserve", "5 lines smaller"], "correct": 3, "explanation": "Maximum reading (about 320 wpm) needs a 5-line reserve so text is well above threshold."}'),
  ('1f1303f5-2a','{"options": ["Stronger", "Unchanged", "Weaker", "Always +2.50 D"], "correct": 0, "explanation": "A shorter working distance corresponds to a shorter focal length and therefore a stronger (higher-plus) add, since D = 1/f."}'),
  ('e3656a39-2s','{"options": ["Older hyperopes", "Aphakes", "Young children with high accommodation and myopes", "Pseudophakes"], "correct": 2, "explanation": "Bringing the object closer relies on accommodation or myopia; children with strong accommodation and myopes using unaided vision manage it, while most others need a high plus add."}'),
  ('ef82841d-29','{"options": ["5x", "10x", "2x", "4x"], "correct": 3, "explanation": "40M/10M = 4x."}'),
  ('9d081ede-1p','{"options": ["8x", "2x", "4x", "5x"], "correct": 3, "explanation": "200/40 = 5x."}'),
  ('99035581-2j','{"options": ["6x", "5x", "10x", "2x"], "correct": 1, "explanation": "60/12 = 5x (achieved/goal using the same notation)."}'),
  ('3c29ae3c-1s','{"options": ["Wider, thinner, farther", "Bigger, bolder, brighter", "Darker, dimmer, distant", "Smaller, sharper, closer"], "correct": 1, "explanation": "Magnification aims to make the target BIGGER, BOLDER, and BRIGHTER."}'),
  ('82150e6b-17','{"options": ["S2 / S1", "r / d", "screen image / object", "Fe / Fo"], "correct": 0, "explanation": "RSM = S2/S1, the new object size divided by the original size, achieved by physically enlarging the object (large print)."}'),
  ('e790d3d5-1s','{"options": ["3x", "5x", "15x", "10x"], "correct": 1, "explanation": "RSM = 15/3 = 5x."}'),
  ('3be1c936-1b','{"options": ["Fe / Fo", "r / d", "object / screen image", "S2 / S1"], "correct": 1, "explanation": "RDM = r/d, the reference (original) working distance divided by the new, closer working distance."}'),
  ('1a33e1e2-2g','{"options": ["4x", "2x", "10x", "8x"], "correct": 0, "explanation": "RDM = 40/10 = 4x. Bringing the object closer enlarges the retinal image proportionally."}'),
  ('39a9e2d8-2o','{"options": ["5 cm", "20 cm", "10 cm", "8 cm"], "correct": 0, "explanation": "d = r/RDM = 40/8 = 5 cm."}'),
  ('5032a985-2k','{"options": ["33 cm and +3.00 D", "50 cm and +2.00 D", "25 cm and +4.00 D", "40 cm and +2.50 D"], "correct": 3, "explanation": "Spectacle magnifiers use a 40 cm reference, where 1x = +2.50 D. Hand and stand magnifiers use a 25 cm reference, where 1x = +4.00 D."}'),
  ('8343d4e2-2g','{"options": ["25 cm; +4.00 D", "40 cm; +2.50 D", "10 cm; +10.00 D", "20 cm; +5.00 D"], "correct": 0, "explanation": "Hand and stand magnifiers use a 25 cm reference, so 1x = +4.00 D (the power focusing at 25 cm)."}'),
  ('7f001049-1v','{"options": ["+2.50 D", "+16.00 D", "+10.00 D", "+5.00 D"], "correct": 2, "explanation": "At 40 cm, 1x = +2.50 D, so 4x = 4 x 2.50 = +10.00 D (object at 10 cm)."}'),
  ('00d6bf9a-1v','{"options": ["+20.00 D", "+12.50 D", "+10.00 D", "+16.00 D"], "correct": 3, "explanation": "At 25 cm, 1x = +4.00 D, so 4x = 4 x 4.00 = +16.00 D."}'),
  ('7d4fa17d-1r','{"options": ["Both increase", "Both decrease", "Focal length increases, field decreases", "Focal length decreases, field increases"], "correct": 1, "explanation": "Higher power means a shorter focal length and a smaller field of view (and, for hand magnifiers, more weight and distortion)."}'),
  ('43aeb133-19','{"options": ["Can be brought closer", "Is already at 40 cm", "Can be easily enlarged", "Is too far or too large to move or resize, so a lens system is interposed"], "correct": 3, "explanation": "Angular (optical) magnification interposes a lens system (magnifier or telescope) without moving or resizing the object, for targets too far or too large to change."}'),
  ('1ecbc29d-3a','{"options": ["Galilean telescope", "Closed-circuit television (CCTV)", "Typoscope", "Hand magnifier"], "correct": 1, "explanation": "Projection magnification throws an enlarged image onto a screen; the CCTV is the familiar low-vision example. PM = screen-image size / object size."}'),
  ('8209ad8b-1c','{"options": ["Concave objective, convex eyepiece", "Convex objective, convex eyepiece", "Concave objective, concave eyepiece", "Convex objective, concave eyepiece"], "correct": 3, "explanation": "The Galilean (terrestrial) telescope pairs a convex (+) objective with a concave (-) eyepiece, forming an erect virtual image with no prism needed."}'),
  ('ea3393da-1z','{"options": ["Inverted image; an internal prism re-inverts it", "Erect image; no correction needed", "Virtual erect image; a mirror corrects it", "Real erect image; a minus lens corrects it"], "correct": 0, "explanation": "The Keplerian (astronomical) telescope uses two convex lenses and forms an inverted image, so an internal prism is added to re-invert the view."}'),
  ('82f2cc5a-14','{"options": ["Fo / Fe", "Fe / Fo", "Fo x Fe", "Fo + Fe"], "correct": 1, "explanation": "M = Fe/Fo, the dioptric power of the eyepiece divided by that of the objective."}'),
  ('679d8a29-2e','{"options": ["4x", "0.25x", "6x", "2x"], "correct": 0, "explanation": "M = Fe/Fo = 32/8 = 4x."}'),
  ('6d84b2ff-w','{"options": ["The sum of the focal lengths (in cm) of objective and eyepiece", "The difference of the focal lengths", "The product of the powers", "The eyepiece focal length only"], "correct": 0, "explanation": "Length = f(objective) + f(eyepiece) in cm, with f = 100/D. The sign of the eyepiece focal length determines whether the design is short (Galilean) or long (Keplerian)."}'),
  ('846f3c06-29','{"options": ["10.00 cm", "6.67 cm", "13.33 cm", "3.33 cm"], "correct": 1, "explanation": "f(obj) = 100/10 = 10 cm; f(eye) = 100/-30 = -3.33 cm; length = 10 + (-3.33) = 6.67 cm. The negative eyepiece shortens the tube."}'),
  ('b6f2a608-2a','{"options": ["3.33 cm", "10.00 cm", "6.67 cm", "13.33 cm"], "correct": 3, "explanation": "f(obj) = 10 cm; f(eye) = 100/30 = 3.33 cm; length = 10 + 3.33 = 13.33 cm. Same 3x magnification as the Galilean but physically longer."}'),
  ('3b673546-20','{"options": ["Objective diameter x exit pupil", "Objective diameter / exit pupil diameter", "Exit pupil / objective diameter", "Field of view / magnification"], "correct": 1, "explanation": "M = diameter of the objective lens / diameter of the exit pupil. A 20 mm objective with a 2 mm exit pupil gives 10x."}'),
  ('932e309e-2a','{"options": ["72x", "8x", "3x", "6x"], "correct": 1, "explanation": "M = 24/3 = 8x."}'),
  ('b2801f5a-1i','{"options": ["The field of view", "The objective lens diameter in millimetres", "The eyepiece power", "The magnification"], "correct": 1, "explanation": "In 4 x 12, 12.5°: 4 is magnification, 12 is the objective diameter (mm), and 12.5° is the field of view."}'),
  ('16242d26-1v','{"options": ["Higher magnification and wider field", "Up to 20x magnification", "Inverted images", "A brighter image but a smaller field of view, up to about 4x"], "correct": 3, "explanation": "The Galilean is available up to about 4x, with a brighter image but a smaller field. The Keplerian reaches up to ~20x with a wider field but less light transmission."}'),
  ('4316bbc5-1x','{"options": ["Decreases", "Doubles", "Increases", "Stays the same"], "correct": 0, "explanation": "Magnification and field of view trade off inversely: higher magnification narrows the field of view."}'),
  ('d9c3b312-2z','{"options": ["Stand magnifier", "Spectacle magnifier", "Hand-held telescope", "Hand magnifier"], "correct": 0, "explanation": "A stand magnifier holds the lens at a fixed distance from the page, so no steady grip is needed, ideal for tremor, Parkinson disease, or cerebral palsy."}'),
  ('5e8e5949-1l','{"options": ["Built-in inversion", "A long working distance", "Unlimited binocular high power", "Hands-free use with a wide field, good for prolonged reading"], "correct": 3, "explanation": "Spectacle magnifiers are hands-free, portable, give a wide field, and suit prolonged reading; the trade-off is a fixed, very close working distance, and binocularity fails at high power."}'),
  ('6c3dd0ca-2r','{"options": ["Base-up prism", "No prism", "Base-out prism", "Base-in prism"], "correct": 3, "explanation": "Base-in prism is incorporated so the two eyes can converge comfortably on the near target through low-power binocular spectacle magnifiers."}'),
  ('dcb51fa9-19','{"options": ["Mobility while walking", "Prolonged hands-free reading", "Sustained near work", "Short-term viewing or spotting activities"], "correct": 3, "explanation": "Hand-held telescopes suit brief spotting tasks; for extended or hands-free viewing a spectacle-mounted system is indicated."}'),
  ('ec8ee86e-1r','{"options": ["Wider field of view", "Erecting prism", "A greater working distance while remaining hands-free", "Lower cost"], "correct": 2, "explanation": "The telemicroscope gives a greater working distance than a spectacle magnifier and is hands-free, helping posture; its drawback is a narrow field of view."}'),
  ('0a2e31f7-33','{"options": ["Reverse telescope", "Stand magnifier", "Typoscope", "CCTV"], "correct": 3, "explanation": "A CCTV offers high magnification, zoom, and contrast reversal/enhancement with comfortable posture and possible binocularity, best for prolonged reading despite cost and bulk."}'),
  ('1bf2d380-2h','{"options": ["Refractive error", "Constricted fields, hemianopsias, and scotomas", "Cataract", "Presbyopia"], "correct": 1, "explanation": "Field expanders help relocate or compress a wider field into the seeing area for patients with contracted fields, hemianopsias, and scotomas; they do not magnify."}'),
  ('05b8790a-2m','{"options": ["Natural light", "Fluorescent", "Halogen", "Incandescent bulb"], "correct": 3, "explanation": "Incandescent bulbs are common, directional, and dimmable with a yellowish light, but they run hot and need frequent replacement. Fluorescent scatters light for general illumination."}'),
  ('355ffced-1x','{"options": ["Grey on light blue", "Blue on green", "Black on white", "Yellow on white"], "correct": 2, "explanation": "Black on white gives the highest contrast. Advice is to choose colours differing in saturation and to avoid pairing white or grey with other light colours."}'),
  ('00c1eda3-10','{"options": ["Glare-reduction / reading aid (non-optical)", "Telescope", "Field expander", "Magnifier"], "correct": 0, "explanation": "A typoscope is a non-optical aid (a slit card) used to reduce glare and guide reading. It falls under glare-reduction and contrast/reading aids."}'),
  ('885b705b-16','{"options": ["Bioptic telescopes", "Stand magnifiers", "Yellow filters", "Braille, tactile devices, and talking books"], "correct": 3, "explanation": "Sight substitution replaces vision with other senses: Braille and other tactile devices, and talking books, newspapers, and magazines."}'),
  ('0e38bfaf-3d','{"options": ["1.7x", "5x", "24x", "11x"], "correct": 2, "explanation": "Combined magnification multiplies: 3x x 8x = 24x."}'),
  ('91edcad9-3b','{"options": ["Watching television", "Contrast enhancement", "Mobility needs", "Reading"], "correct": 2, "explanation": "Head-mounted electronic systems help with distance and near tasks but are not currently recommended for mobility needs."}'),
  ('e2b2054f-1u','{"options": ["It requires steady hands", "It cannot be illuminated", "Fixed focus", "It can block the reading light and has a narrow field, and is bulky"], "correct": 3, "explanation": "Stand magnifiers have a narrow field, can block the reading light, and are bulky. Their fixed lens-to-object distance is actually an advantage for unsteady hands."}'),
  ('aa7ab6e8-1k','{"options": ["Neural ectoderm", "Surface ectoderm", "Mesoderm", "Neural crest"], "correct": 1, "explanation": "Surface ectoderm gives rise to the crystalline lens, lacrimal apparatus, Meibomian glands, and glands of Zeis and Moll. Neural ectoderm gives rise to the retina, optic nerve, and pupil muscles."}'),
  ('1b91a869-1d','{"options": ["Roof (frontal bone)", "Medial wall (lamina papyracea)", "Floor (maxilla)", "Lateral wall (sphenoid + zygomatic)"], "correct": 1, "explanation": "The medial wall is the thinnest wall, formed largely by the lamina papyracea (OS planum of ethmoid) which is as thin as paper. The lateral wall is the thickest and strongest. The floor is triangular and the weakest (fractures → enophthalmos)."}'),
  ('acf64767-2y','{"options": ["Adie''s Tonic Pupil", "Horner''s Syndrome", "Argyll Robertson Pupil", "RAPD"], "correct": 2, "explanation": "Argyll Robertson Pupil is the classic \"accommodates but does not react to light\" pupil, caused by Treponema pallidum (syphilis/tabes dorsalis). Adie''s pupil reacts SLOWLY to light and accommodation, not completely absent. Horner''s shows miosis + ptosis + anhidrosis."}'),
  ('ed1d6b6c-2b','{"options": ["Bowman''s Membrane", "Corneal Stroma", "Dua''s Layer", "Corneal Endothelium"], "correct": 3, "explanation": "The corneal endothelium (single layer of hexagonal cells) is responsible for deturgescence using the Na-K ATPase pump. Ouabain inhibits ATPase. Damage to the endothelium causes permanent, marked corneal swelling (Fuch''s endothelial dystrophy) — far more serious than epithelial damage."}'),
  ('ff37291c-29','{"options": ["CN#3 (Oculomotor)", "CN#4 (Trochlear)", "CN#5 Maxillary division (V2)", "Superior ophthalmic vein"], "correct": 2, "explanation": "The IOF carries CN#5 V2 (maxillary division — specifically the infraorbital nerve, infraorbital artery, inferior ophthalmic vein, and sympathetic nerve). CN#3, CN#4, CN#5 V1, CN#6, and superior ophthalmic vein all pass through the SUPERIOR Orbital Fissure (SOF)."}'),
  ('2ee67aec-2d','{"options": ["The most vascular structure of the ciliary body", "The least vascular structure of the ciliary body", "Adjacent to the posterior aqueous chamber", "Directly continuous with the retina"], "correct": 1, "explanation": "The pars plana is the LEAST vascular structure of the ciliary body (4 mm wide from ora serrata to pars plicata), making it the safest entry site for procedures like vitrectomy. The pars plicata (corona ciliaris) is the MOST vascular structure."}'),
  ('811870b6-2z','{"options": ["CN#2", "CN#3", "CN#4", "CN#6"], "correct": 2, "explanation": "CN#4 (Trochlear nerve) is the only cranial nerve to (1) completely decussate, (2) emerge from the dorsal surface of the brainstem, (3) have the longest intracranial course (75 mm), and (4) be the thinnest (2,150–3,400 nerve fibers). It innervates the contralateral SO."}'),
  ('091073b9-1l','{"options": ["Crystalline lens", "Trabecular meshwork", "Extraocular muscles", "Retina"], "correct": 1, "explanation": "Neural crest gives rise to the trabecular meshwork, the bony orbit, and the optic nerve meninges. The lens comes from surface ectoderm, the EOMs from mesoderm, and the retina from neural ectoderm."}')
)
